INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94173, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "游是人或动物在水里靠身体动作向前移动。", "primary_collocate": null, "pronunciation": "yóu", "ipa": "joʊ˧˥", "syllable_count": 1, "sentences": [{"text": "小鱼在水里游来游去。", "target_word": "游", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他游得很快。", "target_word": "游", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河不宽，我一口气游到了对岸。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸭子在河里慢慢地游。", "target_word": "游", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你能游到对岸吗？", "target_word": "游", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在湖里游了一个小时。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一条大鱼向我这边游过来。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从这边游到那边，只用了两分钟。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水很凉，我只游了一会儿。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗跳进河里，朝岸边游去。", "target_word": "游", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "游了", "label": "体标"}, {"form": "游过", "label": "体标"}, {"form": "游泳", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，人或动物在水中靠身体动作前进，常说游得快、游到对岸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94173, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：“游”指在水里靠身体动作前进。"}, {"text": "有", "is_correct": false, "explanation": "“有”（第三声）与 yóu（第二声）声调不同，意思是“有”。"}, {"text": "又", "is_correct": false, "explanation": "“又”（第四声）与 yóu（第二声）声调不同，意思是“又”。"}, {"text": "悠", "is_correct": false, "explanation": "“悠”（第一声）与 yóu（第二声）声调不同，意思是“悠闲”。"}], "explanations": {"游": "正确：“游”指在水里靠身体动作前进。", "有": "“有”（第三声）与 yóu（第二声）声调不同，意思是“有”。", "又": "“又”（第四声）与 yóu（第二声）声调不同，意思是“又”。", "悠": "“悠”（第一声）与 yóu（第二声）声调不同，意思是“悠闲”。"}, "sentence_index": null, "correct_answer": "游"}, "level_3": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：“游来游去”形容小鱼在水中往来移动，“游”符合句意。"}, {"text": "跑", "is_correct": false, "explanation": "语义：小鱼在水里不能“跑”，与“在水里”不合。"}, {"text": "飞", "is_correct": false, "explanation": "语义：鱼不会“飞”，与“小鱼在水里”不合。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”不接“在水里”来表示移动，不说“站来站去”形容小鱼。"}], "explanations": {"游": "正确：“游来游去”形容小鱼在水中往来移动，“游”符合句意。", "跑": "语义：小鱼在水里不能“跑”，与“在水里”不合。", "飞": "语义：鱼不会“飞”，与“小鱼在水里”不合。", "站": "搭配：“站”不接“在水里”来表示移动，不说“站来站去”形容小鱼。"}, "sentence_index": 0, "correct_answer": "游"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "树叶在河里慢慢地游。", "explanation": "这里应该用〈漂〉。树叶随水流漂动，不会主动游动。"}, {"text": "石块在河里慢慢地游。", "explanation": "这里应该用〈沉〉。石块在水里会下沉，不会游动。"}, {"text": "我的电脑游得很快。", "explanation": "这里应该用〈运行〉。“游”指在水里前进，电脑不能游，应说“运行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94173, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：“游”指在水里靠身体动作前进。"}, {"text": "友", "is_correct": false, "explanation": "“友”（yǒu，第三声）与 yóu（第二声）声调不同，意思是“朋友”。"}, {"text": "右", "is_correct": false, "explanation": "“右”（第四声）与 yóu（第二声）声调不同，意思是“右边”。"}, {"text": "优", "is_correct": false, "explanation": "“优”（yōu，第一声）与 yóu（第二声）声调不同，意思是“优秀”。"}, {"text": "忧", "is_correct": false, "explanation": "“忧”（yōu，第一声）与 yóu（第二声）声调不同，意思是“忧愁”。"}], "explanations": {"游": "正确：“游”指在水里靠身体动作前进。", "友": "“友”（yǒu，第三声）与 yóu（第二声）声调不同，意思是“朋友”。", "右": "“右”（第四声）与 yóu（第二声）声调不同，意思是“右边”。", "优": "“优”（yōu，第一声）与 yóu（第二声）声调不同，意思是“优秀”。", "忧": "“忧”（yōu，第一声）与 yóu（第二声）声调不同，意思是“忧愁”。"}, "sentence_index": null, "correct_answer": "游"}, "level_3": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：大鱼在水中向我这边移动，应说“游过来”。"}, {"text": "爬", "is_correct": false, "explanation": "语义：大鱼生活在水里，不能“爬过来”。"}, {"text": "走", "is_correct": false, "explanation": "语义：鱼在水里不走路，“走过来”与“在水里”不合。"}, {"text": "坐", "is_correct": false, "explanation": "语义：“坐过来”指人坐着移动或过来坐下，大鱼在水里不能“坐过来”。"}], "explanations": {"游": "正确：大鱼在水中向我这边移动，应说“游过来”。", "爬": "语义：大鱼生活在水里，不能“爬过来”。", "走": "语义：鱼在水里不走路，“走过来”与“在水里”不合。", "坐": "语义：“坐过来”指人坐着移动或过来坐下，大鱼在水里不能“坐过来”。"}, "sentence_index": 6, "correct_answer": "游"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车朝城里游去。", "explanation": "这里应该用〈开〉。汽车在陆地上行驶，不能用“游”。"}, {"text": "小鸟朝树林游去。", "explanation": "这里应该用〈飞〉。鸟通常在空中飞，句中的动作不是在水里前进。"}, {"text": "我们在书桌上游了一下午。", "explanation": "这里应该用〈写〉。“游”不能表示在书桌上写字，句中的动作是伏案写作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在湖里游着一个小时。", "corrected_sentence": "他在湖里游了一个小时。", "error_description": "错误：“游着一个小时”。正确：“游了一个小时”。“游”是动作动词，表示做完一段动作的时长用“了”；“着”多表示正在进行或保持的状态，直接接时长不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头大鲸鱼游很快。", "corrected_sentence": "这头大鲸鱼游得很快。", "error_description": "错误：“游很快”。正确：“游得很快”。动词与程度补语之间要用“得”连接，漏掉“得”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
