INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为游览、观光或消遣而到处走动。", "primary_collocate": null, "pronunciation": "yóu", "ipa": "joʊ˧˥", "syllable_count": 1, "sentences": [{"text": "我们花了三天，把西湖游了一遍。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一家人去云南游了一个星期。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "假期里，我们去杭州游了三天。", "target_word": "游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去西湖游了一天。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人游遍了半个中国。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想先游长城，再去吃烤鸭。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暑假里，我们游了很多古城。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在公园里游了一圈。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节的时候，我们把黄山游了一圈。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来北京的外国人都想游故宫。", "target_word": "游", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "游了", "label": "体标"}, {"form": "游过", "label": "体标"}, {"form": "游泳", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，为游览观光或消遣而到各地走动，常说游西湖、游遍中国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：“游”在此指闲逛、游览。"}, {"text": "有", "is_correct": false, "explanation": "“有”（第三声）与 yóu（第二声）声调不同，意思是“有”。"}, {"text": "幽", "is_correct": false, "explanation": "“幽”（yōu，第一声）与 yóu（第二声）声调不同，意思是“幽静”。"}, {"text": "幼", "is_correct": false, "explanation": "“幼”（第四声）与 yóu（第二声）声调不同，意思是“幼小”。"}], "explanations": {"游": "正确：“游”在此指闲逛、游览。", "有": "“有”（第三声）与 yóu（第二声）声调不同，意思是“有”。", "幽": "“幽”（yōu，第一声）与 yóu（第二声）声调不同，意思是“幽静”。", "幼": "“幼”（第四声）与 yóu（第二声）声调不同，意思是“幼小”。"}, "sentence_index": null, "correct_answer": "游"}, "level_3": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：“游”指游览、观光，“把西湖游了一遍”即逛遍了西湖。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭，不能指游览，“把西湖擦了一遍”句意不通。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除，不能指游览，“把西湖拆了一遍”句意不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，不能指游览，“把西湖烧了一遍”句意不通。"}], "explanations": {"游": "正确：“游”指游览、观光，“把西湖游了一遍”即逛遍了西湖。", "擦": "语义：“擦”指擦拭，不能指游览，“把西湖擦了一遍”句意不通。", "拆": "语义：“拆”指拆除，不能指游览，“把西湖拆了一遍”句意不通。", "烧": "语义：“烧”指燃烧或加热，不能指游览，“把西湖烧了一遍”句意不通。"}, "sentence_index": 0, "correct_answer": "游"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都去公司游。", "explanation": "这里应该用〈上班〉。“游”指游览或闲逛，不能指去公司工作。"}, {"text": "我们在餐厅游了一顿饭。", "explanation": "这里应该用〈吃〉。“游”指游览或闲逛，不能与“一顿饭”搭配。"}, {"text": "这些书在书架上游了很久。", "explanation": "这里应该用〈放〉。书是物品，不能“游”，应说“放在书架上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94174, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：“游”在此指闲逛、游览。"}, {"text": "友", "is_correct": false, "explanation": "“友”（yǒu，第三声）与 yóu（第二声）声调不同，意思是“朋友”。"}, {"text": "悠", "is_correct": false, "explanation": "“悠”（yōu，第一声）与 yóu（第二声）声调不同，意思是“悠闲”。"}, {"text": "优", "is_correct": false, "explanation": "“优”（yōu，第一声）与 yóu（第二声）声调不同，意思是“优秀”。"}, {"text": "又", "is_correct": false, "explanation": "“又”（第四声）与 yóu（第二声）声调不同，意思是“又”。"}], "explanations": {"游": "正确：“游”在此指闲逛、游览。", "友": "“友”（yǒu，第三声）与 yóu（第二声）声调不同，意思是“朋友”。", "悠": "“悠”（yōu，第一声）与 yóu（第二声）声调不同，意思是“悠闲”。", "优": "“优”（yōu，第一声）与 yóu（第二声）声调不同，意思是“优秀”。", "又": "“又”（第四声）与 yóu（第二声）声调不同，意思是“又”。"}, "sentence_index": null, "correct_answer": "游"}, "level_3": {"options": [{"text": "游", "is_correct": true, "explanation": "正确：“暑假里，我们游了很多古城”指去古城游览，“游”符合句意。"}, {"text": "攻", "is_correct": false, "explanation": "语义：“攻”是攻打的意思，与“暑假里”的游览不合。"}, {"text": "占", "is_correct": false, "explanation": "语义：“占”是占领的意思，与游览无关。"}, {"text": "围", "is_correct": false, "explanation": "搭配：“围”指包围城池，不用于去古城玩。"}], "explanations": {"游": "正确：“暑假里，我们游了很多古城”指去古城游览，“游”符合句意。", "攻": "语义：“攻”是攻打的意思，与“暑假里”的游览不合。", "占": "语义：“占”是占领的意思，与游览无关。", "围": "搭配：“围”指包围城池，不用于去古城玩。"}, "sentence_index": 6, "correct_answer": "游"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汽车游得很快。", "explanation": "这里应该用〈开〉。“游”不能用来形容汽车行驶，汽车应说“开”。"}, {"text": "他很快游完了作业。", "explanation": "这里应该用〈做〉。“游”指游览或闲逛，不能用于完成作业。"}, {"text": "行李游进了房间。", "explanation": "这里应该用〈搬〉。“游”不能表示搬运行李。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑着自行车游了遍整个云南。", "corrected_sentence": "他骑着自行车游遍了整个云南。", "error_description": "错误：“游了遍”。正确：“游遍了”。“遍”是“游”的结果补语，与“游”紧连，“了”要放在“游遍”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "假期里，我们游着几座古城。", "corrected_sentence": "假期里，我们游了几座古城。", "error_description": "错误：“游着几座古城”。正确：“游了几座古城”。“着”表示持续状态，不能表示已经完成的游览，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
