INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94175, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "炸是东西突然裂开，发出很大的响声。", "primary_collocate": null, "pronunciation": "zhà", "ipa": "ʈʂa˥˩", "syllable_count": 1, "sentences": [{"text": "车胎太热，在路上炸了。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "啤酒瓶放进冰箱，半夜突然炸了。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视机突然炸了一下，吓了我一跳。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯泡一开就炸了，声音很大。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟花在天空炸开，特别好看。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听见厨房里的瓶子炸了。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球吹得太大，一下子炸了。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机电池太热，在桌上炸了。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高压锅炸了，汤洒了一地。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋放进微波炉里，一会儿就炸了。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "炸了", "label": "体标"}, {"form": "炸开", "label": "复合"}, {"form": "爆炸", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西突然裂开并发出很大响声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94175, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：炸 zhà（第四声），表示东西突然裂开并发出很大的响声。"}, {"text": "扎", "is_correct": false, "explanation": "zhā（第一声）与 zhà（第四声）声调不同，意思是扎（如扎针）。"}, {"text": "渣", "is_correct": false, "explanation": "zhā（第一声）与 zhà（第四声）声调不同，意思是渣子。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhà（第四声）声调不同，意思是眨（如眨眼）。"}, {"text": "札", "is_correct": false, "explanation": "zhá（第二声）与 zhà（第四声）声调不同，意思是书信（如信札）。"}], "explanations": {"炸": "正确：炸 zhà（第四声），表示东西突然裂开并发出很大的响声。", "扎": "zhā（第一声）与 zhà（第四声）声调不同，意思是扎（如扎针）。", "渣": "zhā（第一声）与 zhà（第四声）声调不同，意思是渣子。", "眨": "zhǎ（第三声）与 zhà（第四声）声调不同，意思是眨（如眨眼）。", "札": "zhá（第二声）与 zhà（第四声）声调不同，意思是书信（如信札）。"}, "sentence_index": null, "correct_answer": "炸"}, "level_3": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：“车胎太热，在路上炸了”中，“炸”表示突然裂开并发出响声，能正确填入这里。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，车胎不能唱。"}, {"text": "笑", "is_correct": false, "explanation": "语义：车胎没有表情，不会笑，句意不通。"}, {"text": "背", "is_correct": false, "explanation": "搭配：“背”的对象是书包、书本等，车胎不能被背。"}], "explanations": {"炸": "正确：“车胎太热，在路上炸了”中，“炸”表示突然裂开并发出响声，能正确填入这里。", "唱": "搭配：“唱”的对象是歌曲，车胎不能唱。", "笑": "语义：车胎没有表情，不会笑，句意不通。", "背": "搭配：“背”的对象是书包、书本等，车胎不能被背。"}, "sentence_index": 0, "correct_answer": "炸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书突然炸了，声音很大。", "explanation": "〈炸〉指东西突然裂开并发出巨响，书不会这样爆裂，这里应该说〈掉〉，即“这本书突然掉了，声音很大”。"}, {"text": "这块布一用力就炸了。", "explanation": "〈炸〉用于物体突然爆裂，布被扯破应说“撕破”。"}, {"text": "电视机慢慢地炸，一点声音都没有。", "explanation": "〈炸〉指突然爆裂并伴有巨响，与“慢慢地”和“没有声音”相矛盾，这里应该用〈裂开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94175, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：炸 zhà（第四声），表示东西突然裂开并发出很大的响声。"}, {"text": "铡", "is_correct": false, "explanation": "zhá（第二声）与 zhà（第四声）声调不同，意思是铡刀。"}, {"text": "占", "is_correct": false, "explanation": "zhàn（第四声）与 zhà 多了韵尾 n，意思是占有。"}, {"text": "战", "is_correct": false, "explanation": "zhàn（第四声）与 zhà 多了韵尾 n，意思是战斗。"}, {"text": "楂", "is_correct": false, "explanation": "zhā（第一声）与 zhà 声调不同，意思是山楂。"}], "explanations": {"炸": "正确：炸 zhà（第四声），表示东西突然裂开并发出很大的响声。", "铡": "zhá（第二声）与 zhà（第四声）声调不同，意思是铡刀。", "占": "zhàn（第四声）与 zhà 多了韵尾 n，意思是占有。", "战": "zhàn（第四声）与 zhà 多了韵尾 n，意思是战斗。", "楂": "zhā（第一声）与 zhà 声调不同，意思是山楂。"}, "sentence_index": null, "correct_answer": "炸"}, "level_3": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：“气球吹得太大，一下子炸了”中，“炸”表示突然裂开并发出响声，能正确填入这里。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”的主语通常是人或动物，气球不能跳。"}, {"text": "哭", "is_correct": false, "explanation": "语义：气球没有情感，不会哭，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能用于气球。"}], "explanations": {"炸": "正确：“气球吹得太大，一下子炸了”中，“炸”表示突然裂开并发出响声，能正确填入这里。", "跳": "搭配：“跳”的主语通常是人或动物，气球不能跳。", "哭": "语义：气球没有情感，不会哭，句意不通。", "写": "搭配：“写”的对象是文字，不能用于气球。"}, "sentence_index": 6, "correct_answer": "炸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个书架一摇就炸了。", "explanation": "〈炸〉指东西突然裂开，书架摇晃时应该说〈倒〉，不能说“炸”。"}, {"text": "我的毛衣挂在门口，一会儿就炸了。", "explanation": "〈炸〉要求物体突然裂开并发出巨响，毛衣挂着不会这样，应说“毛衣掉了”。"}, {"text": "一块冰放在桌上，一会儿就炸了。", "explanation": "〈炸〉要求物体突然裂开并发出巨响，冰放在桌上不会这样，应说“冰化了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_ve