INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个旧暖水瓶突然开炸了。", "corrected_sentence": "那个旧暖水瓶突然炸开了。", "error_description": "错误形式：“开炸了”。正确形式：“炸开了”。原因：结果补语“开”必须放在动词“炸”之后，语序不能颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饮料瓶冻得太硬，一下子开炸了。", "corrected_sentence": "饮料瓶冻得太硬，一下子炸开了。", "error_description": "错误形式：“开炸了”。正确形式：“炸开了”。原因：结果补语“开”必须放在动词“炸”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
