INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94176, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用炸药等爆炸物破坏。", "primary_collocate": null, "pronunciation": "zhà", "ipa": "ʈʂa˥˩", "syllable_count": 1, "sentences": [{"text": "敌人炸了那座桥。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用火药炸山，修了一条路。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想炸掉那座旧房子。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机把仓库炸了。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用炸药炸了那块大石头。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在山上炸石头，大家别过去。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时，飞机炸了很多房子。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们炸开山洞，救出了里面的人。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了修路，他们炸了半座山。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人炸了半天，终于炸开了那块大石头。", "target_word": "炸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "炸了", "label": "体标"}, {"form": "炸掉", "label": "复合"}, {"form": "爆炸", "label": "复合"}], "register": "中性", "sense_fingerprint": "用炸药炸毁桥、山、房子等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94176, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：炸 zhà（第四声），表示物体爆裂或用爆炸物破坏。"}, {"text": "扎", "is_correct": false, "explanation": "zhā（第一声）与 zhà（第四声）声调不同，意思是扎（如扎针）。"}, {"text": "渣", "is_correct": false, "explanation": "zhā（第一声）与 zhà（第四声）声调不同，意思是渣子。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhà（第四声）声调不同，意思是眨（如眨眼）。"}, {"text": "札", "is_correct": false, "explanation": "zhá（第二声）与 zhà（第四声）声调不同，意思是书信（如信札）。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhà 多了韵尾 n，意思是站立。"}], "explanations": {"炸": "正确：炸 zhà（第四声），表示物体爆裂或用爆炸物破坏。", "扎": "zhā（第一声）与 zhà（第四声）声调不同，意思是扎（如扎针）。", "渣": "zhā（第一声）与 zhà（第四声）声调不同，意思是渣子。", "眨": "zhǎ（第三声）与 zhà（第四声）声调不同，意思是眨（如眨眼）。", "札": "zhá（第二声）与 zhà（第四声）声调不同，意思是书信（如信札）。", "站": "zhàn（第四声）与 zhà 多了韵尾 n，意思是站立。"}, "sentence_index": null, "correct_answer": "炸"}, "level_3": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：“敌人炸了那座桥”中，“炸”表示用爆炸物破坏，能正确填入这里。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃桥。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说喝桥。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，桥不能被唱，句意不通。"}], "explanations": {"炸": "正确：“敌人炸了那座桥”中，“炸”表示用爆炸物破坏，能正确填入这里。", "吃": "搭配：“吃”的对象是食物，不能说吃桥。", "喝": "搭配：“喝”的对象是液体，不能说喝桥。", "唱": "语义：“唱”的对象是歌曲，桥不能被唱，句意不通。"}, "sentence_index": 0, "correct_answer": "炸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书炸了一遍。", "explanation": "〈炸〉指物体爆裂或用爆炸物破坏，不能用于“读书”，应说“他把书读了一遍”。"}, {"text": "妈妈把衣服炸干净了。", "explanation": "〈炸〉指用爆炸物破坏，洗衣服应该用〈洗〉，即“妈妈把衣服洗干净了”。"}, {"text": "我的作业炸了，老师很高兴。", "explanation": "〈炸〉指物体突然爆裂，“作业”不会爆裂，这里应该用〈完成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94176, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：炸 zhà（第四声），表示物体爆裂或用爆炸物破坏。"}, {"text": "铡", "is_correct": false, "explanation": "zhá（第二声）与 zhà（第四声）声调不同，意思是铡刀。"}, {"text": "占", "is_correct": false, "explanation": "zhàn（第四声）与 zhà 多了韵尾 n，意思是占有。"}, {"text": "战", "is_correct": false, "explanation": "zhàn（第四声）与 zhà 多了韵尾 n，意思是战斗。"}, {"text": "楂", "is_correct": false, "explanation": "zhā（第一声）与 zhà 声调不同，意思是山楂。"}], "explanations": {"炸": "正确：炸 zhà（第四声），表示物体爆裂或用爆炸物破坏。", "铡": "zhá（第二声）与 zhà（第四声）声调不同，意思是铡刀。", "占": "zhàn（第四声）与 zhà 多了韵尾 n，意思是占有。", "战": "zhàn（第四声）与 zhà 多了韵尾 n，意思是战斗。", "楂": "zhā（第一声）与 zhà 声调不同，意思是山楂。"}, "sentence_index": null, "correct_answer": "炸"}, "level_3": {"options": [{"text": "炸", "is_correct": true, "explanation": "正确：“飞机炸了很多房子”中，“炸”表示用爆炸物破坏，能正确填入这里。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等物品，不能说洗房子。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”是描绘，飞机不会画房子，句意不通。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”的对象是花草等，不能说浇房子。"}], "explanations": {"炸": "正确：“飞机炸了很多房子”中，“炸”表示用爆炸物破坏，能正确填入这里。", "洗": "搭配：“洗”的对象是衣物等物品，不能说洗房子。", "画": "语义：“画”是描绘，飞机不会画房子，句意不通。", "浇": "搭配：“浇”的对象是花草等，不能说浇房子。"}, "sentence_index": 6, "correct_answer": "炸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那张纸炸成了两半。", "explanation": "〈炸〉指物体爆裂或用爆炸物破坏，把纸撕开应该用〈撕〉，不能说“炸成两半”。"}, {"text": "他用凿子炸开了石头。", "explanation": "〈炸〉需要用爆炸物，用凿子应该说〈凿〉，不能说“炸开”。"}, {"text": "他把作文炸完了。", "explanation": "〈炸〉指爆裂或用爆炸物破坏，写作文应该用〈写〉，不能说“炸完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDE