INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人用炸药炸了开一块石头。", "corrected_sentence": "工人用炸药炸开了一块石头。", "error_description": "错误形式：“炸了开”。正确形式：“炸开了”。原因：结果补语“开”必须紧跟在动词“炸”之后，“了”放在补语之后，不能夹在动词和补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把那座旧房子平炸了。", "corrected_sentence": "工人把那座旧房子炸平了。", "error_description": "错误形式：“平炸了”。正确形式：“炸平了”。原因：结果补语“平”必须放在动词“炸”之后，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
