INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94177, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "为此是说因为刚才说的这件事。", "primary_collocate": null, "pronunciation": "wèi cǐ", "ipa": "weɪ˥˩ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师明天要考试，为此我们都很紧张。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去中国工作，为此每天学汉语。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛快到了，为此大家天天练习。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈病了，我为此请了三天假。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要搬家，为此开了很多会。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想买房子，为此存了很多钱。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试很重要，我为此准备了很久。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当医生，为此努力学习。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司亏损严重，为此董事会召开了紧急会议。", "target_word": "为此", "complexity_tier": "T3", "furigana": "wèi cǐ", "sentence_source": "generated"}, {"text": "他丢了手机，为此很难过。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為此", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为此：为了或因为前面所说的这件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94177, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为此", "is_correct": true, "explanation": "为此（wèi cǐ）：因为前面所说的这件事。"}, {"text": "位次", "is_correct": false, "explanation": "位次（wèi cì）：第二音节声调不同（cǐ 与 cì），意思是位置的次序。"}, {"text": "谓词", "is_correct": false, "explanation": "谓词（wèi cí）：第二音节声调不同（cǐ 与 cí），意思是语法中的谓语词。"}, {"text": "伪词", "is_correct": false, "explanation": "伪词（wěi cí）：两个音节声调都不同（wěi 与 wèi，cí 与 cǐ），意思是假的、不存在的词。"}], "explanations": {"为此": "为此（wèi cǐ）：因为前面所说的这件事。", "位次": "位次（wèi cì）：第二音节声调不同（cǐ 与 cì），意思是位置的次序。", "谓词": "谓词（wèi cí）：第二音节声调不同（cǐ 与 cí），意思是语法中的谓语词。", "伪词": "伪词（wěi cí）：两个音节声调都不同（wěi 与 wèi，cí 与 cǐ），意思是假的、不存在的词。"}, "sentence_index": null, "correct_answer": "为此"}, "level_3": {"options": [{"text": "为此", "is_correct": true, "explanation": "为此：承接前面的考试，表示因为这件事，我们都很紧张。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经」表示已经发生，与句中「明天要考试」的将来时间矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」表示不久前，与「明天」冲突，句子不通。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：「亲自」修饰亲身做的动作，不能修饰「我们都很紧张」这种心理状态。"}], "explanations": {"为此": "为此：承接前面的考试，表示因为这件事，我们都很紧张。", "已经": "语义：「已经」表示已经发生，与句中「明天要考试」的将来时间矛盾。", "刚刚": "语义：「刚刚」表示不久前，与「明天」冲突，句子不通。", "亲自": "搭配：「亲自」修饰亲身做的动作，不能修饰「我们都很紧张」这种心理状态。"}, "sentence_index": 0, "correct_answer": "为此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太冷，为此水管冻住了。", "explanation": "这里应该用〈所以〉。“为此”表示人因为前面的事而做出某种反应（做法或心情），不能引出水管冻住这种物理上的自然结果；表示自然结果要用“所以”。"}, {"text": "他没有带伞，为此淋湿了。", "explanation": "这里应该用〈因此〉。“淋湿了”是没带伞的自然后果，不是人为此做出的反应，不能用“为此”引出；表示自然结果要用“因此”。"}, {"text": "为此堵车，我迟到了。", "explanation": "这里应该用〈因为〉。为此只能指代前文已经说过的事，不能引出新的原因；引出原因要用因为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为此", "is_correct": true, "explanation": "为此：承接前面说的考试很重要，表示因为这件事，我准备了很久。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」表示不久前，与「准备了很久」的持续时间矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示即刻发生，与「准备了很久」的长时间过程冲突。"}, {"text": "极其", "is_correct": false, "explanation": "搭配：「极其」修饰形容词，不能修饰「准备」这样的动作。"}], "explanations": {"为此": "为此：承接前面说的考试很重要，表示因为这件事，我准备了很久。", "刚刚": "语义：「刚刚」表示不久前，与「准备了很久」的持续时间矛盾。", "马上": "语义：「马上」表示即刻发生，与「准备了很久」的长时间过程冲突。", "极其": "搭配：「极其」修饰形容词，不能修饰「准备」这样的动作。"}, "sentence_index": 6, "correct_answer": "为此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他得了第一名，为此可见，他很努力。", "explanation": "这里应该用〈由此〉。为此表示为某事而采取的做法，不能用来从前文推出结论；推断要用由此可见。"}, {"text": "我们到了车站，为此火车已经开走了。", "explanation": "这里应该用〈此时〉。此时表示同一时刻的情况，为此表示因果；我们到站不是火车开走的原因。"}, {"text": "他会说英语，为此还会说法语。", "explanation": "这里应该用〈此外〉。此外表示补充，为此表示因果；会说法语不是因为会说英语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子生病了，我为此了请一天假。", "corrected_sentence": "孩子生病了，我为此请了一天假。", "error_description": "错误在「请」和「了」的顺序。「了」应紧跟动词「请」，说「我为此请了一天假」，不能说「我为此了请一天假」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹要参加钢琴比赛，我为此为了每天陪她练琴。", "corrected_sentence": "妹妹要参加钢琴比赛，我为此每天陪她练琴。", "error_description": "错误：「为此」后多加了「为了」，两者重复表达目的，只保留「为此」即可。正确：应说「我为此每天陪她练琴」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
