INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94178, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示因为前面所说的事情。", "primary_collocate": null, "pronunciation": "wèi cǐ", "ipa": "weɪ˥˩ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司出了问题，为此老板很生气。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要改时间，为此通知了所有家长。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格涨了很多，为此公司决定降低成本。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越来越冷，为此我买了新衣服。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天没来上课，为此老师打了电话。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子太旧了，为此他们决定搬家。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近工作很忙，为此他很少回家。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的比赛输了，为此队员们练得更多。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友要来看我，为此我打扫了房间。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁坏了，为此上班的人都走路去。", "target_word": "为此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為此", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为此：连接前后两句，表示因为前面说的事情而有后面的结果或行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为此", "is_correct": true, "explanation": "为此（wèi cǐ）：表示因为前面所说的事情，有后面的结果。"}, {"text": "位次", "is_correct": false, "explanation": "位次（wèi cì）：第二音节声调不同（cǐ 与 cì），意思是位置的次序。"}, {"text": "谓词", "is_correct": false, "explanation": "谓词（wèi cí）：第二音节声调不同（cǐ 与 cí），意思是语法中的谓语词。"}, {"text": "唯此", "is_correct": false, "explanation": "唯此（wéi cǐ）：第一音节声调不同（wéi 与 wèi），意思是只有这一个。"}], "explanations": {"为此": "为此（wèi cǐ）：表示因为前面所说的事情，有后面的结果。", "位次": "位次（wèi cì）：第二音节声调不同（cǐ 与 cì），意思是位置的次序。", "谓词": "谓词（wèi cí）：第二音节声调不同（cǐ 与 cí），意思是语法中的谓语词。", "唯此": "唯此（wéi cǐ）：第一音节声调不同（wéi 与 wèi），意思是只有这一个。"}, "sentence_index": null, "correct_answer": "为此"}, "level_3": {"options": [{"text": "为此", "is_correct": true, "explanation": "为此：承接前面的问题，表示因为这件事，老板很生气。"}, {"text": "否则", "is_correct": false, "explanation": "语义：「否则」表示假设不然的结果，与句中已发生的「出了问题」不合。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：「虽然」需与「但是」或「却」配合，单独使用时句子不完整。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：「即使」需与「也」配合，单独使用时句子不完整。"}], "explanations": {"为此": "为此：承接前面的问题，表示因为这件事，老板很生气。", "否则": "语义：「否则」表示假设不然的结果，与句中已发生的「出了问题」不合。", "虽然": "搭配：「虽然」需与「但是」或「却」配合，单独使用时句子不完整。", "即使": "搭配：「即使」需与「也」配合，单独使用时句子不完整。"}, "sentence_index": 0, "correct_answer": "为此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，为此没考好。", "explanation": "这里应该用〈但是〉。为此表示因果，不能表示转折；这句说成因为努力而没考好，与原意相反。"}, {"text": "为此天气不好，比赛取消了。", "explanation": "这里应该用〈由于〉。为此只能指代前文已经说过的事，不能引出新的原因；引出原因要用由于。"}, {"text": "我吃完了饭，为此去了图书馆。", "explanation": "这里应该用〈然后〉。为此表示因果，不能表示两件事的先后顺序；只说明先后顺序要用然后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为此", "is_correct": true, "explanation": "为此：承接前面工作很忙的原因，表示因此他很少回家。"}, {"text": "要不然", "is_correct": false, "explanation": "语义：「要不然」表示另一种情况，与句中「工作很忙」的因果关系不合。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：「尽管」需与「仍然」「还是」等配合，单独使用时句子不完整。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：「而是」需用于「不是……而是……」的格式，单独使用时不合语境。"}], "explanations": {"为此": "为此：承接前面工作很忙的原因，表示因此他很少回家。", "要不然": "语义：「要不然」表示另一种情况，与句中「工作很忙」的因果关系不合。", "尽管": "搭配：「尽管」需与「仍然」「还是」等配合，单独使用时句子不完整。", "而是": "搭配：「而是」需用于「不是……而是……」的格式，单独使用时不合语境。"}, "sentence_index": 6, "correct_answer": "为此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我以为他会来，为此他没来。", "explanation": "这里应该用〈反而〉。为此表示因此而做某事，不能表示出乎意料的相反结果；相反结果要用反而。"}, {"text": "他喜欢运动，为此还喜欢画画。", "explanation": "这里应该用〈另外〉。另外表示补充，为此表示因果；喜欢画画不是因为喜欢运动。"}, {"text": "这次比赛他进了决赛，为此可见他很努力。", "explanation": "这里应该用〈由此〉。为此不能用于从前文推出结论；推断要用由此可见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气越来越热，我为此了买一个新风扇。", "corrected_sentence": "天气越来越热，我为此买了一个新风扇。", "error_description": "错误：「了」放在了「为此」和动词之间，成了「为此了买」。正确：「了」应放在动词后，写作「我为此买了一个新风扇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气越来越冷，为此所以我买了一件大衣。", "corrected_sentence": "天气越来越冷，为此我买了一件大衣。", "error_description": "错误：「为此」已表示因果，前面再加「所以」造成因果重复。正确：只用「为此」，写作「天气越来越冷，为此我买了一件大衣」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
