INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94179, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "热烈是场面或气氛很热闹、很高涨。", "primary_collocate": null, "pronunciation": "rè liè", "ipa": "ɻɤ˥˩ liɛ˥˩", "syllable_count": 2, "sentences": [{"text": "大家热烈欢迎新同学。", "target_word": "热烈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会场里的气氛很热烈。", "target_word": "热烈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "观众给了他热烈的掌声。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会上，大家热烈地唱歌跳舞。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场里有很多人热烈欢迎球队回国。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，观众热烈地鼓掌欢呼。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婚礼上的气氛非常热烈，客人们又唱又跳。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在热烈的掌声中走上了舞台。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们热烈欢迎着从国外回来的老师。", "target_word": "热烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年晚会上，音乐一响，现场的气氛就变得热烈起来。", "target_word": "热烈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱烈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：场面气氛热闹、欢快（热烈欢迎、热烈的掌声）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音、不喧闹，与“热烈欢迎”的热闹场面相反。"}, {"text": "缓慢", "is_correct": false, "explanation": "语义：“缓慢”说速度慢，与“欢迎”的热烈语气不合。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”表示没有声音、冷清，不与“欢迎”搭配。"}, {"text": "热烈", "is_correct": true, "explanation": "“热烈”表示热情、热闹，与“欢迎”搭配，符合句意。"}], "explanations": {"安静": "语义：“安静”指没有声音、不喧闹，与“热烈欢迎”的热闹场面相反。", "缓慢": "语义：“缓慢”说速度慢，与“欢迎”的热烈语气不合。", "寂静": "搭配：“寂静”表示没有声音、冷清，不与“欢迎”搭配。", "热烈": "“热烈”表示热情、热闹，与“欢迎”搭配，符合句意。"}, "sentence_index": 0, "correct_answer": "热烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到消息，他热烈地哭了起来。", "explanation": "这里应该用〈激动〉。“热烈”多形容场面、气氛，不用来描写一个人哭的样子。"}, {"text": "晚会上，大家热烈地睡着了。", "explanation": "这里应该用〈安静〉。“热烈”形容气氛或情绪高涨，与“睡着”的安静状态相反，意思矛盾。"}, {"text": "今天的天气很热烈。", "explanation": "这里应该用〈炎热〉。“热烈”形容场面、气氛或情绪，不用于描写天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没有人、不热闹，与“客人们又唱又跳”相矛盾。"}, {"text": "沉闷", "is_correct": false, "explanation": "语义：“沉闷”指气氛压抑，与“客人们又唱又跳”相矛盾。"}, {"text": "冷寂", "is_correct": false, "explanation": "语义：“冷寂”指冷清寂静，与“客人们又唱又跳”的热闹场面相矛盾。"}, {"text": "热烈", "is_correct": true, "explanation": "“热烈”形容气氛热闹，与“客人们又唱又跳”相符。"}], "explanations": {"冷清": "语义：“冷清”指没有人、不热闹，与“客人们又唱又跳”相矛盾。", "沉闷": "语义：“沉闷”指气氛压抑，与“客人们又唱又跳”相矛盾。", "冷寂": "语义：“冷寂”指冷清寂静，与“客人们又唱又跳”的热闹场面相矛盾。", "热烈": "“热烈”形容气氛热闹，与“客人们又唱又跳”相符。"}, "sentence_index": 6, "correct_answer": "热烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大楼的规模很热烈。", "explanation": "这里应该用〈巨大〉。“热烈”形容气氛、场面，不用于描写规模。"}, {"text": "现场的人数变得热烈起来了。", "explanation": "这里应该用〈增多〉。“热烈”不用于描述人数的变化。"}, {"text": "这段山路很热烈。", "explanation": "这里应该用〈陡峭〉。“热烈”不用于描写山路的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "体育馆里的气氛很热烈地，大家一起大声呐喊。", "corrected_sentence": "体育馆里的气氛很热烈，大家一起大声呐喊。", "error_description": "错误：“热烈”在这里作谓语，后面不能加状语标记“地”。“地”只用在修饰动词的状语后，应去掉“地”，说“气氛很热烈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演唱会结束后，场面一下子热烈下来了。", "corrected_sentence": "演唱会结束后，场面一下子热烈起来了。", "error_description": "错误：补语用错。表示气氛由平静转为活跃，应说“热烈起来”，不说“热烈下来”。“下来”一般表示由高向低、由动到静，与句意不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
