INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94180, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "情绪兴奋激动，气氛活跃。", "primary_collocate": null, "pronunciation": "rè liè", "ipa": "ɻɤ˥˩ liɛ˥˩", "syllable_count": 2, "sentences": [{"text": "大家讨论得很热烈。", "target_word": "热烈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们热烈地讨论这个问题。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们热烈讨论明天的比赛。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会上，大家的发言很热烈。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个消息，大家的反应非常热烈。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的问题引起了同学们的热烈讨论。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们热烈地交谈了一个下午。", "target_word": "热烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人为了这个问题热烈地争论着。", "target_word": "热烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影在年轻人中引起了热烈的反响。", "target_word": "热烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到旅行的话题，她的情绪一下子变得很热烈。", "target_word": "热烈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱烈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：情绪兴奋激动、讨论反应活跃（讨论热烈、反响热烈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指态度不热情，与“讨论”的积极状态相矛盾。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“沉默”描述人不说话，不用来说讨论的程度。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”指没有声音，不用来描述讨论的热烈程度。"}, {"text": "热烈", "is_correct": true, "explanation": "“热烈”形容讨论时情绪兴奋、反应活跃，符合句意。"}], "explanations": {"冷淡": "语义：“冷淡”指态度不热情，与“讨论”的积极状态相矛盾。", "沉默": "搭配：“沉默”描述人不说话，不用来说讨论的程度。", "寂静": "搭配：“寂静”指没有声音，不用来描述讨论的热烈程度。", "热烈": "“热烈”形容讨论时情绪兴奋、反应活跃，符合句意。"}, "sentence_index": 0, "correct_answer": "热烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天下午的天气很热烈。", "explanation": "这里应该用〈炎热〉。“热烈”形容情绪或反应活跃，不用于描写天气。"}, {"text": "会上，大家热烈地打了一个喷嚏。", "explanation": "这里应该用〈突然〉。打喷嚏是瞬间的生理反应，不能用“热烈”来描写；“热烈”只用于形容情绪或反应的活跃。"}, {"text": "草原上的狮子很热烈。", "explanation": "这里应该用〈凶猛〉。“热烈”不用于形容动物的性情或样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”形容环境没有声音，不能修饰“交谈”这样的动作。"}, {"text": "炎热", "is_correct": false, "explanation": "搭配：“炎热”形容天气很热，不能用来修饰“交谈”。"}, {"text": "呆滞", "is_correct": false, "explanation": "搭配：“呆滞”多形容眼神、表情，不用来描述交谈。"}, {"text": "热烈", "is_correct": true, "explanation": "“热烈”形容交谈时情绪兴奋、投入，与“交谈了一个下午”相符。"}], "explanations": {"寂静": "搭配：“寂静”形容环境没有声音，不能修饰“交谈”这样的动作。", "炎热": "搭配：“炎热”形容天气很热，不能用来修饰“交谈”。", "呆滞": "搭配：“呆滞”多形容眼神、表情，不用来描述交谈。", "热烈": "“热烈”形容交谈时情绪兴奋、投入，与“交谈了一个下午”相符。"}, "sentence_index": 6, "correct_answer": "热烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房间很热烈。", "explanation": "这里应该用〈宽敞〉。“热烈”不用于描写房间的大小。"}, {"text": "他的脚步很热烈。", "explanation": "这里应该用〈沉稳〉。“热烈”不用于描写脚步。"}, {"text": "这次建设的规模很热烈。", "explanation": "这里应该用〈巨大〉。“热烈”不用于描写规模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里的讨论很热烈得，大家都在发言。", "corrected_sentence": "会议室里的讨论很热烈，大家都在发言。", "error_description": "错误：“很热烈”后多加了“得”，结构助词误用，句子不完整。应去掉“得”，改为“讨论很热烈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们热烈的地讨论了新的方案。", "corrected_sentence": "我们热烈地讨论了新的方案。", "error_description": "“热烈”作状语修饰动词，后面应接“地”，不能用“的”。“热烈的地”误用了结构助词，应改为“热烈地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94181, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新鲜", "is_correct": true, "explanation": "反义：新鲜指未变质，烂指腐败变质，二者相对。"}, {"text": "聪明", "is_correct": false, "explanation": "与“烂”没有反义关系，二者不构成对立。"}, {"text": "高兴", "is_correct": false, "explanation": "与“烂”没有反义关系，二者不构成对立。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“烂”没有反义关系，二者不构成对立。"}], "correct_answer": "新鲜", "explanations": {"新鲜": "反义：新鲜指未变质，烂指腐败变质，二者相对。", "聪明": "与“烂”没有反义关系，二者不构成对立。", "高兴": "与“烂”没有反义关系，二者不构成对立。", "漂亮": "与“烂”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
