INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94182, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "因腐败或煮炖而变得松软；破碎，不整齐。", "primary_collocate": null, "pronunciation": "làn", "ipa": "lan˥˩", "syllable_count": 1, "sentences": [{"text": "西红柿放太久，都烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋很烂，鞋底都破了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书太旧，纸都烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉炖得很烂，老人也能吃。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一夜，路上的叶子都烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件衣服又脏又烂，别穿了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的木头都烂了，不能用了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把烂菜叶扔进了垃圾桶。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板泡在水里，已经烂了。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面条煮得太烂，我不想吃。", "target_word": "烂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烂了", "label": "体标"}, {"form": "腐烂", "label": "复合"}, {"form": "破烂", "label": "复合"}], "register": "中性", "sense_fingerprint": "腐败或煮炖松软；破碎不整齐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '980ebab6-654b-45aa-acc6-731014f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94182, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烂", "is_correct": true, "explanation": "烂（làn，第四声）：因腐败而变软，即本词的词义。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是蓝色。"}, {"text": "懒", "is_correct": false, "explanation": "lǎn（第三声）与 làn（第四声）声调不同，意思是懒惰。"}, {"text": "浪", "is_correct": false, "explanation": "làng 与 làn 韵母不同（ang／an），意思是波浪。"}, {"text": "拦", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是阻拦。"}], "explanations": {"烂": "烂（làn，第四声）：因腐败而变软，即本词的词义。", "蓝": "lán（第二声）与 làn（第四声）声调不同，意思是蓝色。", "懒": "lǎn（第三声）与 làn（第四声）声调不同，意思是懒惰。", "浪": "làng 与 làn 韵母不同（ang／an），意思是波浪。", "拦": "lán（第二声）与 làn（第四声）声调不同，意思是阻拦。"}, "sentence_index": null, "correct_answer": "烂"}, "level_3": {"options": [{"text": "烂", "is_correct": true, "explanation": "正确：西红柿放久后腐败变软，符合语境。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：放太久与“新鲜”矛盾，西红柿不会因放久而变新鲜。"}, {"text": "干净", "is_correct": false, "explanation": "语义：西红柿放久不会变得“干净”，与语境不符。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”说光线或颜色，不能用来形容西红柿的状态。"}], "explanations": {"烂": "正确：西红柿放久后腐败变软，符合语境。", "新鲜": "语义：放太久与“新鲜”矛盾，西红柿不会因放久而变新鲜。", "干净": "语义：西红柿放久不会变得“干净”，与语境不符。", "亮": "搭配：“亮”说光线或颜色，不能用来形容西红柿的状态。"}, "sentence_index": 0, "correct_answer": "烂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天太热，冰箱里的冰都烂了。", "explanation": "这里应该用〈融化〉。烂指东西因腐败而变软，冰受热变成水要用融化。"}, {"text": "这瓶白酒没盖紧，一夜之间就烂光了。", "explanation": "这里应该用〈挥发〉。烂指东西腐败变软，酒精从液体飘散到空气中要用挥发。"}, {"text": "天黑了，路灯一盏一盏地烂了。", "explanation": "这里应该用〈灭〉。烂指东西腐败、破碎或煮得松软，灯光熄掉要用灭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94182, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "烂", "is_correct": true, "explanation": "烂（làn，第四声）：因腐败而变软，即本词的词义。"}, {"text": "难", "is_correct": false, "explanation": "nàn（第四声）与 làn 声母不同（n／l），意思是灾难。"}, {"text": "缆", "is_correct": false, "explanation": "lǎn（第三声）与 làn（第四声）声调不同，意思是缆绳。"}, {"text": "栏", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是栏杆。"}, {"text": "兰", "is_correct": false, "explanation": "lán（第二声）与 làn（第四声）声调不同，意思是兰花。"}], "explanations": {"烂": "烂（làn，第四声）：因腐败而变软，即本词的词义。", "难": "nàn（第四声）与 làn 声母不同（n／l），意思是灾难。", "缆": "lǎn（第三声）与 làn（第四声）声调不同，意思是缆绳。", "栏": "lán（第二声）与 làn（第四声）声调不同，意思是栏杆。", "兰": "lán（第二声）与 làn（第四声）声调不同，意思是兰花。"}, "sentence_index": null, "correct_answer": "烂"}, "level_3": {"options": [{"text": "烂", "is_correct": true, "explanation": "正确：木头腐败变软，符合“不能用了”的语境。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”与“不能用了”矛盾，结实的木头仍可以用。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”不能推出“不能用了”，与后半句矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”说光线或颜色，不能用来形容木头的状态。"}], "explanations": {"烂": "正确：木头腐败变软，符合“不能用了”的语境。", "结实": "语义：“结实”与“不能用了”矛盾，结实的木头仍可以用。", "新": "语义：“新”不能推出“不能用了”，与后半句矛盾。", "亮": "搭配：“亮”说光线或颜色，不能用来形容木头的状态。"}, "sentence_index": 6, "correct_answer": "烂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "炉子里的铁块都烂了。", "explanation": "这里应该用〈熔化〉。烂指东西腐败变软，金属在高温下变成液体要用熔化。"}, {"text": "把糖放进热水里，很快就烂光了。", "explanation": "这里应该用〈溶解〉。烂指东西腐坏，糖在水中化开要用溶解。"}, {"text": "太阳出来后，山上的雾慢慢烂掉了。", "explanation": "这里应该用〈消散〉。烂指东西腐败，雾逐渐散去要用消散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = E