INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94186, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把甲看作乙；认作。", "primary_collocate": null, "pronunciation": "dāng chéng", "ipa": "taŋ˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "别把我的话当成玩笑。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直把我当成好朋友。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把她当成了你，真不好意思。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把他当成偶像。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把老师的批评当成了帮助。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是把我当成小孩子。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要把这件事当成小事。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把陌生人当成了同学，跟他打了招呼。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这家店当成自己的家。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把我当成外人，有话直接说。", "target_word": "当成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当成了", "label": "体标"}, {"form": "當成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把某人或某事看作、认作另一种人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb3a0d9-08c8-4e7f-bd40-b28ca5c44dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当成", "is_correct": true, "explanation": "正确：“当成”表示把我的话认作玩笑，与“别把……”的语境相符。"}, {"text": "切成", "is_correct": false, "explanation": "语义：“切成”指分割成块，与“我的话”的抽象意义不符。"}, {"text": "打扮成", "is_correct": false, "explanation": "搭配：“打扮成”用于装扮外表，不能用于说话的内容。"}, {"text": "冒充", "is_correct": false, "explanation": "配价：“冒充”需要以人或身份为对象，话不能冒充玩笑。"}], "explanations": {"当成": "正确：“当成”表示把我的话认作玩笑，与“别把……”的语境相符。", "切成": "语义：“切成”指分割成块，与“我的话”的抽象意义不符。", "打扮成": "搭配：“打扮成”用于装扮外表，不能用于说话的内容。", "冒充": "配价：“冒充”需要以人或身份为对象，话不能冒充玩笑。"}, "sentence_index": 0, "correct_answer": "当成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把黄豆当成了磨碎。", "explanation": "这里应该用〈磨成〉。“当成”后要接名词，不能接动作结果“磨碎”；把黄豆磨成豆浆要用〈磨成〉。"}, {"text": "工人把泥土当成了烧透。", "explanation": "这里应该用〈烧成〉。“当成”后要接名词，不能接动作结果“烧透”；泥土烧成瓷器要用〈烧成〉。"}, {"text": "我把这张纸当成了涂好。", "explanation": "这里应该用〈涂成〉。“当成”后要接名词，不能接动作结果“涂好”；把纸涂成蓝色要用〈涂成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当成", "is_correct": true, "explanation": "正确：“当成”表示认定这件事是小事，与后面的“小事”相呼应。"}, {"text": "拆成", "is_correct": false, "explanation": "语义：“拆成”指拆开分解，不表示认定这件事是小事。"}, {"text": "铸成", "is_correct": false, "explanation": "搭配：“铸成”指浇铸成器物，不能说把这件事铸成小事。"}, {"text": "凑成", "is_correct": false, "explanation": "语义：“凑成”指凑合组合，与“小事”的认定义不符。"}], "explanations": {"当成": "正确：“当成”表示认定这件事是小事，与后面的“小事”相呼应。", "拆成": "语义：“拆成”指拆开分解，不表示认定这件事是小事。", "铸成": "搭配：“铸成”指浇铸成器物，不能说把这件事铸成小事。", "凑成": "语义：“凑成”指凑合组合，与“小事”的认定义不符。"}, "sentence_index": 6, "correct_answer": "当成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把牛奶当成了冻住。", "explanation": "这里应该用〈冻成〉。“当成”后要接名词，不能接动作结果“冻住”；牛奶冻成布丁要用〈冻成〉。"}, {"text": "妈妈把毛线当成了织好。", "explanation": "这里应该用〈织成〉。“当成”后要接名词，不能接动作结果“织好”；把毛线织成毛衣要用〈织成〉。"}, {"text": "我们把面粉当成了烤熟。", "explanation": "这里应该用〈烤成〉。“当成”后要接名词，不能接动作结果“烤熟”；把面粉烤成面包要用〈烤成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我他当成了朋友，很信任他。", "corrected_sentence": "我把他当成了朋友，很信任他。", "error_description": "错误：缺少“把”，“他”不能直接放在“当成”前作宾语。应为“我把他当成了朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从不把把别人的意见当成负担。", "corrected_sentence": "他从不把别人的意见当成负担。", "error_description": "多余成分：“把”只能用一次，“把把”重复，应为“他从不把别人的意见当成负担”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
