INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "看待是对人或事有一种想法，用这种想法去对他。", "primary_collocate": null, "pronunciation": "kàn dài", "ipa": "kʰan˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "老师把我们当成朋友看待。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一直把我当小孩看待。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把客人当作家人看待。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该平等地看待每一个人。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用老眼光看待他，他已经变了。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都把她当成老大姐看待。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对新人和老人一样看待。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要用不同的眼光看待他。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚来这里，大家都把他当外人看待。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把邻居的孩子当自己的孩子看待。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看待了", "label": "体标（完成）"}, {"form": "看待过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "把某个人当作某种人来看，并这样对待他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”含欺压之意，与“当成朋友”的语境相悖"}, {"text": "糊弄", "is_correct": false, "explanation": "语域：“糊弄”是口语贬义词，与“当成朋友”的语境不合"}, {"text": "看待", "is_correct": true, "explanation": "看待：把人当作某种人来看并对待，与句意相符"}, {"text": "疏远", "is_correct": false, "explanation": "语义：“疏远”指关系变生分，与“当成朋友”相矛盾"}], "explanations": {"欺负": "语义：“欺负”含欺压之意，与“当成朋友”的语境相悖", "糊弄": "语域：“糊弄”是口语贬义词，与“当成朋友”的语境不合", "看待": "看待：把人当作某种人来看并对待，与句意相符", "疏远": "语义：“疏远”指关系变生分，与“当成朋友”相矛盾"}, "sentence_index": 0, "correct_answer": "看待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一眼就看待了这件衣服，马上买下来。", "explanation": "这里应该用〈看中〉。看中指看上某样东西想要；看待指对人或事的态度，不能用于挑选东西"}, {"text": "老师站在门口看待学生，一个一个地数人头。", "explanation": "这里应该用〈数〉。看待表示对人或事的看法和态度，不表示逐个清点人数。"}, {"text": "他站在窗前看待窗外的风景。", "explanation": "这里应该用〈看〉。看待表示对人或事的态度，不表示用眼睛注视风景"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏袒", "is_correct": false, "explanation": "语义：“偏袒”指有所偏向，与“一样”的平等含义相矛盾"}, {"text": "区分", "is_correct": false, "explanation": "语义：“区分”指分别对待，与“一样”相矛盾"}, {"text": "巴结", "is_correct": false, "explanation": "语域：“巴结”是口语贬义词，且多指讨好权势者，与这句语境不合"}, {"text": "看待", "is_correct": true, "explanation": "看待：对人持某种态度来对待，与句中“一样”相符"}], "explanations": {"偏袒": "语义：“偏袒”指有所偏向，与“一样”的平等含义相矛盾", "区分": "语义：“区分”指分别对待，与“一样”相矛盾", "巴结": "语域：“巴结”是口语贬义词，且多指讨好权势者，与这句语境不合", "看待": "看待：对人持某种态度来对待，与句中“一样”相符"}, "sentence_index": 6, "correct_answer": "看待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我终于看待了他的心思。", "explanation": "这里应该用〈看透〉。看透指看清人或事的本质；看待指对人或事的态度，不能说看透心思"}, {"text": "游客们在山顶看待美丽的日出。", "explanation": "这里应该用〈观赏〉。看待表示对人或事的看法，欣赏风景要说观赏"}, {"text": "妈妈下班后在家看待孩子。", "explanation": "这里应该用〈看管〉。看待指对人的态度，照看孩子要说看管"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该用公平的眼光看待了每个同学。", "corrected_sentence": "我们应该用公平的眼光看待每个同学。", "error_description": "“应该”表示应然，不能与表示完成的“了”同用，句中应去掉“了”，说“应该用公平的眼光看待每个同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直把我当成好朋友看待起来。", "corrected_sentence": "他一直把我当成好朋友看待。", "error_description": "“看待”后不能加“起来”，应说“一直把我当成好朋友看待”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
