INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对人或事物持某种态度或看法。", "primary_collocate": null, "pronunciation": "kàn dài", "ipa": "kʰan˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "你怎么看待这件事？", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人和老人看待钱的想法不一样。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要用发展的眼光看待问题。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看待失败的态度很好。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的人看待同一件事，常常想法不同。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人开始重新看待自己的工作。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你应该正确看待考试成绩。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻松地看待这次比赛的结果。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怎样看待网上的新闻，是个大问题。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看待新东西，和我们不太一样。", "target_word": "看待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看待了", "label": "体标（完成）"}, {"form": "看待过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "对某件事或某个东西抱有某种看法和态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿扯，与对事情的看法无关"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”的对象是人或装饰，不能说打扮这件事"}, {"text": "看待", "is_correct": true, "explanation": "看待：对事物持某种看法，与句意相符"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说煮这件事"}], "explanations": {"咬": "语义：“咬”指用牙齿扯，与对事情的看法无关", "打扮": "搭配：“打扮”的对象是人或装饰，不能说打扮这件事", "看待": "看待：对事物持某种看法，与句意相符", "煮": "搭配：“煮”的对象是食物，不能说煮这件事"}, "sentence_index": 0, "correct_answer": "看待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在大门口看待门，不让陌生人进来。", "explanation": "这里应该用〈看守〉。看守指照管、守护人或物；看待指对人或事的态度，不能用来说守门"}, {"text": "我在窗口看待了一只小鸟。", "explanation": "这里应该用〈看到〉。看待表示对人或事的态度，不表示用眼睛看见"}, {"text": "我一眼看待了这辆自行车，马上就买了下来。", "explanation": "这里应该用〈看上〉。看上指觉得某样东西好而想要；看待指对人或事的态度，不能用于挑选东西"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抄", "is_correct": false, "explanation": "语义：“抄”指照着写，与“正确”的态度不合"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”的对象是衣物或纸张，不能说叠考试成绩"}, {"text": "看待", "is_correct": true, "explanation": "看待：对事情持某种看法，与句意相符"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指点火焚毁，与“正确”的态度不合"}], "explanations": {"抄": "语义：“抄”指照着写，与“正确”的态度不合", "叠": "搭配：“叠”的对象是衣物或纸张，不能说叠考试成绩", "看待": "看待：对事情持某种看法，与句意相符", "烧": "语义：“烧”指点火焚毁，与“正确”的态度不合"}, "sentence_index": 6, "correct_answer": "看待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我终于看待了他的真面目。", "explanation": "这里应该用〈看清〉。看待表示对人或事的态度，看清真面目要说看清"}, {"text": "大家都在湖边看待美丽的风景。", "explanation": "这里应该用〈观赏〉。看待不表示用眼睛欣赏景物，欣赏风景要说观赏"}, {"text": "我看待明天会下雨。", "explanation": "这里应该用〈估计〉。看待表示对事物的看法或态度，推测天气要说估计"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们该怎样看待了这次失败？", "corrected_sentence": "我们该怎样看待这次失败？", "error_description": "“该”表示应当，是未发生的情态，不能与表示完成的“了”同用，应说“我们该怎样看待这次失败？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你应该正确地看待着考试成绩。", "corrected_sentence": "你应该正确地看待考试成绩。", "error_description": "体标错误：“应该”表示应当做的事，“看待”在这里不能加表示持续的“着”，应说“正确地看待考试成绩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
