INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "笔者是写这篇文章的人，自己说自己时用的词。", "primary_collocate": null, "pronunciation": "bǐ zhě", "ipa": "pi˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "笔者今天想说说读书的事。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者对这件事有不同的看法。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这篇文章里，笔者写了自己的经历。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者每天早上都会跑步。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者曾经在上海工作过。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者很感谢帮助过自己的人。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者认为，学外语要多听多说。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是笔者写的。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者带着孩子去过那个公园。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔者先介绍一下这个城市。", "target_word": "笔者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "写文章的人自称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '980ebab6-654b-45aa-acc6-731014f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笔者", "is_correct": true, "explanation": "正确。笔者指写文章的人，这里是作者说自己今天想谈读书的事。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有想法，不会想说话，也不会谈读书的事。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能说话，也不会有想说的事。"}, {"text": "猫", "is_correct": false, "explanation": "配价：「说」需要会说话的施事，猫不能谈读书的事。"}], "explanations": {"笔者": "正确。笔者指写文章的人，这里是作者说自己今天想谈读书的事。", "石头": "语义：石头没有想法，不会想说话，也不会谈读书的事。", "窗户": "语义：窗户不能说话，也不会有想说的事。", "猫": "配价：「说」需要会说话的施事，猫不能谈读书的事。"}, "sentence_index": 0, "correct_answer": "笔者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的笔者是李白。", "explanation": "这里应该用〈作者〉。笔者只用于作者称呼自己，不能指别人写的作品的作者。"}, {"text": "我最近成了一只笔者。", "explanation": "量词用错：笔者指写文章的人，是人，应该用「位」，不能用「只」。"}, {"text": "您好，请问您是笔者吗？", "explanation": "这里应该用〈读者〉。笔者是作者自称，不能用来称呼对方；称呼读文章的人要用「读者」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笔者", "is_correct": true, "explanation": "正确。笔者是写文章的人，这里是作者给出自己的看法。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有判断能力，不能「认为」学外语的方法好。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不会判断，不能对学外语提出看法。"}, {"text": "老虎", "is_correct": false, "explanation": "配价：「认为」要求能判断的人作主语，老虎不能表达这种看法。"}], "explanations": {"笔者": "正确。笔者是写文章的人，这里是作者给出自己的看法。", "桌子": "语义：桌子没有判断能力，不能「认为」学外语的方法好。", "河水": "语义：河水不会判断，不能对学外语提出看法。", "老虎": "配价：「认为」要求能判断的人作主语，老虎不能表达这种看法。"}, "sentence_index": 6, "correct_answer": "笔者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部笔者很精彩。", "explanation": "这里应该用〈作品〉。笔者指写文章的人，不能指作品；「这部」修饰的是作品，要用「作品」。"}, {"text": "我用这支笔者写字。", "explanation": "这里应该用〈钢笔〉。笔者指写文章的人，不能指书写工具；书写工具要说「钢笔」。"}, {"text": "我买了一本笔者。", "explanation": "量词用错：笔者指人，不能用「本」来数，应该用「位」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只笔者很喜欢读书。", "corrected_sentence": "笔者很喜欢读书。", "error_description": "量词错误：笔者指人，不能用「只」（「只」多用于动物）。正确的是直接说「笔者很喜欢读书」，去掉「这只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "笔者，请你先介绍一下这个城市。", "corrected_sentence": "作者，请你先介绍一下这个城市。", "error_description": "用词错误：笔者是作者称呼自己的词，不能用来称呼别人。称呼对方应该用「作者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
