INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94193, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "罪犯是做了很坏的事、违反法律的人，多指正被警察追捕或抓获的人。", "primary_collocate": null, "pronunciation": "zuì fàn", "ipa": "tsuei˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "警察抓住了那个罪犯。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯跑得很快，警察没追上。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来不像罪犯，像个老师。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了坏事，警察把这个罪犯抓走了。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把罪犯带回了警察局。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个罪犯偷了很多人的钱。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，警察一直在找那名罪犯。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯坐在车里，不说话。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在门口等着，罪犯出来了。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的罪犯躲在一个小房子里。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "违法做坏事、被警察追捕或抓获的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94c76b39-0b43-41b7-acc8-e7c4649e2034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罪犯", "is_correct": true, "explanation": "“警察抓住了那个……”的对象是违法犯罪、被警察追捕的人，“罪犯”符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能被“抓住”，警察抓的只能是人，句子不通。"}, {"text": "皮球", "is_correct": false, "explanation": "语义：警察不会去抓皮球，“抓住”在这里的对象只能是人。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“抓住”一般不与“咖啡”搭配，咖啡应说“喝”。"}], "explanations": {"罪犯": "“警察抓住了那个……”的对象是违法犯罪、被警察追捕的人，“罪犯”符合句意。", "窗户": "语义：窗户不能被“抓住”，警察抓的只能是人，句子不通。", "皮球": "语义：警察不会去抓皮球，“抓住”在这里的对象只能是人。", "咖啡": "搭配：“抓住”一般不与“咖啡”搭配，咖啡应说“喝”。"}, "sentence_index": 0, "correct_answer": "罪犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都去罪犯上班，工作很认真。", "explanation": "这里应该用〈公司〉。罪犯指犯了罪的人，是人而不是地方，不能说“去罪犯上班”。"}, {"text": "这家公司的罪犯是王先生，大家都很尊敬他。", "explanation": "这里应该用〈经理〉。罪犯指犯了罪的人，不能用来称呼公司里负责管理的人。"}, {"text": "他的钱被小偷偷了，他是这件事的罪犯。", "explanation": "罪犯指作案的人，这里的“他”是被偷的人，不能称为罪犯，应说受害者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罪犯", "is_correct": true, "explanation": "“警察一直在找”的对象是犯了事的人，“那名”也只用于人，“罪犯”符合句意。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：量词“名”只用于人，动物应用“只”，而且警察不会去找小猫。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：警察不会去找月亮，“找”的对象应是人或丢失的东西。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“名”不能修饰“桌子”，桌子应用“张”。"}], "explanations": {"罪犯": "“警察一直在找”的对象是犯了事的人，“那名”也只用于人，“罪犯”符合句意。", "小猫": "搭配：量词“名”只用于人，动物应用“只”，而且警察不会去找小猫。", "月亮": "语义：警察不会去找月亮，“找”的对象应是人或丢失的东西。", "桌子": "搭配：量词“名”不能修饰“桌子”，桌子应用“张”。"}, "sentence_index": 6, "correct_answer": "罪犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的罪犯太严重了，法院判了他十年。", "explanation": "这里应该用〈罪行〉。罪犯指人，罪行才指做的坏事，不能说“罪犯很严重”。"}, {"text": "我的罪犯很热心，经常帮我。", "explanation": "这里应该用〈朋友〉。罪犯指做了坏事、被警察抓起来的人，不能用来称呼关系很好的人。"}, {"text": "这位罪犯每天认真备课，学生们都很喜欢他。", "explanation": "这里应该用〈老师〉。罪犯指犯了罪的人，不能用来称呼负责教课的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天，警察抓到了一只罪犯。", "corrected_sentence": "昨天，警察抓到了一个罪犯。", "error_description": "量词错误：“罪犯”指人，应用量词“个”或“名”，不能用“只”（“只”用于动物等）。正确说法是“一个罪犯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察已经罪犯抓住了。", "corrected_sentence": "警察已经把罪犯抓住了。", "error_description": "漏掉“把”：“罪犯”是被抓的对象，要用“把”引出并放在动词前，应说“警察已经把罪犯抓住了”。原句直接把名词放在动词前，缺“把”后不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
