INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "犯了罪的人，特别是被依法判刑的人。", "primary_collocate": null, "pronunciation": "zuì fàn", "ipa": "tsuei˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "法院判了这名罪犯十年。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯要在监狱里关十年。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判罪犯三年，他在监狱里很后悔。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这名罪犯已经受到了法律的处罚。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯出狱后，找到了一份工作。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监狱里的罪犯每天都要工作。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官问罪犯：“你知道自己错了吗？”", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写着，这个罪犯今天上法庭。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罪犯的家人来监狱看他。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是罪犯，现在重新开始生活了。", "target_word": "罪犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "依法判刑的犯罪者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94c76b39-0b43-41b7-acc8-e7c4649e2034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罪犯", "is_correct": true, "explanation": "法院判刑十年的对象是犯罪并被定罪的人，“罪犯”符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“名”只用于人，房子应用“座”或“栋”，而且房子不能被判刑。"}, {"text": "水", "is_correct": false, "explanation": "语义：“判十年”的对象必须是人，水不能被法院判刑。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“判”的受事只能是人，“窗户”不能作为判刑的对象。"}], "explanations": {"罪犯": "法院判刑十年的对象是犯罪并被定罪的人，“罪犯”符合句意。", "房子": "搭配：量词“名”只用于人，房子应用“座”或“栋”，而且房子不能被判刑。", "水": "语义：“判十年”的对象必须是人，水不能被法院判刑。", "窗户": "配价：“判”的受事只能是人，“窗户”不能作为判刑的对象。"}, "sentence_index": 0, "correct_answer": "罪犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我班上的罪犯，成绩很好。", "explanation": "这里应该用〈学生〉。罪犯指犯了罪的人，不能用来指在班里学习的人。"}, {"text": "这次的罪犯很严重，法院判了他十年。", "explanation": "这里应该用〈罪行〉。罪犯指人，不能用来说犯罪行为有多严重。"}, {"text": "这位罪犯每天在法庭上判案，大家都很信任他。", "explanation": "这里应该用〈法官〉。罪犯是犯了罪的人，不能担任在法庭上判案的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罪犯", "is_correct": true, "explanation": "问话的对象是能听懂问题、能回答的人，“罪犯”符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“问”的对象要能回答问题，椅子不能作受问者。"}, {"text": "树", "is_correct": false, "explanation": "语义：树听不懂问题，也不会回答“你知道自己错了吗”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能作受问者，法官的问话只能对人说。"}], "explanations": {"罪犯": "问话的对象是能听懂问题、能回答的人，“罪犯”符合句意。", "椅子": "配价：“问”的对象要能回答问题，椅子不能作受问者。", "树": "语义：树听不懂问题，也不会回答“你知道自己错了吗”。", "桌子": "语义：桌子不能作受问者，法官的问话只能对人说。"}, "sentence_index": 6, "correct_answer": "罪犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的职业是罪犯，每天在法院上班。", "explanation": "这里应该用〈法官〉。罪犯指犯了罪、被判刑的人，是一种身份，不是职业，更不会在法院上班。"}, {"text": "我家的罪犯很热心，经常帮我。", "explanation": "这里应该用〈邻居〉。罪犯指犯了罪的人，不能用来称呼住在隔壁、经常帮助我的人。"}, {"text": "他被小偷打伤了，他是这件事的罪犯。", "explanation": "这里应该用〈受害者〉。罪犯指作案的人，被小偷打伤的人应称为〈受害者〉，不是罪犯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个罪犯把法院判了十年。", "corrected_sentence": "那个罪犯被法院判了十年。", "error_description": "被字句错误：错误形式是“把法院判了十年”，正确形式是“被法院判了十年”。“罪犯”是被判的人，应作主语；“法院”是施事，要用“被”引出，“把”不能引出施事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官那个罪犯判了十年。", "corrected_sentence": "法官把那个罪犯判了十年。", "error_description": "漏掉“把”：错误形式是“法官那个罪犯判了十年”，正确形式是“法官把那个罪犯判了十年”。把字句中受事要由“把”引出并放在动词前；漏掉“把”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94195, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "容易：与“艰难”构成反义，指做起来不费力。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：形容外貌好看，与“艰难”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容明白、不模糊，与“艰难”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容人多、有声音，与“艰难”没有反义关系。"}], "correct_answer": "容易", "explanations": {"容易": "容易：与“艰难”构成反义，指做起来不费力。", "漂亮": "漂亮：形容外貌好看，与“艰难”没有反义关系。", "清楚": "清楚：形容明白、不模糊，与“艰难”没有反义关系。", "热闹": "热闹：形容人多、有声音，与“艰难”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94195, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "容易：与“艰难”构成反义，指做起来不费力。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容没有污物，与“艰难”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足或颜色鲜亮，与“艰难”没有反义关系。"}, {"text": "新鲜", "is_correct": false, "explanation": "新鲜：形容刚生产或刚出现的，与“艰难”没有反义关系。"}], "correct_answer": "容易", "explanations": {"容易": "容易：与“艰难”构成反义，指做起来不费力。", "干净": "干净：形容没有污物，与“艰难”没有反义关系。", "明亮": "明亮：形容光线充足或颜色鲜亮，与“艰难”没有反义关系。", "新鲜": "新鲜：形容刚生产或刚出现的，与“艰难”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94195, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "艰难是很难做到，要花很大力气。", "primary_collocate": null, "pronunciation": "jiān nán", "ipa": "tɕjɛn˥ nan˧˥", "syllable_count": 2, "sentences": [{"text": "他艰难地爬上了山顶。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大了，我们走得很艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人艰难地站起来，慢慢走向门口。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要在一年内学会这门语言，真的很艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条路又窄又滑，每一步都很艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了伤，说话也变得很艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大雨里找一个人，是件艰难的事。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们艰难地走完了最后十公里。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她艰难地把重箱子搬上了楼。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里没有路，大家前进得很艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艰难困苦", "label": "复合"}, {"form": "艰难险阻", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事要花很大力气、很费劲、很难完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3b207d-7c24-48b9-bf1d-e4e2b943cf6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”说经济状况，与爬上山顶的方式无关。"}, {"text": "艰难", "is_correct": true, "explanation": "艰难：表示做起来很费力，符合“他费力地爬上了山顶”的意思。"}, {"text": "通红", "is_correct": false, "explanation": "搭配：“通红”只描写脸色或颜色，不能修饰“爬”这样的动作。"}, {"text": "蔚蓝", "is_correct": false, "explanation": "语义：“蔚蓝”形容颜色，不能描述爬上山顶的方式。"}], "explanations": {"富裕": "语义：“富裕”说经济状况，与爬上山顶的方式无关。", "艰难": "艰难：表示做起来很费力，符合“他费力地爬上了山顶”的意思。", "通红": "搭配：“通红”只描写脸色或颜色，不能修饰“爬”这样的动作。", "蔚蓝": "语义：“蔚蓝”形容颜色，不能描述爬上山顶的方式。"}, "sentence_index": 0, "correct_answer": "艰难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你艰难了，先休息一下吧。", "explanation": "这里应该用〈辛苦〉。“辛苦”可以用来慰问、评价人的付出，“艰难”只说事情或过程难，不能用来评价人。"}, {"text": "有艰难就来找我，我会帮你。", "explanation": "这里应该用〈困难〉。“有困难”里的“困难”是名词，“艰难”一般只作形容词，不能这样用。"}, {"text": "他这样做，艰难不讨好。", "explanation": "这里应该用〈吃力〉。“吃力不讨好”是固定说法，“艰难”不能代替其中的“吃力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻松", "is_correct": false, "explanation": "语义：在大雨里找人并不轻松，“轻松”与句中的“大雨”处境矛盾。"}, {"text": "艰难", "is_correct": true, "explanation": "艰难：表示做起来很费力，符合“在大雨里找一个人”的处境。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”表示心情好，与“大雨里找人”的处境不合。"}, {"text": "精确", "is_correct": false, "explanation": "搭配：“精确”多修饰数据、计算、测量，不说“精确的事”。"}], "explanations": {"轻松": "语义：在大雨里找人并不轻松，“轻松”与句中的“大雨”处境矛盾。", "艰难": "艰难：表示做起来很费力，符合“在大雨里找一个人”的处境。", "愉快": "语义：“愉快”表示心情好，与“大雨里找人”的处境不合。", "精确": "搭配：“精确”多修饰数据、计算、测量，不说“精确的事”。"}, "sentence_index": 6, "correct_answer": "艰难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒了，浑身艰难。", "explanation": "这里应该用〈难受〉。“难受”可形容身体的不舒服，“艰难”不用来形容身体感觉。"}, {"text": "他是个很艰难的人，大家都怕他。", "explanation": "这里应该用〈难缠〉。“难缠”形容人不好对付，“艰难”只说事情或处境难，不用来形容人的性格。"}, {"text": "天色很艰难，眼看要下雨了。", "explanation": "这里应该用〈阴沉〉。“阴沉”可以形容天色，“艰难”不用来描写天气或天色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她艰难的走进了屋。", "corrected_sentence": "她艰难地走进了屋。", "error_description": "错误：“艰难”修饰动词“走进”时用了“的”，说成“艰难的走进”。正确：修饰动词要用“地”，应说“艰难地走进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在大雨中艰难得前进。", "corrected_sentence": "他们在大雨中艰难地前进。", "error_description": "错误：修饰动词“前进”时，“艰难”后应用结构助词“地”，这里误写成“得”，说成“艰难得前进”。正确：应说“艰难地前进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94196, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺利", "is_correct": true, "explanation": "顺利：与“艰难”构成反义，指事情进行得没有阻碍。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮：形容声音大而清楚，与“艰难”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐：形容排列有序，与“艰难”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖：形容温度适中、令人舒适，与“艰难”没有反义关系。"}], "correct_answer": "顺利", "explanations": {"顺利": "顺利：与“艰难”构成反义，指事情进行得没有阻碍。", "响亮": "响亮：形容声音大而清楚，与“艰难”没有反义关系。", "整齐": "整齐：形容排列有序，与“艰难”没有反义关系。", "温暖": "温暖：形容温度适中、令人舒适，与“艰难”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94196, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺利", "is_correct": true, "explanation": "顺利：与“艰难”构成反义，指事情进行得没有阻碍。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：形容外貌好看，与“艰难”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容明白、不模糊，与“艰难”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容人多、有声音，与“艰难”没有反义关系。"}], "correct_answer": "顺利", "explanations": {"顺利": "顺利：与“艰难”构成反义，指事情进行得没有阻碍。", "漂亮": "漂亮：形容外貌好看，与“艰难”没有反义关系。", "清楚": "清楚：形容明白、不模糊，与“艰难”没有反义关系。", "热闹": "热闹：形容人多、有声音，与“艰难”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94196, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事情困难，不容易应付。", "primary_collocate": null, "pronunciation": "jiān nán", "ipa": "tɕjɛn˥ nan˧˥", "syllable_count": 2, "sentences": [{"text": "那几年，他们家的生活很艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司遇到了艰难的时期。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个艰难的选择，我想了很久。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在艰难的环境中长大。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争年代，人们过着艰难的日子。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在找工作比较艰难，很多人都在担心。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人带孩子，处境十分艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对艰难的局面，老板没有放弃。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失业后，他的日子越来越艰难。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定很艰难，因为两边我都舍不得。", "target_word": "艰难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艰难困苦", "label": "复合"}, {"form": "艰难险阻", "label": "复合"}], "register": "中性", "sense_fingerprint": "处境、生活、选择等困难，不容易应付", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3b207d-7c24-48b9-bf1d-e4e2b943cf6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能描述生活状况。"}, {"text": "艰难", "is_correct": true, "explanation": "艰难：形容生活处境困难，与“那几年，他们家的生活”相符。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”多修饰空气、土壤、眼睛，不说“生活湿润”。"}, {"text": "尖锐", "is_correct": false, "explanation": "语义：“尖锐”形容锋利或矛盾激烈，不用来形容生活状况。"}], "explanations": {"清脆": "语义：“清脆”形容声音，不能描述生活状况。", "艰难": "艰难：形容生活处境困难，与“那几年，他们家的生活”相符。", "湿润": "搭配：“湿润”多修饰空气、土壤、眼睛，不说“生活湿润”。", "尖锐": "语义：“尖锐”形容锋利或矛盾激烈，不用来形容生活状况。"}, "sentence_index": 0, "correct_answer": "艰难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个客户很艰难，大家都躲着他。", "explanation": "这里应该用〈难缠〉。“难缠”形容人不好对付，“艰难”只说事情或处境难，不用来形容人的性格。"}, {"text": "他的脸色很艰难，大家都不敢说话。", "explanation": "这里应该用〈阴沉〉。“阴沉”可以形容脸色，“艰难”不用来描写脸色。"}, {"text": "有什么艰难尽管说。", "explanation": "这里应该用〈困难〉。“有什么困难”里的“困难”是名词，“艰难”一般只作形容词，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能描述处境。"}, {"text": "艰难", "is_correct": true, "explanation": "艰难：形容处境困难，与“她一个人带孩子”的情况相符。"}, {"text": "干脆", "is_correct": false, "explanation": "搭配：“干脆”多修饰说话或做事的方式，不说“处境干脆”。"}, {"text": "清爽", "is_correct": false, "explanation": "语义：“清爽”形容感觉干净、舒畅，不能描述处境。"}], "explanations": {"柔软": "语义：“柔软”形容质地，不能描述处境。", "艰难": "艰难：形容处境困难，与“她一个人带孩子”的情况相符。", "干脆": "搭配：“干脆”多修饰说话或做事的方式，不说“处境干脆”。", "清爽": "语义：“清爽”形容感觉干净、舒畅，不能描述处境。"}, "sentence_index": 6, "correct_answer": "艰难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些年你艰难了。", "explanation": "这里应该用〈辛苦〉。“辛苦”可以用来慰问、评价人的付出，“艰难”只说事情或处境难，不能用来评价人。"}, {"text": "这种服务艰难不讨好。", "explanation": "这里应该用〈吃力〉。“吃力不讨好”是固定说法，“艰难”不能代替其中的“吃力”。"}, {"text": "她胃疼得很艰难，一句话也不想说。", "explanation": "这里应该用〈难受〉。“难受”可形容身体的不舒服，“艰难”不用来形容身体感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在艰难地环境里努力学习。", "corrected_sentence": "他在艰难的环境里努力学习。", "error_description": "错误：“艰难”修饰名词“环境”时用了“地”，说成“艰难地环境”。正确：修饰名词要用“的”，应说“艰难的环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场病以后，他的日子变得很艰难地。", "corrected_sentence": "这场病以后，他的日子变得很艰难。", "error_description": "错误：“艰难”在句末作谓语，后面多加了“地”，说成“变得很艰难地。”。正确：作谓语时不加“地”，应说“变得很艰难。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
