INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94197, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "艾是一种有香味的草，叶子可以点着熏。", "primary_collocate": null, "pronunciation": "ài", "ipa": "aɪ˥˩", "syllable_count": 1, "sentences": [{"text": "端午节，家家门口都插着艾。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶点着艾，屋里有一股香味。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艾的叶子有香味，可以用来驱蚊。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边长着很多艾，闻起来很香。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把艾晒干，放在袋子里。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天蚊子多，爷爷常常点艾熏屋子。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艾点着以后，会冒出白色的烟。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种艾要在春天采，夏天晒干。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在院子里种了一小块艾。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艾烧起来，有一种特别的香味。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把艾", "label": "量词"}, {"form": "艾草", "label": "复合"}], "register": "中性", "sense_fingerprint": "艾：端午节常用的有香味的草，点着可以熏屋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94197, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艾", "is_correct": true, "explanation": "艾：ài（第四声），一种有香味的草，端午节常用来熏屋子。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 ài（第四声）声调不同，意思是高矮的矮。"}, {"text": "挨", "is_correct": false, "explanation": "ái（第二声）与 ài（第四声）声调不同，意思是挨着的挨。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 ài（第四声）声调不同，意思是癌症的癌。"}, {"text": "哀", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，意思是哀伤的哀。"}], "explanations": {"艾": "艾：ài（第四声），一种有香味的草，端午节常用来熏屋子。", "矮": "ǎi（第三声）与 ài（第四声）声调不同，意思是高矮的矮。", "挨": "ái（第二声）与 ài（第四声）声调不同，意思是挨着的挨。", "癌": "ái（第二声）与 ài（第四声）声调不同，意思是癌症的癌。", "哀": "āi（第一声）与 ài（第四声）声调不同，意思是哀伤的哀。"}, "sentence_index": null, "correct_answer": "艾"}, "level_3": {"options": [{"text": "艾", "is_correct": true, "explanation": "此处指端午节门口插的有香味的草，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是植物，端午节门口插石头的说法不通。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“插”不能与饺子搭配，说插饺子不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是端午节门口常插的东西，句子不成立。"}], "explanations": {"艾": "此处指端午节门口插的有香味的草，符合语境。", "石头": "语义：石头不是植物，端午节门口插石头的说法不通。", "饺子": "搭配：“插”不能与饺子搭配，说插饺子不通。", "书包": "语义：书包不是端午节门口常插的东西，句子不成立。"}, "sentence_index": 0, "correct_answer": "艾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在集市上买了一只艾。", "explanation": "这里应该用〈把〉。艾是成把卖的草，量词用“把”；“只”用于动物，不能用于草本植物。"}, {"text": "秋天到了，树上结满了红红的艾，孩子们摘来吃。", "explanation": "这里应该用〈果子〉。艾是草本植物，不长在树上，也不结可以吃的果实。"}, {"text": "河边有一头艾，闻起来很香。", "explanation": "这里应该用〈棵〉。“头”用于大型牲畜，不能用于草本植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94197, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "艾", "is_correct": true, "explanation": "艾：ài（第四声），一种有香味的草，点燃后可以熏屋子。"}, {"text": "傲", "is_correct": false, "explanation": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是傲慢的傲。"}, {"text": "奥", "is_correct": false, "explanation": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是奥运的奥。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 ài（第四声）声调不同，意思是癌症的癌。"}, {"text": "埃", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，意思是埃及的埃。"}], "explanations": {"艾": "艾：ài（第四声），一种有香味的草，点燃后可以熏屋子。", "傲": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是傲慢的傲。", "奥": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是奥运的奥。", "癌": "ái（第二声）与 ài（第四声）声调不同，意思是癌症的癌。", "埃": "āi（第一声）与 ài（第四声）声调不同，意思是埃及的埃。"}, "sentence_index": null, "correct_answer": "艾"}, "level_3": {"options": [{"text": "艾", "is_correct": true, "explanation": "此处指点着后会冒白烟的草，符合语境。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰遇火不能点着，句子说点着以后冒烟不成立。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能被点着，也不会冒出白色的烟。"}, {"text": "砖", "is_correct": false, "explanation": "搭配：“点着”不搭配砖，砖不能点燃冒烟。"}], "explanations": {"艾": "此处指点着后会冒白烟的草，符合语境。", "冰": "语义：冰遇火不能点着，句子说点着以后冒烟不成立。", "水": "语义：水不能被点着，也不会冒出白色的烟。", "砖": "搭配：“点着”不搭配砖，砖不能点燃冒烟。"}, "sentence_index": 6, "correct_answer": "艾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把艾当成风筝线，放起了风筝。", "explanation": "这里应该用〈线〉。艾是草本植物，柔软易断，不能当风筝线。"}, {"text": "孩子们在艾上踢球。", "explanation": "这里应该用〈草坪〉。艾是直立生长的草本植物，不能像草坪一样用来踢球。"}, {"text": "艾在河里游泳，游得非常快。", "explanation": "这里应该用〈鱼〉。艾是草，不会游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在门口挂了一只艾。", "corrected_sentence": "我在门口挂了一把艾。", "error_description": "量词错误：艾是成把的草，应说“一把艾”，不能说“一只艾”；“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候用艾过驱蚊。", "corrected_sentence": "我小时候用过艾驱蚊。", "error_description": "体标位置错误：“过”要紧跟动词“用”，说“用过艾”，不能说“用艾过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
