INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "多年生草本植物，叶有香气，可入药或用于熏灸。", "primary_collocate": null, "pronunciation": "ài", "ipa": "aɪ˥˩", "syllable_count": 1, "sentences": [{"text": "医生用艾给病人治腰疼。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艾是多年生的草，叶子有香味。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药是用艾做的。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷腿疼的时候，常用艾熏一熏。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医常用艾给人治病。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艾的叶子背面是白色的。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上的艾每年春天都会长出新叶。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药店里有晒干的艾，可以买回家。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种艾可以入药，也可以用来熏灸。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，用艾熏的时候，身上会觉得很热。", "target_word": "艾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把艾", "label": "量词"}, {"form": "艾草", "label": "复合"}], "register": "中性", "sense_fingerprint": "艾：可入药、用于熏灸的多年生草本植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94198, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艾", "is_correct": true, "explanation": "艾：ài（第四声），可入药、用于熏灸的草本植物。"}, {"text": "哎", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，意思是叹词“哎”。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 ài（第四声）声调不同，意思是高矮的矮。"}, {"text": "挨", "is_correct": false, "explanation": "ái（第二声）与 ài（第四声）声调不同，意思是挨着的挨。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 ài（第四声）声调不同，意思是癌症的癌。"}], "explanations": {"艾": "艾：ài（第四声），可入药、用于熏灸的草本植物。", "哎": "āi（第一声）与 ài（第四声）声调不同，意思是叹词“哎”。", "矮": "ǎi（第三声）与 ài（第四声）声调不同，意思是高矮的矮。", "挨": "ái（第二声）与 ài（第四声）声调不同，意思是挨着的挨。", "癌": "ái（第二声）与 ài（第四声）声调不同，意思是癌症的癌。"}, "sentence_index": null, "correct_answer": "艾"}, "level_3": {"options": [{"text": "艾", "is_correct": true, "explanation": "此处指可入药的草本植物，医生用它给病人治病，符合语境。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓不能用来治腰疼，句子不成立。"}, {"text": "饭团", "is_correct": false, "explanation": "搭配：“用……给病人治病”的宾语应是药物或疗法，饭团不能用于治疗。"}, {"text": "口罩", "is_correct": false, "explanation": "语义：口罩用于防护，不能用来治腰疼。"}], "explanations": {"艾": "此处指可入药的草本植物，医生用它给病人治病，符合语境。", "草莓": "语义：草莓不能用来治腰疼，句子不成立。", "饭团": "搭配：“用……给病人治病”的宾语应是药物或疗法，饭团不能用于治疗。", "口罩": "语义：口罩用于防护，不能用来治腰疼。"}, "sentence_index": 0, "correct_answer": "艾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生用艾修好了断掉的腿。", "explanation": "这里应该用〈夹板〉。艾是草药，不能用来固定骨折。"}, {"text": "这种药是用一只艾做的。", "explanation": "这里应该用〈把〉或〈束〉。“只”用于动物，不能用于草本植物。"}, {"text": "这种艾可以入药，也可以用来做被子。", "explanation": "这里应该用〈熏灸〉。艾是草本植物，不能用来做被子，它的用途是入药和熏灸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94198, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "艾", "is_correct": true, "explanation": "艾：ài（第四声），可入药、用于熏灸的草本植物。"}, {"text": "傲", "is_correct": false, "explanation": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是傲慢的傲。"}, {"text": "奥", "is_correct": false, "explanation": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是奥运的奥。"}, {"text": "埃", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，意思是埃及的埃。"}, {"text": "哀", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，意思是哀伤的哀。"}], "explanations": {"艾": "艾：ài（第四声），可入药、用于熏灸的草本植物。", "傲": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是傲慢的傲。", "奥": "ào（第四声）与 ài 韵母不同：ao 与 ai，意思是奥运的奥。", "埃": "āi（第一声）与 ài（第四声）声调不同，意思是埃及的埃。", "哀": "āi（第一声）与 ài（第四声）声调不同，意思是哀伤的哀。"}, "sentence_index": null, "correct_answer": "艾"}, "level_3": {"options": [{"text": "艾", "is_correct": true, "explanation": "此处指山坡上长出新叶的草本植物，符合语境。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋不是植物，不会每年春天长出新叶。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“长出新叶”只用于植物，不能与水泥搭配。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不会长出新叶，句子不成立。"}], "explanations": {"艾": "此处指山坡上长出新叶的草本植物，符合语境。", "皮鞋": "语义：皮鞋不是植物，不会每年春天长出新叶。", "水泥": "搭配：“长出新叶”只用于植物，不能与水泥搭配。", "椅子": "语义：椅子是家具，不会长出新叶，句子不成立。"}, "sentence_index": 6, "correct_answer": "艾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "艾的叶子是透明的，很好看。", "explanation": "这里应该用〈有香气〉。艾叶不透明，香气才是它的特点。"}, {"text": "医生用艾打针，病人很快就好了。", "explanation": "这里应该用〈药〉。艾不能用来打针，要点燃后熏灸。"}, {"text": "这种艾长在海底，很少见。", "explanation": "这里应该用〈海藻〉。艾生长在陆地上，不长在海底。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷以前用艾过给自己治腿疼。", "corrected_sentence": "爷爷以前用过艾给自己治腿疼。", "error_description": "体标位置错误：“过”要紧跟动词“用”，说“用过艾”，不能说“用艾过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一只艾，准备熏屋子。", "corrected_sentence": "他买了一把艾，准备熏屋子。", "error_description": "量词错误：艾是成把的草，应说“一把艾”，不能说“一只艾”；“只”用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
