INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94199, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "兰是一种好看又很香的花。", "primary_collocate": null, "pronunciation": "lán", "ipa": "lan˧˥", "syllable_count": 1, "sentences": [{"text": "我家里养了一盆兰。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆兰很香，也很好看。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，窗前的兰开了。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶喜欢养兰，每天给它浇水。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻闻，这株兰的味道真好。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给妈妈买了一盆兰。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一盆兰，屋里很香。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱玫瑰，只爱兰。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一株兰，开着小白花。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兰不太大，可是很好看。", "target_word": "兰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盆", "label": "量词"}, {"form": "株", "label": "量词"}, {"form": "兰花", "label": "复合"}, {"form": "蘭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "好看又很香的花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94c76b39-0b43-41b7-acc8-e7c4649e2034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94199, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兰", "is_correct": true, "explanation": "兰（lán）指兰花，是花香而美的植物。"}, {"text": "南", "is_correct": false, "explanation": "南（nán）与 lán 声母不同（n 与 l），意思是南方。"}, {"text": "郎", "is_correct": false, "explanation": "郎（láng）与 lán 韵母不同（ang 与 an），意思是男子。"}, {"text": "览", "is_correct": false, "explanation": "览（lǎn）与 lán 声调不同（第三声与第二声），意思是阅览。"}, {"text": "滥", "is_correct": false, "explanation": "滥（làn）与 lán 声调不同（第四声与第二声），意思是过多。"}], "explanations": {"兰": "兰（lán）指兰花，是花香而美的植物。", "南": "南（nán）与 lán 声母不同（n 与 l），意思是南方。", "郎": "郎（láng）与 lán 韵母不同（ang 与 an），意思是男子。", "览": "览（lǎn）与 lán 声调不同（第三声与第二声），意思是阅览。", "滥": "滥（làn）与 lán 声调不同（第四声与第二声），意思是过多。"}, "sentence_index": null, "correct_answer": "兰"}, "level_3": {"options": [{"text": "兰", "is_correct": true, "explanation": "正确：兰是可以养在盆里的花，符合句意。"}, {"text": "铁锅", "is_correct": false, "explanation": "语义：铁锅是炊具，不能被“养”，句子不通。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“养”的对象需要是有生命的东西，汽车不能被养。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：量词“盆”不能用于椅子，椅子也不能放进盆里。"}], "explanations": {"兰": "正确：兰是可以养在盆里的花，符合句意。", "铁锅": "语义：铁锅是炊具，不能被“养”，句子不通。", "汽车": "配价：“养”的对象需要是有生命的东西，汽车不能被养。", "椅子": "搭配：量词“盆”不能用于椅子，椅子也不能放进盆里。"}, "sentence_index": 0, "correct_answer": "兰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一张兰。", "explanation": "这里应该用〈盆〉或〈株〉。量词“张”用于纸、桌子等扁平的东西，兰不能用“张”。"}, {"text": "他每天晚上都读兰，读到很晚才睡。", "explanation": "这里应该用〈书〉。兰是植物，不能阅读，读的应是书。"}, {"text": "妈妈用兰做了一大锅汤。", "explanation": "这里应该用〈萝卜〉。兰不能用来做汤，它是观赏植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94199, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兰", "is_correct": true, "explanation": "兰（lán）指兰花，是花香而美的植物。"}, {"text": "难", "is_correct": false, "explanation": "难（nán）与 lán 声母不同（n 与 l），意思是困难。"}, {"text": "狼", "is_correct": false, "explanation": "狼（láng）与 lán 韵母不同（ang 与 an），意思是狼。"}, {"text": "懒", "is_correct": false, "explanation": "懒（lǎn）与 lán 声调不同（第三声与第二声），意思是懒惰。"}, {"text": "烂", "is_correct": false, "explanation": "烂（làn）与 lán 声调不同（第四声与第二声），意思是腐烂。"}], "explanations": {"兰": "兰（lán）指兰花，是花香而美的植物。", "难": "难（nán）与 lán 声母不同（n 与 l），意思是困难。", "狼": "狼（láng）与 lán 韵母不同（ang 与 an），意思是狼。", "懒": "懒（lǎn）与 lán 声调不同（第三声与第二声），意思是懒惰。", "烂": "烂（làn）与 lán 声调不同（第四声与第二声），意思是腐烂。"}, "sentence_index": null, "correct_answer": "兰"}, "level_3": {"options": [{"text": "兰", "is_correct": true, "explanation": "正确：兰有香味，放在桌上，屋里会很香，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾气味难闻，与“屋里很香”矛盾。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词“盆”不能用于计量猫，猫也不能放在盆里。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“一盆”不能用来计量桌子，桌子也不能放在盆里。"}], "explanations": {"兰": "正确：兰有香味，放在桌上，屋里会很香，符合句意。", "垃圾": "语义：垃圾气味难闻，与“屋里很香”矛盾。", "猫": "搭配：量词“盆”不能用于计量猫，猫也不能放在盆里。", "桌子": "搭配：“一盆”不能用来计量桌子，桌子也不能放在盆里。"}, "sentence_index": 6, "correct_answer": "兰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上骑一辆兰去上班。", "explanation": "这里应该用〈自行车〉。兰是植物，不能骑，应说“骑自行车”。"}, {"text": "妈妈每天用兰给汤调味。", "explanation": "这里应该用〈葱〉。兰不能用来调味。"}, {"text": "他早上吃了两个兰。", "explanation": "这里应该用〈鸡蛋〉。兰不能吃，“个”指的是鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在阳台上养了一条兰。", "corrected_sentence": "我在阳台上养了一盆兰。", "error_description": "错误：量词“条”；正确：“盆”。兰是种在盆里的花，量词应用“盆”或“株”，“条”用于鱼、路等长条形的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书桌上摆着一颗兰。", "corrected_sentence": "书桌上摆着一株兰。", "error_description": "错误：量词“颗”；正确：“株”。兰是植物，量词应用“株”或“盆”，“颗”用于种子、果实等小而圆的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
