INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "补偿是弄坏了别人的东西，就给别人东西或钱作为赔偿。", "primary_collocate": null, "pronunciation": "bǔ cháng", "ipa": "pu˨˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我弄坏了朋友的相机，买了新的来补偿他。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明打破了邻居的窗户，买了一块新玻璃来补偿他。", "target_word": "补偿", "complexity_tier": "T3", "furigana": "bǔcháng", "sentence_source": "generated"}, {"text": "孩子把别人的玩具摔坏了，妈妈让他补偿。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你踩坏了我的帽子，该怎么补偿我？", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他撞坏了邻居的门，买了一扇新门来补偿他。", "target_word": "补偿", "complexity_tier": "T3", "furigana": "bǔcháng", "sentence_source": "generated"}, {"text": "弟弟弄坏了我的书包，答应买个新的补偿我。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不小心摔坏了老师的眼镜，想买新的补偿她。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我撞坏了你的自行车，我来补偿。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把我的杯子打破了，说要补偿我。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁弄坏了公司的电脑，谁就要补偿。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "补偿了", "label": "体标"}, {"form": "补偿过", "label": "体标"}, {"form": "補償", "label": "繁体"}, {"form": "补偿金", "label": "复合"}], "register": "中性", "sense_fingerprint": "补偿：弄坏别人的东西后，给对方东西或钱作为赔偿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94201, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "补偿", "is_correct": true, "explanation": "正确答案：补偿（bǔ cháng），指弄坏别人的东西后，给对方东西或钱作为赔偿。"}, {"text": "步长", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是步子的长度。"}, {"text": "不长", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是不长。"}, {"text": "不畅", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，cháng（第二声）与 chàng（第四声）声调也不同，意思是不通畅。"}, {"text": "不常", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是不经常。"}], "explanations": {"补偿": "正确答案：补偿（bǔ cháng），指弄坏别人的东西后，给对方东西或钱作为赔偿。", "步长": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是步子的长度。", "不长": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是不长。", "不畅": "bǔ（第三声）与 bù（第四声）声调不同，cháng（第二声）与 chàng（第四声）声调也不同，意思是不通畅。", "不常": "bǔ（第三声）与 bù（第四声）声调不同，意思是不经常。"}, "sentence_index": null, "correct_answer": "补偿"}, "level_3": {"options": [{"text": "补偿", "is_correct": true, "explanation": "补偿：弄坏朋友的相机后，买新的赔给他，与句中的“买了新的来”相合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“买了新的”是赔给对方的行为，与批评对方的意思矛盾。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：惩罚是让犯错的人吃苦头，与“买了新的”的赔偿行为不符。"}, {"text": "原谅", "is_correct": false, "explanation": "搭配：“原谅”的对象是过错，不能靠买新东西来实现。"}], "explanations": {"补偿": "补偿：弄坏朋友的相机后，买新的赔给他，与句中的“买了新的来”相合。", "批评": "语义：“买了新的”是赔给对方的行为，与批评对方的意思矛盾。", "惩罚": "语义：惩罚是让犯错的人吃苦头，与“买了新的”的赔偿行为不符。", "原谅": "搭配：“原谅”的对象是过错，不能靠买新东西来实现。"}, "sentence_index": 0, "correct_answer": "补偿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把坏了的书包补偿好了。", "explanation": "这里应该用〈修理〉。补偿是给对方东西或钱作为赔偿，不能用来指把坏东西修好。"}, {"text": "老板补偿了他的努力。", "explanation": "这里应该用〈奖励〉。补偿是弥补损失，不能用来表示对努力的酬谢。"}, {"text": "今天天气很好，我们去公园补偿吧。", "explanation": "这里应该用〈散步〉。补偿是弄坏别人东西后给对方赔偿，不能表示游玩活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94201, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "补偿", "is_correct": true, "explanation": "正确答案：补偿（bǔ cháng），指弄坏别人的东西后，给对方东西或钱作为赔偿。"}, {"text": "不唱", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，chàng（第四声）与 cháng（第二声）声调也不同，意思是不唱歌。"}, {"text": "不常", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是不经常。"}, {"text": "不尝", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是没有尝过。"}], "explanations": {"补偿": "正确答案：补偿（bǔ cháng），指弄坏别人的东西后，给对方东西或钱作为赔偿。", "不唱": "bù（第四声）与 bǔ（第三声）声调不同，chàng（第四声）与 cháng（第二声）声调也不同，意思是不唱歌。", "不常": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是不经常。", "不尝": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是没有尝过。"}, "sentence_index": null, "correct_answer": "补偿"}, "level_3": {"options": [{"text": "补偿", "is_correct": true, "explanation": "补偿：摔坏老师的眼镜后，想买新的赔给她，与句意相合。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑对方，与“想买新的”赔偿的意图不合。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：责怪是怪罪对方，与“我不小心”的过失语境相反。"}, {"text": "夸奖", "is_correct": false, "explanation": "搭配：“夸奖”的内容应是人的优点或成绩，不能说因为买新的东西而夸奖。"}], "explanations": {"补偿": "补偿：摔坏老师的眼镜后，想买新的赔给她，与句意相合。", "嘲笑": "语义：嘲笑是取笑对方，与“想买新的”赔偿的意图不合。", "责怪": "语义：责怪是怪罪对方，与“我不小心”的过失语境相反。", "夸奖": "搭配：“夸奖”的内容应是人的优点或成绩，不能说因为买新的东西而夸奖。"}, "sentence_index": 6, "correct_answer": "补偿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每天要喝牛奶，补偿身体需要的营养。", "explanation": "这里应该用〈补充〉。补偿是弥补损失或赔给对方东西，给身体补充营养要说补充。"}, {"text": "他进步很大，老师补偿了他的进步。", "explanation": "这里应该用〈夸奖〉。补偿是弥补损失，不能用来表示对进步的称赞。"}, {"text": "大家都来补偿你的成功。", "explanation": "这里应该用〈祝贺〉。补偿用于弥补损失，不能用来表示对成功的庆贺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不小心踩坏了你的伞，买了一把新的来补偿了你。", "corrected_sentence": "我不小心踩坏了你的伞，买了一把新的来补偿你。", "error_description": "错误在于“补偿”后面多了“了”。目的小句中应说“来补偿你”，不能说“来补偿了你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟把同学的风筝弄坏了，买了一个新的来补偿着同学。", "corrected_sentence": "弟弟把同学的风筝弄坏了，买了一个新的来补偿同学。", "error_description": "错误在于“补偿”后多了“着”。目的小句中应说“来补偿同学”，不能说“来补偿着同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
