INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94202, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对损失、差额或亏欠给予弥补。", "primary_collocate": null, "pronunciation": "bǔ cháng", "ipa": "pu˨˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "公司给工人补偿了这个月少发的钱。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在别的地方努力工作，来补偿这次的损失。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天没陪孩子，周末要好好补偿他。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的错让你多等了，请让我补偿你一顿饭。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂关门了，老板给大家补偿了三个月工资。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子要拆了，政府会补偿一笔钱。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机晚点了，航空公司补偿了乘客两百元。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没能参加婚礼，就送了礼物来补偿。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格涨了，国家给低收入家庭补偿了一部分钱。", "target_word": "补偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我欠了你很多，以后一定补偿你。", "target_word": "补偿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "补偿了", "label": "体标"}, {"form": "补偿过", "label": "体标"}, {"form": "補償", "label": "繁体"}, {"form": "补偿金", "label": "复合"}], "register": "中性", "sense_fingerprint": "补偿：对损失、差额或亏欠给予弥补", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94202, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "补偿", "is_correct": true, "explanation": "正确答案：补偿（bǔ cháng），指对损失、差额或亏欠给予弥补。"}, {"text": "步长", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是步子的长度。"}, {"text": "不长", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是不长。"}, {"text": "不畅", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，cháng（第二声）与 chàng（第四声）声调也不同，意思是不通畅。"}, {"text": "不常", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是不经常。"}], "explanations": {"补偿": "正确答案：补偿（bǔ cháng），指对损失、差额或亏欠给予弥补。", "步长": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是步子的长度。", "不长": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是不长。", "不畅": "bǔ（第三声）与 bù（第四声）声调不同，cháng（第二声）与 chàng（第四声）声调也不同，意思是不通畅。", "不常": "bǔ（第三声）与 bù（第四声）声调不同，意思是不经常。"}, "sentence_index": null, "correct_answer": "补偿"}, "level_3": {"options": [{"text": "补偿", "is_correct": true, "explanation": "补偿：对少发的工资给予弥补，与句意相合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是地方或展览，不能说参观少发的钱。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：“表彰”是公开赞扬，与工资被少发的语境不合。"}, {"text": "赠送", "is_correct": false, "explanation": "搭配：“赠送”的对象是礼物，不能用来说赠送应发的工资。"}], "explanations": {"补偿": "补偿：对少发的工资给予弥补，与句意相合。", "参观": "搭配：“参观”的对象是地方或展览，不能说参观少发的钱。", "表彰": "语义：“表彰”是公开赞扬，与工资被少发的语境不合。", "赠送": "搭配：“赠送”的对象是礼物，不能用来说赠送应发的工资。"}, "sentence_index": 0, "correct_answer": "补偿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的加班时间补偿了不少。", "explanation": "这里应该用〈增加〉。补偿是弥补损失或亏欠，表示数量上升要用增加。"}, {"text": "他的英语水平补偿了很多。", "explanation": "这里应该用〈提高〉。补偿用于弥补损失，表示水平上升要用提高。"}, {"text": "期末考得好，老师补偿了我一本书。", "explanation": "这里应该用〈奖励〉。补偿用于弥补损失或亏欠，不能用来表示因成绩好而给的奖赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94202, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "补偿", "is_correct": true, "explanation": "正确答案：补偿（bǔ cháng），指对损失、差额或亏欠给予弥补。"}, {"text": "不唱", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，chàng（第四声）与 cháng（第二声）声调也不同，意思是不唱歌。"}, {"text": "部长", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，zhǎng（第三声）与 cháng（第二声）声母和声调都不同，意思是政府部门的负责人。"}, {"text": "不尝", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是没有尝过。"}], "explanations": {"补偿": "正确答案：补偿（bǔ cháng），指对损失、差额或亏欠给予弥补。", "不唱": "bù（第四声）与 bǔ（第三声）声调不同，chàng（第四声）与 cháng（第二声）声调也不同，意思是不唱歌。", "部长": "bù（第四声）与 bǔ（第三声）声调不同，zhǎng（第三声）与 cháng（第二声）声母和声调都不同，意思是政府部门的负责人。", "不尝": "bù（第四声）与 bǔ（第三声）声调不同，cháng 相同，意思是没有尝过。"}, "sentence_index": null, "correct_answer": "补偿"}, "level_3": {"options": [{"text": "补偿", "is_correct": true, "explanation": "补偿：飞机晚点后，航空公司给乘客两百元作弥补，与句意相合。"}, {"text": "处罚", "is_correct": false, "explanation": "语义：乘客没有过错，航空公司处罚乘客与晚点的语境不符。"}, {"text": "没收", "is_correct": false, "explanation": "语义：“没收”是强制拿走，与航空公司对乘客的弥补方向相反。"}, {"text": "抚恤", "is_correct": false, "explanation": "语域：“抚恤”是对伤亡者及其家属的书面用语，与晚点的口语语境不合。"}], "explanations": {"补偿": "补偿：飞机晚点后，航空公司给乘客两百元作弥补，与句意相合。", "处罚": "语义：乘客没有过错，航空公司处罚乘客与晚点的语境不符。", "没收": "语义：“没收”是强制拿走，与航空公司对乘客的弥补方向相反。", "抚恤": "语域：“抚恤”是对伤亡者及其家属的书面用语，与晚点的口语语境不合。"}, "sentence_index": 6, "correct_answer": "补偿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一定要补偿你的帮助。", "explanation": "这里应该用〈感谢〉。补偿用于弥补损失，不能用来表达对帮助的谢意。"}, {"text": "老师补偿了他的进步。", "explanation": "这里应该用〈赞扬〉。补偿是弥补损失，不能用于称赞进步。"}, {"text": "老板补偿了员工的努力。", "explanation": "这里应该用〈奖励〉。补偿是弥补损失，不能用于对努力的酬谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板给员工补偿着上个月少发的奖金。", "corrected_sentence": "老板给员工补偿了上个月少发的奖金。", "error_description": "错误在于“补偿”后用了“着”。补偿是一次性完成的动作，已完成时应用“了”，不说“补偿着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "商场关门了，老板补偿起来每位顾客一张优惠券。", "corrected_sentence": "商场关门了，老板补偿了每位顾客一张优惠券。", "error_description": "错误在于“补偿”后用了“起来”。这里是已经完成的给予，应说“补偿了”，不能说“补偿起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
