INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说服是好好讲道理，让别人愿意听你的。", "primary_collocate": null, "pronunciation": "shuō fú", "ipa": "ʂwo˥ fu˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈耐心地说服了弟弟。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想说服女朋友搬过来。", "target_word": "说服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说服不了我的孩子早点睡觉。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要用道理说服别人，不能生气。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说服了同事一起去旅行。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会说服别人。", "target_word": "说服", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我花了一个小时才说服他。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也说服不了固执的爷爷。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板想说服大家加班。", "target_word": "说服", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我试着说服她，可是没有成功。", "target_word": "说服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说服了", "label": "体标"}, {"form": "说服过", "label": "体标"}, {"form": "说服力", "label": "复合"}], "register": "中性", "sense_fingerprint": "讲道理让别人愿意听从自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说服", "is_correct": true, "explanation": "正确：「耐心地说服了弟弟」指耐心讲道理使弟弟同意，句意通顺。"}, {"text": "打", "is_correct": false, "explanation": "语义：「耐心地」与「打」的动作相矛盾，句意不通。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：「耐心地」与「忽视」语义相反，「耐心地忽视弟弟」自相矛盾。"}, {"text": "修", "is_correct": false, "explanation": "搭配：「修」的对象是器物，不能用于「弟弟」这样的人。"}], "explanations": {"说服": "正确：「耐心地说服了弟弟」指耐心讲道理使弟弟同意，句意通顺。", "打": "语义：「耐心地」与「打」的动作相矛盾，句意不通。", "忽视": "语义：「耐心地」与「忽视」语义相反，「耐心地忽视弟弟」自相矛盾。", "修": "搭配：「修」的对象是器物，不能用于「弟弟」这样的人。"}, "sentence_index": 0, "correct_answer": "说服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他狠狠说服了孩子一顿。", "explanation": "这里应该用〈打〉。说服是讲道理使人同意，不是动手打人。"}, {"text": "他说服了我一顿。", "explanation": "这里应该用〈骂〉。说服是讲道理使人同意，不是责骂；「说服」不能与「一顿」搭配，「骂了我一顿」才自然。"}, {"text": "他认真说服了这个现象的原因。", "explanation": "这里应该用〈分析〉。说服的对象是人，分析现象的原因要用分析。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说服", "is_correct": true, "explanation": "正确：「才说服他」表示花了一小时之后才使他同意，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，「吃他」句意荒谬。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」指用牙齿，与「花了一个小时才……他」的语境不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食物，不能用于「他」这样的人。"}], "explanations": {"说服": "正确：「才说服他」表示花了一小时之后才使他同意，句意通顺。", "吃": "语义：「吃」指进食，「吃他」句意荒谬。", "咬": "语义：「咬」指用牙齿，与「花了一个小时才……他」的语境不符。", "煮": "搭配：「煮」的对象是食物，不能用于「他」这样的人。"}, "sentence_index": 6, "correct_answer": "说服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们还要再说服一下这个计划。", "explanation": "这里应该用〈讨论〉。说服的对象是人，讨论计划要用讨论。"}, {"text": "老师说服了很多道理。", "explanation": "这里应该用〈讲〉。说服的对象是人，讲道理要用讲。"}, {"text": "他说服了那辆自行车。", "explanation": "这里应该用〈修〉。说服的对象是人，不能用于自行车；修理自行车要用修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很快得说服了弟弟同意。", "corrected_sentence": "我很快说服了弟弟同意。", "error_description": "错误：多加了「得」。「很快」已是状语，后面直接接动词「说服」即可，「得」是补语标记，用在这里是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了很久才把我说服我。", "corrected_sentence": "他花了很久才把我说服。", "error_description": "错误：宾语“我”重复了。用了“把我”以后，“说服”后面不能再带“我”，应写作“才把我说服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
