INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用理由使对方信服并接受自己的意见。", "primary_collocate": null, "pronunciation": "shuō fú", "ipa": "ʂwo˥ fu˧˥", "syllable_count": 2, "sentences": [{"text": "我说服了他参加比赛。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用事实说服了大家。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你很难说服他改变主意。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理终于说服了客户。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说服我继续学中文。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想说服爸爸买新电脑。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话没有说服我。", "target_word": "说服", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你说服不了她。", "target_word": "说服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师用证据说服了法官。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友说服我去看医生。", "target_word": "说服", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "说服了", "label": "体标"}, {"form": "说服过", "label": "体标"}, {"form": "说服力", "label": "复合"}], "register": "中性", "sense_fingerprint": "用理由或事实使对方信服并接受意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说服", "is_correct": true, "explanation": "正确：「说服了他参加比赛」指用道理让他同意参赛，句意通顺。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：「原谅」要求对方有过错，「参加比赛」不是过错，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」作用于器物或故障，「修理他参加比赛」搭配不当。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是场所或物品，不能用于「他参加比赛」这类动作。"}], "explanations": {"说服": "正确：「说服了他参加比赛」指用道理让他同意参赛，句意通顺。", "原谅": "语义：「原谅」要求对方有过错，「参加比赛」不是过错，句意不通。", "修理": "搭配：「修理」作用于器物或故障，「修理他参加比赛」搭配不当。", "打扫": "搭配：「打扫」的对象是场所或物品，不能用于「他参加比赛」这类动作。"}, "sentence_index": 0, "correct_answer": "说服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仔细说服了这个问题。", "explanation": "这里应该用〈解释〉。说服的对象是人，要使对方接受意见；讲清问题要用解释。"}, {"text": "他用力说服了那扇门。", "explanation": "这里应该用〈打开〉。说服只用于人，不能用于门等物体；推门要用打开。"}, {"text": "我们终于说服了这个难关。", "explanation": "这里应该用〈克服〉。说服的对象是人，克服困难要用克服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说服", "is_correct": true, "explanation": "正确：「没有说服我」表示他的话未能使我同意，句意通顺。"}, {"text": "治疗", "is_correct": false, "explanation": "搭配：「治疗」的对象是病症或病人，不能让「话」作主语去治疗「我」。"}, {"text": "送", "is_correct": false, "explanation": "语义：「送」指给予或陪同，「他的话没有送我」句意荒谬。"}, {"text": "雇", "is_correct": false, "explanation": "语义：「雇」需要雇主作主语，「话」不能雇人，句意不通。"}], "explanations": {"说服": "正确：「没有说服我」表示他的话未能使我同意，句意通顺。", "治疗": "搭配：「治疗」的对象是病症或病人，不能让「话」作主语去治疗「我」。", "送": "语义：「送」指给予或陪同，「他的话没有送我」句意荒谬。", "雇": "语义：「雇」需要雇主作主语，「话」不能雇人，句意不通。"}, "sentence_index": 6, "correct_answer": "说服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说服了一口流利的英语。", "explanation": "这里应该用〈说〉。说服表示用道理使人同意，表示说话、讲外语要用说。"}, {"text": "他用例子说服了这个概念。", "explanation": "这里应该用〈说明〉。说服的对象是人，讲清一个概念要用说明。"}, {"text": "他们为这件事说服了一架。", "explanation": "这里应该用〈吵〉。说服是使对方接受意见，不是争执；「为这件事吵了一架」自然，「说服了一架」不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我终于说服着妹妹参加长跑。", "corrected_sentence": "我终于说服了妹妹参加长跑。", "error_description": "错误：“终于”表示动作已完成，应与“了”搭配，写作“说服了妹妹”；用“着”表示持续，与“终于”矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一个人说服得了不弟弟。", "corrected_sentence": "我一个人说服不了弟弟。", "error_description": "错误：表示「不能说服」要用可能补语的否定式「说服不了」，「不」放在「说服」和「了」之间；「说服得了不」语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
