INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "起点是开始的地方。", "primary_collocate": null, "pronunciation": "qǐ diǎn", "ipa": "tɕʰi˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "跑步比赛的起点在学校门口。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁一号线的起点是这个车站。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从这条路的起点开始走。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的起点在哪里？", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在起点，等老师说开始。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起点离我家很近，走路五分钟。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们骑自行车从起点出发。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的起点和终点都在同一个地方。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在地图上找一下起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起点的旁边有一家小商店。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "起点站", "label": "复合"}, {"form": "起點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "路线或比赛开始的具体地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb3a0d9-08c8-4e7f-bd40-b28ca5c44dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指比赛开始的具体地点，“比赛的起点在学校门口”符合语境。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是上课的场所，不能用来指比赛的地点。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时刻，不能说“在学校门口”，与具体地点的语境不符。"}, {"text": "名次", "is_correct": false, "explanation": "搭配：“名次”指比赛的结果，不能说“名次在学校门口”。"}], "explanations": {"起点": "正确：“起点”指比赛开始的具体地点，“比赛的起点在学校门口”符合语境。", "教室": "语义：“教室”是上课的场所，不能用来指比赛的地点。", "时间": "语义：“时间”指时刻，不能说“在学校门口”，与具体地点的语境不符。", "名次": "搭配：“名次”指比赛的结果，不能说“名次在学校门口”。"}, "sentence_index": 0, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的起点是友谊。", "explanation": "义项：“起点”指具体的地点，不指抽象的事物；说抽象的开始要用“开端”。"}, {"text": "比赛的起点是三点。", "explanation": "义项：“起点”指具体的地点，不指时刻；说比赛开始的时间要用“开始”。"}, {"text": "这条路有一只起点。", "explanation": "量词：“起点”应该用量词“个”，“只”不能用于“起点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指出发的具体地点，“从起点出发”符合语境。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“答案”是抽象的结果，不能作为骑车出发的地点。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是骑自行车出发的地点，与具体的出发点不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是地点，不能说“从天气出发”。"}], "explanations": {"起点": "正确：“起点”指出发的具体地点，“从起点出发”符合语境。", "答案": "搭配：“答案”是抽象的结果，不能作为骑车出发的地点。", "天空": "语义：“天空”不是骑自行车出发的地点，与具体的出发点不符。", "天气": "搭配：“天气”不是地点，不能说“从天气出发”。"}, "sentence_index": 6, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的起点很好吃。", "explanation": "义项：“起点”指开始的地点，不是食物，不能说“好吃”。"}, {"text": "这条路的起点是三个朋友。", "explanation": "义项：“起点”指地点，不指人；说人群要用“人们”。"}, {"text": "这条路有一位起点。", "explanation": "量词：“起点”应该用量词“个”，“位”用于人，不能用于“起点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的一只起点在山上。", "corrected_sentence": "这条河的起点在山上。", "error_description": "多了量词短语：“起点”前面不能加“一只”，应直接说“这条河的起点在山上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在起点们集合，然后出发。", "corrected_sentence": "他们在起点集合，然后出发。", "error_description": "错误：“们”只用于指人的名词或代词，不能加在“起点”后面。正确：“他们在起点集合，然后出发。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终点", "is_correct": true, "explanation": "正确：“终点”与“起点”构成反义，指事情结束或行程结束的地方。"}, {"text": "花园", "is_correct": false, "explanation": "无关：“花园”是具体场所，与“起点”的开始义不构成反义。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是具体物件，与“起点”没有反义关系。"}, {"text": "答案", "is_correct": false, "explanation": "无关：“答案”是抽象名词，与“起点”没有反义关系。"}], "correct_answer": "终点", "explanations": {"终点": "正确：“终点”与“起点”构成反义，指事情结束或行程结束的地方。", "花园": "无关：“花园”是具体场所，与“起点”的开始义不构成反义。", "窗户": "无关：“窗户”是具体物件，与“起点”没有反义关系。", "答案": "无关：“答案”是抽象名词，与“起点”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终点", "is_correct": true, "explanation": "正确：“终点”与“起点”构成反义，指行程或事情结束的地方。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是具体家具，与“起点”没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "无关：“天空”是自然景物，与“起点”没有反义关系。"}, {"text": "数字", "is_correct": false, "explanation": "无关：“数字”是抽象名词，与“起点”没有反义关系。"}], "correct_answer": "终点", "explanations": {"终点": "正确：“终点”与“起点”构成反义，指行程或事情结束的地方。", "桌子": "无关：“桌子”是具体家具，与“起点”没有反义关系。", "天空": "无关：“天空”是自然景物，与“起点”没有反义关系。", "数字": "无关：“数字”是抽象名词，与“起点”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情、事业或过程开始的阶段或时间。", "primary_collocate": null, "pronunciation": "qǐ diǎn", "ipa": "tɕʰi˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次工作是他事业的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高中毕业不是结束，是新生活的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的习惯是成功的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的起点不一样，不要和别人比。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小店是他做生意的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从零开始也可以是一个好的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好拼音是学汉语的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次见面是我们友谊的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起点低没关系，只要努力就能进步。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败也是他重新开始的起点。", "target_word": "起点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "起点站", "label": "复合"}, {"form": "起點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事业、学习等抽象过程的开始阶段或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb3a0d9-08c8-4e7f-bd40-b28ca5c44dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指事情开始的地方或时间，“事业的起点”符合语境。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”是场所，不能用来指事业的开始阶段，与“起点”的抽象义不符。"}, {"text": "错误", "is_correct": false, "explanation": "语义：“错误”指失误，不能用来指事业的开始阶段。"}, {"text": "口号", "is_correct": false, "explanation": "语义：“口号”是宣传用的话，不能说成事业的开始阶段。"}], "explanations": {"起点": "正确：“起点”指事情开始的地方或时间，“事业的起点”符合语境。", "地点": "语义：“地点”是场所，不能用来指事业的开始阶段，与“起点”的抽象义不符。", "错误": "语义：“错误”指失误，不能用来指事业的开始阶段。", "口号": "语义：“口号”是宣传用的话，不能说成事业的开始阶段。"}, "sentence_index": 0, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "成功的起点很好吃。", "explanation": "义项：“起点”指事情开始的阶段，不是食物，不能说“好吃”。"}, {"text": "他事业的起点穿着一件红衣服。", "explanation": "义项：“起点”指开始的阶段，不是人，不能“穿衣服”。"}, {"text": "这次工作是他事业的一只起点。", "explanation": "量词：“起点”应该用量词“个”，“只”用于动物或成对的东西，不能用于“起点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "正确：“起点”指开始的阶段，“学汉语的起点”符合语境。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：“停车场”是具体场所，不能用来指学习的开始。"}, {"text": "车库", "is_correct": false, "explanation": "语义：“车库”是存放车辆的场所，与“学汉语”的抽象义不符。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”多用于商品，不能说“学汉语的包装”。"}], "explanations": {"起点": "正确：“起点”指开始的阶段，“学汉语的起点”符合语境。", "停车场": "语义：“停车场”是具体场所，不能用来指学习的开始。", "车库": "语义：“车库”是存放车辆的场所，与“学汉语”的抽象义不符。", "包装": "搭配：“包装”多用于商品，不能说“学汉语的包装”。"}, "sentence_index": 6, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行的起点很长。", "explanation": "义项：“起点”指地点或时间，不能用“长”来形容；说长短要用“路程”或“时间”。"}, {"text": "旅行的起点是三天。", "explanation": "义项：“起点”指开始的地方或时间，不是持续的时长；“三天”是时长。"}, {"text": "学汉语的起点很聪明。", "explanation": "义项：“起点”指开始的阶段，不是人，不能用“聪明”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找到了一只新的起点。", "corrected_sentence": "他找到了一个新的起点。", "error_description": "量词错误：“起点”应该用量词“个”，“只”用于动物或成对的东西，不能用于“起点”，应为“一个新的起点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这次经历当作一个的新起点。", "corrected_sentence": "他把这次经历当作一个新的起点。", "error_description": "语序错误：“新的”是修饰“起点”的定语，应为“一个新的起点”；“的新”颠倒了“新”和“的”的位置，不能成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94214, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "闭幕", "is_correct": true, "explanation": "闭幕与开幕相对，指会议、展览、演出等活动正式结束，是反义词。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指离开某地上路，与“开幕”没有反义关系。"}, {"text": "举办", "is_correct": false, "explanation": "“举办”指组织进行某项活动，与“开幕”同属相关动作，但不是反义词。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”指看表演或比赛，与“开幕”没有反义关系。"}], "correct_answer": "闭幕", "explanations": {"闭幕": "闭幕与开幕相对，指会议、展览、演出等活动正式结束，是反义词。", "出发": "“出发”指离开某地上路，与“开幕”没有反义关系。", "举办": "“举办”指组织进行某项活动，与“开幕”同属相关动作，但不是反义词。", "观看": "“观看”指看表演或比赛，与“开幕”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94214, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "闭幕", "is_correct": true, "explanation": "闭幕与开幕相对，指活动正式结束，是反义词。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指深入探讨问题，与“开幕”没有反义关系。"}, {"text": "取消", "is_correct": false, "explanation": "“取消”指不再进行原定的安排，与“开幕”不构成反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "“等待”指耐心守候，与“开幕”没有反义关系。"}], "correct_answer": "闭幕", "explanations": {"闭幕": "闭幕与开幕相对，指活动正式结束，是反义词。", "研究": "“研究”指深入探讨问题，与“开幕”没有反义关系。", "取消": "“取消”指不再进行原定的安排，与“开幕”不构成反义关系。", "等待": "“等待”指耐心守候，与“开幕”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94214, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "会议、展览或演出等开始。", "primary_collocate": null, "pronunciation": "kāi mù", "ipa": "kʰaɪ˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "国际电影节明天晚上八点开幕。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次书展在上海开幕了。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会下周一上午在北京开幕。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐节开幕那天，很多人来看表演。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会开幕以后，学生们都很高兴。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览九点开幕，我们八点半就到了。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋季博览会将在广州开幕。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话剧节昨天开幕，我买到了票。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术节开幕时，天气特别好。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，画展推迟到周六开幕。", "target_word": "开幕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开幕了", "label": "体标"}, {"form": "开幕式", "label": "复合"}, {"form": "开幕词", "label": "复合"}], "register": "中性", "sense_fingerprint": "会议、展览、演出等活动正式开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a3a156-5f7f-41d1-8849-8ba4ee2579e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开幕", "is_correct": true, "explanation": "“开幕”指电影节正式开始，与“明天晚上八点”搭配，符合句意。"}, {"text": "开学", "is_correct": false, "explanation": "语义：“开学”指学校开始上课，国际电影节不会开学。"}, {"text": "开业", "is_correct": false, "explanation": "搭配：“开业”用于商店、公司等开门营业，不能用于电影节。"}, {"text": "开工", "is_correct": false, "explanation": "语义：“开工”指工厂或工程开始动工，与电影节活动不符。"}], "explanations": {"开幕": "“开幕”指电影节正式开始，与“明天晚上八点”搭配，符合句意。", "开学": "语义：“开学”指学校开始上课，国际电影节不会开学。", "开业": "搭配：“开业”用于商店、公司等开门营业，不能用于电影节。", "开工": "语义：“开工”指工厂或工程开始动工，与电影节活动不符。"}, "sentence_index": 0, "correct_answer": "开幕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂下个月开幕，可以招很多工人。", "explanation": "这里应该用〈开工〉。开幕用于展览、会议、演出等活动，工厂开始生产或施工要说开工。"}, {"text": "新学期下周开幕，学生们都很期待。", "explanation": "这里应该用〈开学〉。开幕指活动正式开始，学校新学期开始上课要说开学。"}, {"text": "新地铁线下周开幕，市民们都很期待。", "explanation": "这里应该用〈开通〉。开幕用于活动，地铁线路、道路等开始运行要说开通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开幕", "is_correct": true, "explanation": "“开幕”指博览会正式开始，符合“将在广州”的句意。"}, {"text": "开课", "is_correct": false, "explanation": "语义：“开课”指学校、培训班开始上课，博览会不能说开课。"}, {"text": "开播", "is_correct": false, "explanation": "搭配：“开播”用于电视台、电台的节目，博览会不说开播。"}, {"text": "开航", "is_correct": false, "explanation": "搭配：“开航”用于船只、航线等交通路线，博览会不能开航。"}], "explanations": {"开幕": "“开幕”指博览会正式开始，符合“将在广州”的句意。", "开课": "语义：“开课”指学校、培训班开始上课，博览会不能说开课。", "开播": "搭配：“开播”用于电视台、电台的节目，博览会不说开播。", "开航": "搭配：“开航”用于船只、航线等交通路线，博览会不能开航。"}, "sentence_index": 6, "correct_answer": "开幕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部新电视剧下周开幕，观众很期待。", "explanation": "这里应该用〈开播〉。开幕用于大型活动，电视剧、节目开始播出要说开播。"}, {"text": "这门新课下个月开幕，报名的人很多。", "explanation": "这里应该用〈开课〉。开幕用于大型活动，课程开始上课要说开课。"}, {"text": "这部新电影下周开幕，很多人都想去看。", "explanation": "这里应该用〈上映〉。开幕用于活动，电影在影院开始放映要说上映。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天下午把画展开幕。", "corrected_sentence": "明天下午画展开幕。", "error_description": "错误：“开幕”是不及物动词，不能带“把”字结构。应说“明天下午画展开幕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博览会明天在广州开幕了。", "corrected_sentence": "博览会明天在广州开幕。", "error_description": "错误：“明天”指将来，“开幕”后不能加“了”。应说“博览会明天在广州开幕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
