INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94215, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "阴谋是坏人偷偷想好的、要害别人的计划。", "primary_collocate": null, "pronunciation": "yīn móu", "ipa": "in˥ moʊ˧˥", "syllable_count": 2, "sentences": [{"text": "坏人想出了一个阴谋。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现了他们的阴谋。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个要害死他的阴谋。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板早就知道了你的阴谋。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的坏人有一个大阴谋。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们偷偷想了一个阴谋，要害那个好人。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明听到了坏人的阴谋。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个阴谋太可怕了，我们要告诉警察。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的阴谋没有成功。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人为了钱，想出了害朋友的阴谋。", "target_word": "阴谋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "阴谋家", "label": "复合词"}, {"form": "阴谋论", "label": "复合词"}], "register": "中性", "sense_fingerprint": "坏人偷偷想好的、用来害人的计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23290bf5-6828-47ec-9731-af1e3e5fe151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阴谋", "is_correct": true, "explanation": "阴谋指坏人偷偷想好的、要害别人的计划，与“坏人想出了一个”的语境相符。"}, {"text": "善意", "is_correct": false, "explanation": "语义：“善意”指好心，与“坏人”矛盾，句子说的是要害人的计划。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“想出”说的是计划、办法，不能用于笑容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是坏人能想出来的事。"}], "explanations": {"阴谋": "阴谋指坏人偷偷想好的、要害别人的计划，与“坏人想出了一个”的语境相符。", "善意": "语义：“善意”指好心，与“坏人”矛盾，句子说的是要害人的计划。", "笑容": "搭配：“想出”说的是计划、办法，不能用于笑容。", "天气": "语义：天气是自然现象，不是坏人能想出来的事。"}, "sentence_index": 0, "correct_answer": "阴谋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生为病人制定了一个周密的阴谋，帮助他尽快康复。", "explanation": "这里应该用〈方案〉。阴谋指坏人暗中策划、要害别人的计划，救治病人的正当安排要用方案，不能用阴谋。"}, {"text": "这家公司为了发展，制定了新的阴谋。", "explanation": "这里应该用〈策略〉。阴谋含有害人的意思，正当的公司经营要用策略，不能用阴谋。"}, {"text": "消防员冒着浓烟发动了一次救援阴谋，救出了三名孩子。", "explanation": "这里应该用〈行动〉。阴谋指坏人要害别人的计划，消防员的救援是正当的，应说救援行动，不能用阴谋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阴谋", "is_correct": true, "explanation": "阴谋指坏人偷偷想好的、要害别人的计划，与“坏人的”相符，是听到的内容。"}, {"text": "光芒", "is_correct": false, "explanation": "搭配：“听到”用于声音、消息，不能用于光芒。"}, {"text": "善心", "is_correct": false, "explanation": "语义：“善心”是好心，与“坏人”矛盾，句子说的是要害人的计划。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“听到”不能接体温这样的对象。"}], "explanations": {"阴谋": "阴谋指坏人偷偷想好的、要害别人的计划，与“坏人的”相符，是听到的内容。", "光芒": "搭配：“听到”用于声音、消息，不能用于光芒。", "善心": "语义：“善心”是好心，与“坏人”矛盾，句子说的是要害人的计划。", "体温": "搭配：“听到”不能接体温这样的对象。"}, "sentence_index": 6, "correct_answer": "阴谋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是公司里最有名的阴谋，大家都很怕他。", "explanation": "这里应该用〈阴谋家〉。阴谋是计划，不能指人，指做阴谋的人要说阴谋家。"}, {"text": "老师和同学们一起想了一个阴谋，周末去公园打扫卫生。", "explanation": "这里应该用〈计划〉。阴谋指坏人偷偷想好、要害别人的计划，大家一起去打扫公园是好事，要用计划，不能用阴谋。"}, {"text": "这个城市的交通阴谋很完善，大家出行都很方便。", "explanation": "这里应该用〈计划〉。阴谋指坏人要害别人的计划，城市的交通安排是正当的，不能用阴谋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想出了一块阴谋，但被警察识破了。", "corrected_sentence": "他们想出了一个阴谋，但被警察识破了。", "error_description": "量词错误：“阴谋”应搭配量词“个”或“场”，不能用“块”（“块”用于块状的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家终于识破了那群人的一块阴谋。", "corrected_sentence": "大家终于识破了那群人的一个阴谋。", "error_description": "量词错误：“阴谋”应搭配量词“个”或“场”，不能用“块”（“块”用于块状的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f7da343-aff2-41d7-a0c8-03400183b1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
