INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94217, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94217, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "随意是想怎么做就怎么做，没有人管。", "primary_collocate": null, "pronunciation": "suí yì", "ipa": "swei˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "在自己家里，你可以随意一点。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不在，同学们都很随意。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末没人管我，我过得很随意。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有规定，穿衣服很随意。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家吃饭很随意，想坐哪儿就坐哪儿。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出差了，弟弟在家很随意，吃饭睡觉都不用按时。", "target_word": "随意", "complexity_tier": "T3", "furigana": "bà ba chū chāi le, dì di zài jiā hěn suí yì, chī fàn shuì jiào dōu bú yòng àn shí.", "sentence_source": "generated"}, {"text": "这个小饭馆没有人管，客人都很随意。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是老朋友，说话不用客气，随意就好。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里没人管你几点起床，生活很随意。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶不管我，所以我在她家很随意。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "随意地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "随意：形容人的言行放松自在，想怎么做就怎么做，没有人管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc88ea3-cc81-44ee-a2a6-03befb6fb706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随意", "is_correct": true, "explanation": "随意：放松自在、想怎么做就怎么做，正符合“在自己家里”的语境。"}, {"text": "拘谨", "is_correct": false, "explanation": "语义：拘谨指不自然、放不开，与“在自己家里你可以……一点”的放松语境相反。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：紧张表示心里不安，家里本应是放松的地方，句中不能这样用。"}, {"text": "庄重", "is_correct": false, "explanation": "语域：庄重是正式、郑重的语域，用在家里说“一点”很不协调。"}], "explanations": {"随意": "随意：放松自在、想怎么做就怎么做，正符合“在自己家里”的语境。", "拘谨": "语义：拘谨指不自然、放不开，与“在自己家里你可以……一点”的放松语境相反。", "紧张": "语义：紧张表示心里不安，家里本应是放松的地方，句中不能这样用。", "庄重": "语域：庄重是正式、郑重的语域，用在家里说“一点”很不协调。"}, "sentence_index": 0, "correct_answer": "随意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题很随意，大家都做得很快。", "explanation": "这里应该用〈简单〉。随意指不受约束、想怎么做就怎么做，不能用来形容题目的难易。"}, {"text": "这次考试很重要，你要随意地准备。", "explanation": "这里应该用〈认真〉。随意指放松、不拘束，不能用来形容对待重要事情的态度。"}, {"text": "第一次见老师，他很紧张，坐得很随意。", "explanation": "这里应该用〈拘束〉。紧张时人放不开，与“随意”（自在、不受约束）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随意", "is_correct": true, "explanation": "随意：不拘束、按自己的意思来，符合“没有人管”的语境。"}, {"text": "拘束", "is_correct": false, "explanation": "语义：拘束指不自由、放不开，与“没有人管”的自由气氛相反。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：严肃表示态度郑重，与饭馆里没人管、随便的气氛冲突。"}, {"text": "正式", "is_correct": false, "explanation": "语域：正式是规范、庄重的书面语域，用来形容小饭馆里的客人很不协调。"}], "explanations": {"随意": "随意：不拘束、按自己的意思来，符合“没有人管”的语境。", "拘束": "语义：拘束指不自由、放不开，与“没有人管”的自由气氛相反。", "严肃": "语义：严肃表示态度郑重，与饭馆里没人管、随便的气氛冲突。", "正式": "语域：正式是规范、庄重的书面语域，用来形容小饭馆里的客人很不协调。"}, "sentence_index": 6, "correct_answer": "随意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文的论证很随意，每个结论都有数据支持。", "explanation": "这里应该用〈严谨〉。随意表示不受约束、想怎么来就怎么来，不能用来形容论证的周密程度。"}, {"text": "老板对数据的核对要求很随意，每个数字都要复查。", "explanation": "这里应该用〈严格〉。随意表示不受约束，不能用来形容核对数据的要求。"}, {"text": "这次面试的流程很随意，每个环节都有固定的时间表。", "explanation": "这里应该用〈规范〉。随意指不受约束，不能用来形容流程的正式程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿很随意。", "corrected_sentence": "他穿得很随意。", "error_description": "错误：「穿很随意」；正确：「穿得很随意」。“随意”作“穿”的补语时，动词后要加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们随意的聊了一会儿。", "corrected_sentence": "我们随意地聊了一会儿。", "error_description": "错误：「随意的聊」；正确：「随意地聊」。“随意”修饰动词作状语时用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
