INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94218, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由着自己的意思，不加限制。", "primary_collocate": null, "pronunciation": "suí yì", "ipa": "swei˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "请大家随意坐，不用客气。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单上的菜，你可以随意选。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的书可以随意翻看。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的花不能随意摘。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书不能随意带出去。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间很大，东西可以随意放。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的时间，你可以随意安排。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛没有规则，大家可以随意发挥。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家店，客人可以随意试穿衣服。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小路上不能随意停车。", "target_word": "随意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "随意地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "随意：修饰动作，表示按自己的意思做，不受限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc88ea3-cc81-44ee-a2a6-03befb6fb706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随意", "is_correct": true, "explanation": "随意：不拘束地按自己的意思坐，符合“不用客气”的语境。"}, {"text": "笔直", "is_correct": false, "explanation": "体貌：笔直形容身体或线条挺直，与“不用客气”的放松坐法不符。"}, {"text": "拘谨", "is_correct": false, "explanation": "语义：拘谨指放不开，与“不用客气”的语境直接冲突。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：整齐多用于修饰排列或队伍，不用来说人坐的方式。"}], "explanations": {"随意": "随意：不拘束地按自己的意思坐，符合“不用客气”的语境。", "笔直": "体貌：笔直形容身体或线条挺直，与“不用客气”的放松坐法不符。", "拘谨": "语义：拘谨指放不开，与“不用客气”的语境直接冲突。", "整齐": "搭配：整齐多用于修饰排列或队伍，不用来说人坐的方式。"}, "sentence_index": 0, "correct_answer": "随意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学题的答案是随意的，每道题只有一个正确答案。", "explanation": "这里应该用〈唯一〉。随意指不受限制、可以任意选择，与“只有一个正确答案”矛盾。"}, {"text": "这门课的考试时间很随意，每个人都要在规定时间内交卷。", "explanation": "这里应该用〈固定〉。随意指不受限制，不能用来形容考试时间的安排。"}, {"text": "这台机器的开关很随意，每次操作都要按照说明书的顺序进行。", "explanation": "这里应该用〈规范〉。随意指不受限制，不能用来形容开关的操作方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随意", "is_correct": true, "explanation": "随意：按自己的意思安排，不受限制，符合“你可以”的语境。"}, {"text": "严格", "is_correct": false, "explanation": "语义：严格表示不容许变动，与“你可以”允许自由安排的语境冲突。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：呆板指不灵活，与“你可以”的自由语境相矛盾。"}, {"text": "拘束", "is_correct": false, "explanation": "语义：拘束指不自由、放不开，不能用来修饰“安排”，与“你可以……”允许自由安排的语境不合。"}], "explanations": {"随意": "随意：按自己的意思安排，不受限制，符合“你可以”的语境。", "严格": "语义：严格表示不容许变动，与“你可以”允许自由安排的语境冲突。", "呆板": "语义：呆板指不灵活，与“你可以”的自由语境相矛盾。", "拘束": "语义：拘束指不自由、放不开，不能用来修饰“安排”，与“你可以……”允许自由安排的语境不合。"}, "sentence_index": 6, "correct_answer": "随意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同很重要，签字以前你要随意地看一遍。", "explanation": "这里应该用〈仔细〉。随意指不加限制、想怎样就怎样，与“合同很重要”要求认真阅读的语境矛盾。"}, {"text": "这份实验方案的步骤很随意，每一步都要事先写清楚。", "explanation": "这里应该用〈周密〉。随意指不受限制，不能用来形容方案的周密程度。"}, {"text": "这个实验的结果很随意，所有数据都要重复测量三次。", "explanation": "这里应该用〈可靠〉。随意指不受限制，不能用来形容实验结果的可信度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他随意的坐在角落里。", "corrected_sentence": "他随意地坐在角落里。", "error_description": "错误：「随意的坐」；正确：「随意地坐」。“随意”修饰动词作状语时用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他翻书翻很随意。", "corrected_sentence": "他翻书翻得很随意。", "error_description": "错误：「翻书翻很随意」；正确：「翻书翻得很随意」。“随意”作补语时，动词后要加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
