INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94219, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94219, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "露出是让原来被盖着的东西让人看见。", "primary_collocate": null, "pronunciation": "lù chū", "ipa": "lu˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这件衣服太短，一弯腰就会露出肚子。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手伸出来，袖子里露出一块手表。", "target_word": "露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裤子破了，露出了里面的皮肤。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上的白灰掉了，露出了里面的红砖。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一笑，就露出了一口白牙。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把头发拿开，露出了耳朵。", "target_word": "露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地毯拿走以后，地上露出了一块旧木板。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把盖着的布拿开，露出了一幅画。", "target_word": "露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袜子破了，露出了脚趾。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风吹走了沙子，露出了一个小盒子。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "露出了", "label": "体标"}, {"form": "露出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "露出：原来被盖着的东西让人看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94219, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "露出", "is_correct": true, "explanation": "正确答案：露出（lù chū），指原来被盖着的东西让人看见。"}, {"text": "漏出", "is_correct": false, "explanation": "lù（第四声）与 lòu（第四声）韵母不同（ù 与 ou），意思是液体或气体泄漏出去。"}, {"text": "录取", "is_correct": false, "explanation": "chū（第一声）与 qǔ（第三声）声母和声调不同，意思是录用。"}, {"text": "吐出", "is_correct": false, "explanation": "lù（第四声）与 tǔ（第三声）声母和声调不同，意思是从口中吐出来。"}, {"text": "数出", "is_correct": false, "explanation": "lù（第四声）与 shǔ（第三声）声母和声调都不同（l 与 sh），意思是一个一个数出来。"}], "explanations": {"露出": "正确答案：露出（lù chū），指原来被盖着的东西让人看见。", "漏出": "lù（第四声）与 lòu（第四声）韵母不同（ù 与 ou），意思是液体或气体泄漏出去。", "录取": "chū（第一声）与 qǔ（第三声）声母和声调不同，意思是录用。", "吐出": "lù（第四声）与 tǔ（第三声）声母和声调不同，意思是从口中吐出来。", "数出": "lù（第四声）与 shǔ（第三声）声母和声调都不同（l 与 sh），意思是一个一个数出来。"}, "sentence_index": null, "correct_answer": "露出"}, "level_3": {"options": [{"text": "露出", "is_correct": true, "explanation": "露出：衣服太短，弯腰后肚子就显现出来，与句意相合。"}, {"text": "遮住", "is_correct": false, "explanation": "语义：衣服太短遮不住肚子，“遮住”与句中的“太短”矛盾。"}, {"text": "显示", "is_correct": false, "explanation": "搭配：“显示”的对象是信息、实力等，不能说显示肚子。"}, {"text": "挡住", "is_correct": false, "explanation": "语义：衣服太短不能挡住肚子，“挡住”与句意矛盾。"}], "explanations": {"露出": "露出：衣服太短，弯腰后肚子就显现出来，与句意相合。", "遮住": "语义：衣服太短遮不住肚子，“遮住”与句中的“太短”矛盾。", "显示": "搭配：“显示”的对象是信息、实力等，不能说显示肚子。", "挡住": "语义：衣服太短不能挡住肚子，“挡住”与句意矛盾。"}, "sentence_index": 0, "correct_answer": "露出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "报告露出了收入增长的情况。", "explanation": "这里应该用〈显示〉。露出指原来被盖着的东西让人看见，报告的内容是呈现出来的，要说显示。"}, {"text": "屋里露出了一阵笑声。", "explanation": "这里应该用〈传出〉。露出指原来被盖着的东西让人看见，笑声是传出来的，不能说露出。"}, {"text": "音箱露出了巨大的声音。", "explanation": "这里应该用〈发出〉。声音是发出来的，露出用于原来被盖着的东西让人看见，不能用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "露出", "is_correct": true, "explanation": "露出：地毯拿走后，原来盖着的木板显现出来，与句意相合。"}, {"text": "盖住", "is_correct": false, "explanation": "语义：地毯拿走后，地上应当显出东西，“盖住”与“拿走”的语境相反。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”表示用肩搬运，不能说在地上扛木板。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”表示移动东西，与句中地上显现东西的语境不符。"}], "explanations": {"露出": "露出：地毯拿走后，原来盖着的木板显现出来，与句意相合。", "盖住": "语义：地毯拿走后，地上应当显出东西，“盖住”与“拿走”的语境相反。", "扛": "搭配：“扛”表示用肩搬运，不能说在地上扛木板。", "搬": "语义：“搬”表示移动东西，与句中地上显现东西的语境不符。"}, "sentence_index": 6, "correct_answer": "露出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他露出了一篇文章。", "explanation": "这里应该用〈写出〉。露出指让原来被盖着的东西被看见，文章是写出来的，不能说露出。"}, {"text": "工匠露出了一把椅子。", "explanation": "这里应该用〈造出〉。椅子是造出来的，露出不能表示制造。"}, {"text": "政府露出了新政策。", "explanation": "这里应该用〈宣布〉。政策是宣布出来的，露出指让被盖着的东西被看见，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把外套脱下来，露出得了里面的毛衣。", "corrected_sentence": "她把外套脱下来，露出了里面的毛衣。", "error_description": "错误在于“露出”后多加了“得”。应说“露出了里面的毛衣”，不能在中间插入“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把布掀开，露出了着一台旧机器。", "corrected_sentence": "老板把布掀开，露出了一台旧机器。", "error_description": "错误在于“露出了”后又加了“着”（“了着”不能连用）。应只用“了”，即“露出了一台旧机器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "隐藏：使东西不被看见，与露出的意思相反。"}, {"text": "收集", "is_correct": false, "explanation": "收集：把分散的东西聚到一起，与露出的意思无关。"}, {"text": "思考", "is_correct": false, "explanation": "思考：用脑子想问题，与露出的意思无关。"}, {"text": "奔跑", "is_correct": false, "explanation": "奔跑：快速地跑动，与露出的意思无关。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "隐藏：使东西不被看见，与露出的意思相反。", "收集": "收集：把分散的东西聚到一起，与露出的意思无关。", "思考": "思考：用脑子想问题，与露出的意思无关。", "奔跑": "奔跑：快速地跑动，与露出的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "隐藏：使东西不被看见，与露出的意思相反。"}, {"text": "散步", "is_correct": false, "explanation": "散步：随意地慢慢走，与露出的意思无关。"}, {"text": "呼吸", "is_correct": false, "explanation": "呼吸：吸入和呼出空气，与露出的意思无关。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：在水中划动身体前进，与露出的意思无关。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "隐藏：使东西不被看见，与露出的意思相反。", "散步": "散步：随意地慢慢走，与露出的意思无关。", "呼吸": "呼吸：吸入和呼出空气，与露出的意思无关。", "游泳": "游泳：在水中划动身体前进，与露出的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94220, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使隐藏的部分显现出来。", "primary_collocate": null, "pronunciation": "lù chū", "ipa": "lu˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他一听这个笑话，脸上露出了笑容。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说了谎，终于露出了马脚。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个好消息，她露出了开心的样子。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到考试成绩，他脸上露出了失望的表情。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一紧张，就露出了害怕的样子。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝多了，露出了心里的秘密。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话里露出了不想去的意思。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的眼睛里露出了一点担心。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说起家乡，老人脸上露出了温暖的笑容。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到新玩具，孩子的脸上露出了好奇的神情。", "target_word": "露出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "露出了", "label": "体标"}, {"form": "露出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "露出：原来隐藏的部分显现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94220, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "露出", "is_correct": true, "explanation": "正确答案：露出（lù chū），指使隐藏的部分显现出来。"}, {"text": "漏出", "is_correct": false, "explanation": "lù（第四声）与 lòu（第四声）韵母不同（ù 与 ou），意思是液体或气体泄漏出去。"}, {"text": "录取", "is_correct": false, "explanation": "chū（第一声）与 qǔ（第三声）声母和声调不同，意思是录用。"}, {"text": "吐出", "is_correct": false, "explanation": "lù（第四声）与 tǔ（第三声）声母和声调不同，意思是从口中吐出来。"}, {"text": "数出", "is_correct": false, "explanation": "lù（第四声）与 shǔ（第三声）声母和声调都不同（l 与 sh），意思是一个一个数出来。"}], "explanations": {"露出": "正确答案：露出（lù chū），指使隐藏的部分显现出来。", "漏出": "lù（第四声）与 lòu（第四声）韵母不同（ù 与 ou），意思是液体或气体泄漏出去。", "录取": "chū（第一声）与 qǔ（第三声）声母和声调不同，意思是录用。", "吐出": "lù（第四声）与 tǔ（第三声）声母和声调不同，意思是从口中吐出来。", "数出": "lù（第四声）与 shǔ（第三声）声母和声调都不同（l 与 sh），意思是一个一个数出来。"}, "sentence_index": null, "correct_answer": "露出"}, "level_3": {"options": [{"text": "露出", "is_correct": true, "explanation": "露出：听了笑话后，笑容显现在脸上，与句意相合。"}, {"text": "吞下", "is_correct": false, "explanation": "搭配：“吞下”的对象是食物或东西，不能说吞下笑容。"}, {"text": "沉下", "is_correct": false, "explanation": "搭配：“沉下”多用于脸色，不能说“沉下笑容”。"}, {"text": "撕下", "is_correct": false, "explanation": "搭配：“撕下”的对象是纸张或贴着的东西，不能说撕下笑容。"}], "explanations": {"露出": "露出：听了笑话后，笑容显现在脸上，与句意相合。", "吞下": "搭配：“吞下”的对象是食物或东西，不能说吞下笑容。", "沉下": "搭配：“沉下”多用于脸色，不能说“沉下笑容”。", "撕下": "搭配：“撕下”的对象是纸张或贴着的东西，不能说撕下笑容。"}, "sentence_index": 0, "correct_answer": "露出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试结果露出了他的进步。", "explanation": "这里应该用〈显示〉。露出指原来隐藏的部分显现，考试结果呈现的是进步，要说显示。"}, {"text": "收音机里露出了熟悉的声音。", "explanation": "这里应该用〈发出〉。声音是发出来的，露出指原来隐藏的东西显现，不能说露出声音。"}, {"text": "火山露出了一阵轰鸣。", "explanation": "这里应该用〈发出〉。轰鸣是发出的声音，露出指原来隐藏的部分显现，不能用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "露出", "is_correct": true, "explanation": "露出：原来隐藏的意思在话里显现，与句意相合。"}, {"text": "消化", "is_correct": false, "explanation": "语义：“消化”的主体多为人或胃，“话里消化”句意不通。"}, {"text": "关", "is_correct": false, "explanation": "搭配：“关”的对象是门窗、开关之类，不能说关了意思。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”的对象是信件、包裹之类，不能说拆开意思。"}], "explanations": {"露出": "露出：原来隐藏的意思在话里显现，与句意相合。", "消化": "语义：“消化”的主体多为人或胃，“话里消化”句意不通。", "关": "搭配：“关”的对象是门窗、开关之类，不能说关了意思。", "拆开": "搭配：“拆开”的对象是信件、包裹之类，不能说拆开意思。"}, "sentence_index": 6, "correct_answer": "露出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作家露出了一本小说。", "explanation": "这里应该用〈写出〉。露出指使隐藏的部分显现出来，小说是写出来的，不能说露出一本小说。"}, {"text": "她露出了美妙的歌声。", "explanation": "这里应该用〈唱出〉。歌声是唱出来的，露出指使隐藏的部分显现，不能用于歌声。"}, {"text": "厨师露出了一道好菜。", "explanation": "这里应该用〈做出〉。菜是做出来的，露出指使隐藏的部分显现，不能表示制作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一看到礼物，脸上就露出了着开心的表情。", "corrected_sentence": "他一看到礼物，脸上就露出了开心的表情。", "error_description": "错误在于“露出了”后又加了“着”（“了着”不能连用）。应只用“了”，即“脸上就露出了开心的表情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听完消息，眼睛里露出得了高兴的神色。", "corrected_sentence": "他听完消息，眼睛里露出了高兴的神色。", "error_description": "错误在于“露出”后多加了“得”。“露出”后应直接接“了”，不能说“露出得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
