INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某些国家内阁的最高首长。", "primary_collocate": null, "pronunciation": "shǒu xiàng", "ipa": "ʂoʊ˨˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "首相是内阁的最高首长。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内阁成员都要听首相的安排。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相带着几位部长去开会。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会选出了新的首相。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有国王，也有首相。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相在会上介绍了内阁的新计划。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相让部长们准备一份报告。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相今天上午召开了内阁会议。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加拿大的首相是内阁的领导人。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相需要得到议会的支持。", "target_word": "首相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "副首相", "label": "复合"}, {"form": "前首相", "label": "复合"}, {"form": "首相府", "label": "复合"}], "register": "正式", "sense_fingerprint": "内阁制国家中内阁的最高领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a3a156-5f7f-41d1-8849-8ba4ee2579e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首相", "is_correct": true, "explanation": "“首相”指内阁制国家内阁的最高首长，与句意一致。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是房间，不是内阁的最高首长。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，不能充当内阁的首长。"}, {"text": "大楼", "is_correct": false, "explanation": "搭配：“最高首长”指人，大楼不能充当。"}], "explanations": {"首相": "“首相”指内阁制国家内阁的最高首长，与句意一致。", "办公室": "语义：办公室是房间，不是内阁的最高首长。", "房子": "语义：房子是建筑物，不能充当内阁的首长。", "大楼": "搭配：“最高首长”指人，大楼不能充当。"}, "sentence_index": 0, "correct_answer": "首相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王先生是我们国家新的首相，负责教育工作。", "explanation": "这里应该用〈部长〉。首相是内阁的最高首长，不负责某一个部门；负责教育的部门首长叫部长。"}, {"text": "学生会新选出的首相昨天开了会。", "explanation": "这里应该用〈主席〉。学生会、协会等团体的领导人叫主席，不叫首相。"}, {"text": "中国新选出的首相今天上任了。", "explanation": "这里应该用〈总理〉。中国政府的首脑称为总理，不叫首相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首相", "is_correct": true, "explanation": "“首相”是内阁的最高首长，能够让部长们准备报告，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能让部长们做事。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能让部长们做事。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“让”要求能指使他人的施事，小猫不能指使部长。"}], "explanations": {"首相": "“首相”是内阁的最高首长，能够让部长们准备报告，符合句意。", "天气": "语义：天气是自然现象，不能让部长们做事。", "冰箱": "语义：冰箱是家电，不能让部长们做事。", "小猫": "配价：“让”要求能指使他人的施事，小猫不能指使部长。"}, "sentence_index": 6, "correct_answer": "首相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的首相需要得到工人的支持。", "explanation": "这里应该用〈厂长〉。首相是国家政府的首脑，工厂的负责人叫厂长。"}, {"text": "这家医院的首相需要得到医生的支持。", "explanation": "这里应该用〈院长〉。医院的负责人叫院长，首相只用于国家政府。"}, {"text": "这个县的首相需要得到县议会的支持。", "explanation": "这里应该用〈县长〉。县的行政首长叫县长，首相用于国家政府。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两支首相昨天都来了。", "corrected_sentence": "两位首相昨天都来了。", "error_description": "量词错误：“首相”指人，量词应用“位”，不能用“支”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条首相明天要去访问美国。", "corrected_sentence": "这位首相明天要去访问美国。", "error_description": "量词错误：“首相”指人，量词应用“位”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
