INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94225, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "惊讶是遇到想不到的事，吃了一惊。", "primary_collocate": null, "pronunciation": "jīng yà", "ipa": "tɕiŋ˥ ia˥˩", "syllable_count": 2, "sentences": [{"text": "听到这个消息，我很惊讶。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到老朋友，惊讶地叫了一声。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩这么好，大家都很惊讶。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我惊讶地发现，门没有关。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然来了，妈妈有点惊讶。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那么大的雪，弟弟惊讶极了。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用这么惊讶，这只是个小礼物。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话让我很惊讶。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脸上露出惊讶的样子。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都惊讶地看着他。", "target_word": "惊讶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驚訝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到想不到的事而吃惊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54747f1c-7f82-48a2-943c-930173304b61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惊讶", "is_correct": true, "explanation": "正确。「惊讶」表示遇到想不到的事而吃惊，与听到消息的反应相符。"}, {"text": "饿", "is_correct": false, "explanation": "语义：「饿」指想吃东西，与听到消息后的心理反应不符。"}, {"text": "困", "is_correct": false, "explanation": "语义：「困」指想睡觉，与听到消息的反应无关。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：「美丽」形容外貌，不能用来描述听到消息时的心理反应。"}], "explanations": {"惊讶": "正确。「惊讶」表示遇到想不到的事而吃惊，与听到消息的反应相符。", "饿": "语义：「饿」指想吃东西，与听到消息后的心理反应不符。", "困": "语义：「困」指想睡觉，与听到消息的反应无关。", "美丽": "体貌：「美丽」形容外貌，不能用来描述听到消息时的心理反应。"}, "sentence_index": 0, "correct_answer": "惊讶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都惊讶地起床去上班。", "explanation": "「惊讶」只用于出乎意料的事，每天起床去上班是日常，没有意外，不能用「惊讶」。"}, {"text": "我惊讶地发现太阳从东边升起。", "explanation": "「惊讶」只用于出乎意料的事，太阳从东边升起是常识，不能用「惊讶」。"}, {"text": "每次下雨，我都惊讶地带伞。", "explanation": "「惊讶」只用于出乎意料的事，每次下雨都带伞是习惯，不能用「惊讶」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惊讶", "is_correct": true, "explanation": "正确。「惊讶」表示因意外而吃惊，与「你不用这么……」的语境相符。"}, {"text": "粗糙", "is_correct": false, "explanation": "体貌：「粗糙」形容质地或表面，不能用来形容对礼物的态度。"}, {"text": "深刻", "is_correct": false, "explanation": "语义：「深刻」形容印象或道理，与「不用这么……」的语境不搭。"}, {"text": "方便", "is_correct": false, "explanation": "语义：「方便」指便利，与对礼物的反应无关，句子不通。"}], "explanations": {"惊讶": "正确。「惊讶」表示因意外而吃惊，与「你不用这么……」的语境相符。", "粗糙": "体貌：「粗糙」形容质地或表面，不能用来形容对礼物的态度。", "深刻": "语义：「深刻」形容印象或道理，与「不用这么……」的语境不搭。", "方便": "语义：「方便」指便利，与对礼物的反应无关，句子不通。"}, "sentence_index": 6, "correct_answer": "惊讶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提前一个月订好了机票，出发时我惊讶地检查行李。", "explanation": "「惊讶」只用于出乎意料的事，提前订好的行程在计划之内，不能用「惊讶」。"}, {"text": "我每天早上都惊讶地刷牙，这已经是多年的习惯了。", "explanation": "「惊讶」只用于出乎意料的事，每天刷牙是习惯，没有意外，不能用「惊讶」。"}, {"text": "我早就知道要上台领奖，所以惊讶地走上了台。", "explanation": "「惊讶」只用于出乎意料的事，事先已知的安排不是意外，不能用「惊讶」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他脸上露出惊讶地神情。", "corrected_sentence": "他脸上露出惊讶的神情。", "error_description": "修饰语标记错误：「惊讶」修饰名词「神情」时要用「的」，「地」只用于修饰动词或形容词，应写作「惊讶的神情」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他惊讶的张大了嘴。", "corrected_sentence": "他惊讶得张大了嘴。", "error_description": "补语标记错误：「惊讶得」引出程度补语，应写作「惊讶得张大了嘴」；「的」用于名词前，不能用在此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
