INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一时是很短的一小段时间。", "primary_collocate": null, "pronunciation": "yì shí", "ipa": "i˥˩ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这首歌曾经流行一时。", "target_word": "一时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那部电影轰动一时，大家都去看。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别因为一时的冲动，做出后悔的事。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一时的快乐不等于长久的幸福。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只是一时的困难，很快会过去的。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只是一时的失败，以后还有机会。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一时的任性让妈妈很难过。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要为了一时的方便，伤害环境。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种玩具风靡一时，现在没人买了。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小城的旅游曾经热闹一时。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，指很短的一段时间，常见于流行一时、一时的冲动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一时", "is_correct": true, "explanation": "一时（yì shí）：很短的一段时间。"}, {"text": "衣食", "is_correct": false, "explanation": "衣食（yī shí）：第一音节声调不同（yī 与 yì），意思是衣服和食物。"}, {"text": "依时", "is_correct": false, "explanation": "依时（yī shí）：第一音节声调不同（yī 与 yì），意思是按时、准时。"}, {"text": "一事", "is_correct": false, "explanation": "一事（yì shì）：第二音节声调不同（shí 与 shì），意思是一件事。"}], "explanations": {"一时": "一时（yì shí）：很短的一段时间。", "衣食": "衣食（yī shí）：第一音节声调不同（yī 与 yì），意思是衣服和食物。", "依时": "依时（yī shí）：第一音节声调不同（yī 与 yì），意思是按时、准时。", "一事": "一事（yì shì）：第二音节声调不同（shí 与 shì），意思是一件事。"}, "sentence_index": null, "correct_answer": "一时"}, "level_3": {"options": [{"text": "一时", "is_correct": true, "explanation": "一时：一段很短的时间。这里表示这首歌流行的时间很短。"}, {"text": "一个人", "is_correct": false, "explanation": "语义：「流行」不能与「一个人」搭配，句子不通。"}, {"text": "一棵树", "is_correct": false, "explanation": "语义：「流行」说的是事物受欢迎，不能与「一棵树」搭配。"}, {"text": "一瓶水", "is_correct": false, "explanation": "搭配：「流行」不能带「一瓶水」这样的数量短语作宾语。"}], "explanations": {"一时": "一时：一段很短的时间。这里表示这首歌流行的时间很短。", "一个人": "语义：「流行」不能与「一个人」搭配，句子不通。", "一棵树": "语义：「流行」说的是事物受欢迎，不能与「一棵树」搭配。", "一瓶水": "搭配：「流行」不能带「一瓶水」这样的数量短语作宾语。"}, "sentence_index": 0, "correct_answer": "一时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一时的成功持续了五十年。", "explanation": "这里应该用〈一生〉。一时指很短的一段时间，不能用来说五十年这样的长时段。"}, {"text": "学习外语是一时的事，要坚持很多年。", "explanation": "这里应该用〈长期〉。一时表示短暂，与「坚持很多年」矛盾；需要多年坚持要用长期。"}, {"text": "他的一时声望永远不会消失。", "explanation": "这里应该用〈长久〉。一时指很短的一段时间，不能用来修饰不会消失的声望；长久存在的声望要用长久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一时", "is_correct": true, "explanation": "一时的：暂时的，短暂的。这里修饰「任性」，表示暂时的任性。"}, {"text": "一个", "is_correct": false, "explanation": "搭配：「一个」是量词短语，不能直接修饰「任性」，句子不通。"}, {"text": "一股", "is_correct": false, "explanation": "语义：「一股」多修饰气味、力量等，不能修饰「任性」。"}, {"text": "一腔", "is_correct": false, "explanation": "语义：「一腔」多修饰情感或热血，与「任性」搭配不当。"}], "explanations": {"一时": "一时的：暂时的，短暂的。这里修饰「任性」，表示暂时的任性。", "一个": "搭配：「一个」是量词短语，不能直接修饰「任性」，句子不通。", "一股": "语义：「一股」多修饰气味、力量等，不能修饰「任性」。", "一腔": "语义：「一腔」多修饰情感或热血，与「任性」搭配不当。"}, "sentence_index": 6, "correct_answer": "一时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个小城的旅游一时的热闹，永远不会结束。", "explanation": "这里应该用〈长久〉。一时指短暂的一段时间，不能用来描述不会结束的热闹；不会结束的状态要用长久。"}, {"text": "那个小城的历史一时的悠久。", "explanation": "这里不能用〈一时〉。一时指很短的一段时间，不能修饰悠久的历史；说历史长久要用长久。"}, {"text": "那个小城的旅游一时的兴盛持续了一百年。", "explanation": "这里应该用〈长久〉。一时指很短的一段时间，不能修饰持续了一百年的兴盛；长时间持续要用长久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅曾经红火一时的。", "corrected_sentence": "这家餐厅曾经红火一时。", "error_description": "错误：「一时」之后多加了「的」，句末的「的」没有中心词，句子不完整。正确：应写作「这家餐厅曾经红火一时。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款手机很风靡一时，现在没人用了。", "corrected_sentence": "这款手机风靡一时，现在没人用了。", "error_description": "错误：副词「很」放在了动词「风靡」之前。正确：「风靡」不能被「很」修饰，应写作「风靡一时」，中间不加「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
