INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94228, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "短时间；暂时。", "primary_collocate": null, "pronunciation": "yì shí", "ipa": "i˥˩ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "我一时想不起他的名字。", "target_word": "一时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一时没听懂老师的话。", "target_word": "一时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事太突然，我一时不知道怎么办。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到这么多人，他一时说不出话来。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一时找不到钥匙，只好等朋友来开门。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一时高兴，买了很多东西。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题很难，一时很难解决。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一时生气，说了不该说的话。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一时糊涂，把钱借给了陌生人。", "target_word": "一时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，我们一时走不了。", "target_word": "一时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，指一小段时间内暂时的状态，常见于一时想不起来、一时说不出话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0cf54a7-0afe-42d5-a594-db103a67f3f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94228, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一时", "is_correct": true, "explanation": "一时（yì shí）：短时间；暂时。"}, {"text": "衣食", "is_correct": false, "explanation": "衣食（yī shí）：第一音节声调不同（yī 与 yì），意思是衣服和食物。"}, {"text": "依时", "is_correct": false, "explanation": "依时（yī shí）：第一音节声调不同（yī 与 yì），意思是按时、准时。"}, {"text": "一事", "is_correct": false, "explanation": "一事（yì shì）：第二音节声调不同（shí 与 shì），意思是一件事。"}], "explanations": {"一时": "一时（yì shí）：短时间；暂时。", "衣食": "衣食（yī shí）：第一音节声调不同（yī 与 yì），意思是衣服和食物。", "依时": "依时（yī shí）：第一音节声调不同（yī 与 yì），意思是按时、准时。", "一事": "一事（yì shì）：第二音节声调不同（shí 与 shì），意思是一件事。"}, "sentence_index": null, "correct_answer": "一时"}, "level_3": {"options": [{"text": "一时", "is_correct": true, "explanation": "一时：短时间内，暂时。这里表示暂时想不起他的名字。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：「正在」表示动作进行中，「想不起」是一种状态，不能用进行体修饰。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或心理动词，不能修饰「想不起」。"}, {"text": "很快", "is_correct": false, "explanation": "语义：「很快」表示迅速发生，与「想不起」这种持续的状态不合。"}], "explanations": {"一时": "一时：短时间内，暂时。这里表示暂时想不起他的名字。", "正在": "体貌：「正在」表示动作进行中，「想不起」是一种状态，不能用进行体修饰。", "非常": "搭配：「非常」修饰形容词或心理动词，不能修饰「想不起」。", "很快": "语义：「很快」表示迅速发生，与「想不起」这种持续的状态不合。"}, "sentence_index": 0, "correct_answer": "一时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一时住在北京十年了。", "explanation": "这里应该用〈一直〉。一时指很短的一段时间，不能用来说明十年这样的长时段。"}, {"text": "我一时会去北京。", "explanation": "这里应该用〈总有一天〉。一时指很短的一段时间，不能指将来某个不确定的时间；说将来的不确定时间要用总有一天。"}, {"text": "这门手艺一时传了三百年。", "explanation": "这里应该用〈一直〉。一时指很短的一段时间，与「传了三百年」的长时段矛盾；长时段持续要用一直。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_