INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一时", "is_correct": true, "explanation": "一时：暂时。这里表示问题暂时很难解决。"}, {"text": "终于", "is_correct": false, "explanation": "语义：「终于」表示经过较长过程后最终实现，与「很难解决」的持续状态冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与「很难解决」这样的状态不搭。"}, {"text": "反复", "is_correct": false, "explanation": "搭配：「反复」修饰动作，不能修饰「很难解决」这样的状态。"}], "explanations": {"一时": "一时：暂时。这里表示问题暂时很难解决。", "终于": "语义：「终于」表示经过较长过程后最终实现，与「很难解决」的持续状态冲突。", "偶尔": "语义：「偶尔」表示不常发生，与「很难解决」这样的状态不搭。", "反复": "搭配：「反复」修饰动作，不能修饰「很难解决」这样的状态。"}, "sentence_index": 6, "correct_answer": "一时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一时永远住在这里。", "explanation": "这里应该用〈一直〉。一时表示暂时，不能用来说明长久持续的状态；长久持续要用一直。"}, {"text": "他一时出生在北京。", "explanation": "这里不能用〈一时〉。一时表示暂时的状态，出生是一次性的事实，没有暂时不暂时；应去掉一时，说「他出生在北京」。"}, {"text": "这座桥一时建了五百年。", "explanation": "这里应该用〈已经〉。一时指很短的一段时间，与「建了五百年」的长时段矛盾；说明到目前为止的时长要用已经。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一时的想不起这件事的细节。", "corrected_sentence": "我一时想不起这件事的细节。", "error_description": "错误：「一时」作状语修饰动词时，后面不能加「的」，「一时的」变成定语，不能修饰「想不起」。正确：应写作「我一时想不起」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很一时着急，忘了带钥匙。", "corrected_sentence": "她一时着急，忘了带钥匙。", "error_description": "错误：「一时」是副词，前面不能再加程度副词「很」，「很一时」不成词。正确：应写作「她一时着急」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2688b55a-0a23-48fe-83a5-801a1a7eb119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
