INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94230, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "三回，表示动作重复三遍。", "primary_collocate": null, "pronunciation": "sān cì", "ipa": "san˥˥ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "请你再说三次。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们读三次课文。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个字写了三次。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我算了三次，答案不变。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门铃按了三次，没人开门。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈叫了他三次，他才起床。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这句话重复三次。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌我听了三次才学会。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他检查了三次，还是错了。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个动作都要练三次。", "target_word": "三次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第三次", "label": "序数"}], "register": "中性", "sense_fingerprint": "同一动作重复进行三遍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b63a56-8ab2-40e1-be94-f37f7483128e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三次", "is_correct": true, "explanation": "“三次”表示同一动作重复的遍数，与“再说”搭配，说明再说几遍。"}, {"text": "三斤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，不能用来数说话的遍数。"}, {"text": "三米", "is_correct": false, "explanation": "语义：“米”是长度单位，与说话的遍数无关。"}, {"text": "三楼", "is_correct": false, "explanation": "语义：“三楼”指楼层，不能表示再说的次数。"}], "explanations": {"三次": "“三次”表示同一动作重复的遍数，与“再说”搭配，说明再说几遍。", "三斤": "搭配：“斤”是重量单位，不能用来数说话的遍数。", "三米": "语义：“米”是长度单位，与说话的遍数无关。", "三楼": "语义：“三楼”指楼层，不能表示再说的次数。"}, "sentence_index": 0, "correct_answer": "三次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈三次生下了我。", "explanation": "此处不能用〈三次〉。“生下”只发生一次，“三次”表示重复多次，与句意冲突。"}, {"text": "这个公司的利润是去年的三次。", "explanation": "此处应该用〈三倍〉。“次”表示动作重复的遍数，不能用来表示利润的倍数。"}, {"text": "他三次出生在上海。", "explanation": "此处不能用〈三次〉。“出生”只发生一次，“三次”表示重复多次，与句意冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三次", "is_correct": true, "explanation": "“三次”表示同一动作重复的遍数，与“重复”搭配，说明重复几遍。"}, {"text": "三张", "is_correct": false, "explanation": "搭配：“张”用于纸张、桌子等平面物件，不能用来量“重复”。"}, {"text": "三岁", "is_correct": false, "explanation": "语义：“三岁”说年龄，与重复这句话的遍数无关。"}, {"text": "三元", "is_correct": false, "explanation": "语义：“三元”是钱数，不能用来表示重复的遍数。"}], "explanations": {"三次": "“三次”表示同一动作重复的遍数，与“重复”搭配，说明重复几遍。", "三张": "搭配：“张”用于纸张、桌子等平面物件，不能用来量“重复”。", "三岁": "语义：“三岁”说年龄，与重复这句话的遍数无关。", "三元": "语义：“三元”是钱数，不能用来表示重复的遍数。"}, "sentence_index": 6, "correct_answer": "三次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他三次去世了。", "explanation": "此处不能用〈三次〉。“去世”只发生一次，“三次”表示重复多次，与句意冲突。"}, {"text": "我的存款是去年的三次。", "explanation": "此处应该用〈三倍〉。“次”表示遍数，不能用来表示存款的倍数。"}, {"text": "我三次第一次去北京。", "explanation": "此处不能用〈三次〉。“第一次”已表示初次，与“三次”的重复义冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又把这句话念了三次次。", "corrected_sentence": "他又把这句话念了三次。", "error_description": "错误形式：“三次次”，“次”重复多加一个；正确形式：“三次”，“次”本身就是量词，后面不能再加“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天练习钢琴三次个。", "corrected_sentence": "他每天练习钢琴三次。", "error_description": "错误形式：“三次个”，“次”后多加了量词“个”；正确形式：“三次”，“次”本身就是量词，后面不能再加其他量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94231, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上一次", "is_correct": true, "explanation": "反义：上一次与下一次方向相反，构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "与“下一次”没有反义关系，二者不构成对立。"}, {"text": "课本", "is_correct": false, "explanation": "与“下一次”没有反义关系，二者不构成对立。"}, {"text": "闹钟", "is_correct": false, "explanation": "与“下一次”没有反义关系，二者不构成对立。"}], "correct_answer": "上一次", "explanations": {"上一次": "反义：上一次与下一次方向相反，构成反义。", "周末": "与“下一次”没有反义关系，二者不构成对立。", "课本": "与“下一次”没有反义关系，二者不构成对立。", "闹钟": "与“下一次”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
