INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下一次是接着现在这一回以后的那一回。", "primary_collocate": null, "pronunciation": "xià yí cì", "ipa": "ɕja˥˩ i˧˥ tsʰɨ˥˩", "syllable_count": 3, "sentences": [{"text": "下一次我一定早点来。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次我请客，下一次你请。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一次考试在下个月。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天没时间，下一次再去吧。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一次见面，我给你带茶。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次没赢，下一次一定能赢。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一次你想去哪儿玩？", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我下一次会把作业写完。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一次的会议改到星期五了。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请记住，下一次别忘了带伞。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "现在这一回之后的那一回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '980ebab6-654b-45aa-acc6-731014f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下一次", "is_correct": true, "explanation": "正确：“下一次”表示将来的一次，可以用于许诺。"}, {"text": "地方", "is_correct": false, "explanation": "语义：“地方”不能作为“来”的时间承诺，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能发出“来”的动作，不能作主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被许诺“早点来”，与语境不符。"}], "explanations": {"下一次": "正确：“下一次”表示将来的一次，可以用于许诺。", "地方": "语义：“地方”不能作为“来”的时间承诺，句子不通。", "作业": "搭配：“作业”不能发出“来”的动作，不能作主语。", "天气": "语义：天气不能被许诺“早点来”，与语境不符。"}, "sentence_index": 0, "correct_answer": "下一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下一次我去过北京。", "explanation": "这里应该用〈上一次〉。下一次指将来的那一回，不能用来说已经发生的经历。"}, {"text": "下一次他很胖。", "explanation": "这里应该用〈以前〉。下一次指将来的一次，不能用来描述人过去的状态。"}, {"text": "下一次我还小，不懂事。", "explanation": "这里应该用〈那时候〉。下一次指将来的一次，不能用来描述过去的年龄状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下一次", "is_correct": true, "explanation": "正确：“下一次”表示将来，可以用于提问将来的安排。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔不能去哪儿玩，与语境不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”不能作为去玩的主体。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能去哪儿玩，与语境不符。"}], "explanations": {"下一次": "正确：“下一次”表示将来，可以用于提问将来的安排。", "钢笔": "语义：钢笔不能去哪儿玩，与语境不符。", "窗户": "搭配：“窗户”不能作为去玩的主体。", "书包": "语义：书包不能去哪儿玩，与语境不符。"}, "sentence_index": 6, "correct_answer": "下一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下一次我在超市买了一本书。", "explanation": "这里应该用〈昨天〉。下一次指将来的一次，不能和已经完成的“买了”搭配。"}, {"text": "下一次老师讲过这道题。", "explanation": "这里应该用〈刚才〉。下一次指将来，不能与“讲过”这种已完成的动作搭配。"}, {"text": "下一次我们一起去了海边。", "explanation": "这里应该用〈去年〉。下一次指将来的一次，不能用来说已经去过的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下一次的我们再一起去吧。", "corrected_sentence": "下一次我们再一起去吧。", "error_description": "“下一次”后加“的”后变成修饰“我们”的定语，句子不通；应去掉“的”，说“下一次我们再一起去吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下一次的再把作业交给你。", "corrected_sentence": "我下一次再把作业交给你。", "error_description": "“下一次”后加“的”后变成定语，句子不通；时间词作状语应直接放在副词“再”之前，去掉“的”，说“我下一次再把作业交给你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
