INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "接在这一次之后的那一次。", "primary_collocate": null, "pronunciation": "xià yí cì", "ipa": "ɕja˥˩ i˧˥ tsʰɨ˥˩", "syllable_count": 3, "sentences": [{"text": "这一次是我，下一次轮到你。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次检查很好，下一次在三月。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这次没买，下一次再买吧。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这次输了，下一次要把比分赢回来。", "target_word": "下一次", "complexity_tier": "T3", "furigana": "wǒmen zhè cì shū le, xià yí cì yào bǎ bǐfēn yíng huí lái", "sentence_source": "generated"}, {"text": "第一次很难，下一次会容易一些。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下一次上课要带课本。", "target_word": "下一次", "complexity_tier": "T3", "furigana": "lǎoshī shuō, xià yí cì shàng kè yào dài kèběn", "sentence_source": "generated"}, {"text": "这次先看到这里，下一次继续。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一次他迟到了，下一次不能再迟到。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这次做错了，下一次要小心。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一次开会，请大家准时到。", "target_word": "下一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "这一次之后紧接着的那一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '980ebab6-654b-45aa-acc6-731014f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下一次", "is_correct": true, "explanation": "正确：“下一次”表示这次之后的那一次，符合“轮到你”的语境。"}, {"text": "地方", "is_correct": false, "explanation": "语义：“地方”不能轮到人，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能作为“轮到”的主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能“轮到”人，与语境不符。"}], "explanations": {"下一次": "正确：“下一次”表示这次之后的那一次，符合“轮到你”的语境。", "地方": "语义：“地方”不能轮到人，句子不通。", "作业": "搭配：“作业”不能作为“轮到”的主语。", "天气": "语义：天气不能“轮到”人，与语境不符。"}, "sentence_index": 0, "correct_answer": "下一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下一次我们去了长城，玩得很开心。", "explanation": "这里应该用〈上一次〉。下一次指将来的一次，不能用来说已经去过的事。"}, {"text": "下一次他还很年轻，每天骑车上学。", "explanation": "这里应该用〈那时候〉。下一次指将来的一次，不能用来描述过去的年龄和习惯。"}, {"text": "下一次我们在海边玩了三天。", "explanation": "这里应该用〈上一次〉。下一次指将来的一次，不能和已经完成的“玩了三天”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下一次", "is_correct": true, "explanation": "正确：“下一次”表示接着的那一次，符合“继续”的语境。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“继续”的主体是人或动作，钢琴不能作“继续”的主语。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能“继续”，与“先看到这里”的语境不通。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不能“继续”，与语境不符。"}], "explanations": {"下一次": "正确：“下一次”表示接着的那一次，符合“继续”的语境。", "钢琴": "搭配：“继续”的主体是人或动作，钢琴不能作“继续”的主语。", "花园": "语义：花园不能“继续”，与“先看到这里”的语境不通。", "镜子": "语义：镜子不能“继续”，与语境不符。"}, "sentence_index": 6, "correct_answer": "下一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下一次我们已经见过面了。", "explanation": "这里应该用〈上一次〉。下一次指将来的一次，不能用来说已经发生的见面。"}, {"text": "下一次老师讲过这个故事。", "explanation": "这里应该用〈上次〉。下一次指将来的一次，不能与表示经历的“讲过”搭配。"}, {"text": "下一次我很胖，不喜欢运动。", "explanation": "这里应该用〈小时候〉。下一次指将来，不能用来描述过去的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下一次的我们再去看看吧。", "corrected_sentence": "下一次我们再去看看吧。", "error_description": "“下一次”后加“的”后变成修饰“我们”的定语，句子不通；应去掉“的”，说“下一次我们再去看看吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下一次你一定要准时来过。", "corrected_sentence": "下一次你一定要准时来。", "error_description": "体标错误：“下一次”指将来，句中不能用表示经历的“过”，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
