INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不外是说不会超出这些，就只是这样。", "primary_collocate": null, "pronunciation": "bù wài", "ipa": "pu˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "他每天的生活不外吃饭、睡觉和工作。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到的原因不外是起晚了或者路上堵车。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的游戏不外跑步、跳绳和踢球。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的爱好不外看书和听音乐。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末的活动不外逛街或者看电影。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家问的问题不外这几个。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话不外是想让我们早点回家。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天不外是热和湿。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们聊天，说的不外是孩子和身体。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜不外那几样，价格都不贵。", "target_word": "不外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示范围有限，后面列举的内容就是全部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb3a0d9-08c8-4e7f-bd40-b28ca5c44dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“每天”的习惯矛盾，句子读来不通。"}, {"text": "不外", "is_correct": true, "explanation": "正确：“不外”表示范围有限，后面的“吃饭、睡觉和工作”就是生活的全部内容。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与“每天”的习惯性动作不相容。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有与之相对的内容，无法衔接。"}], "explanations": {"偶尔": "语义：“偶尔”表示不常发生，与“每天”的习惯矛盾，句子读来不通。", "不外": "正确：“不外”表示范围有限，后面的“吃饭、睡觉和工作”就是生活的全部内容。", "已经": "体貌：“已经”表示动作已经完成，与“每天”的习惯性动作不相容。", "却": "语义：“却”表示转折，句中没有与之相对的内容，无法衔接。"}, "sentence_index": 0, "correct_answer": "不外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说要来，不外没来。", "explanation": "这里应该用〈却〉。不外是表示范围有限的副词，不表示转折；“他说要来，却没来”表示与预期相反，要用〈却〉。"}, {"text": "他很不外高兴。", "explanation": "用法：“不外”表示范围有限，不修饰形容词表示程度；“他很高兴”才自然，应去掉“不外”。"}, {"text": "这道题很难，不外我会做。", "explanation": "这里应该用〈可是〉。不外是副词，表示范围有限，不表示转折；“这道题很难，可是我会做”才是转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间上刚发生，与“说的话”的内容判断不符，读来不通。"}, {"text": "不外", "is_correct": true, "explanation": "正确：“不外”表示说话的内容只限于此，“想让我们早点回家”就是他话里的全部意思。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”多修饰突然发生的事，不修饰“说的话”这样的内容判断。"}, {"text": "随即", "is_correct": false, "explanation": "语义：“随即”表示紧接着发生，与“说的话”的内容判断不符。"}], "explanations": {"刚刚": "语义：“刚刚”表示时间上刚发生，与“说的话”的内容判断不符，读来不通。", "不外": "正确：“不外”表示说话的内容只限于此，“想让我们早点回家”就是他话里的全部意思。", "忽然": "搭配：“忽然”多修饰突然发生的事，不修饰“说的话”这样的内容判断。", "随即": "语义：“随即”表示紧接着发生，与“说的话”的内容判断不符。"}, "sentence_index": 6, "correct_answer": "不外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他五点不外回到家。", "explanation": "这里应该用〈才〉。不外表示范围或结论，不表示时间的晚或早；“五点才回到家”表示时间偏晚，要用〈才〉。"}, {"text": "他不外会唱歌，还会跳舞。", "explanation": "这里应该用〈不但〉。不外表示只限于此，与“还”搭配会自相矛盾；“不但会唱歌，还会跳舞”才是递进。"}, {"text": "他不外变得更忙了。", "explanation": "这里应该用〈反而〉。不外表示只限于此，不表示出乎意料的转变；“反而变得更忙了”表示相反的结果，要用〈反而〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的工作很不外写报告和开会。", "corrected_sentence": "他的工作不外写报告和开会。", "error_description": "错误：多用了“很”。“不外”是表示范围有限的副词，不能受程度副词“很”修饰。正确：去掉“很”，说“他的工作不外写报告和开会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩只不外是中等偏下。", "corrected_sentence": "他的成绩不外是中等偏下。", "error_description": "错误：多用了“只”，与“不外”重复表示“只是”。正确：“不外是”，去掉“只”。“不外”本身已经表示范围有限，不必再加“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91c796bd-631a-4e2d-a347-cf9cdc30eb7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94235, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高于", "is_correct": true, "explanation": "正确。高于与低于是反义词，都表示与某个数目或标准相比的高低，意思相反。"}, {"text": "等于", "is_correct": false, "explanation": "等于表示数目相同，与低于不构成反义关系。"}, {"text": "达到", "is_correct": false, "explanation": "达到表示够到某个标准，与低于不构成反义关系。"}, {"text": "接近", "is_correct": false, "explanation": "接近表示相差不远，与低于不构成反义关系。"}], "correct_answer": "高于", "explanations": {"高于": "正确。高于与低于是反义词，都表示与某个数目或标准相比的高低，意思相反。", "等于": "等于表示数目相同，与低于不构成反义关系。", "达到": "达到表示够到某个标准，与低于不构成反义关系。", "接近": "接近表示相差不远，与低于不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94235, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高于", "is_correct": true, "explanation": "正确。高于与低于是反义词，都表示与某个数目或标准相比的高低，意思相反。"}, {"text": "相当", "is_correct": false, "explanation": "相当表示数量或程度差不多，与低于不构成反义关系。"}, {"text": "维持", "is_correct": false, "explanation": "维持表示保持某种状态，与低于不构成反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "停留表示暂时不动，与低于不构成反义关系。"}], "correct_answer": "高于", "explanations": {"高于": "正确。高于与低于是反义词，都表示与某个数目或标准相比的高低，意思相反。", "相当": "相当表示数量或程度差不多，与低于不构成反义关系。", "维持": "维持表示保持某种状态，与低于不构成反义关系。", "停留": "停留表示暂时不动，与低于不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94235, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "低于是比某个数少，或者比某个地方矮。", "primary_collocate": null, "pronunciation": "dī yú", "ipa": "ti˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "今天的气温低于零度。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，他的分数低于六十分。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的高度低于两米。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下的村子低于河面，下雨时很危险。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水位低于桥面一米，船可以过去。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的人，年龄不能低于十八岁。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的价格低于别的店。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的雨量低于去年。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树的高度低于围墙，所以看不到外面。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的人口低于一百万。", "target_word": "低于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比某个数目少，或比某个地方矮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a3a156-5f7f-41d1-8849-8ba4ee2579e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94235, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "低于", "is_correct": true, "explanation": "正确。低于 dī yú 是目标词，表示比某个数或标准少。"}, {"text": "低语", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，低语意思是小声说话，不是低于。"}, {"text": "地域", "is_correct": false, "explanation": "dì 与 dī 声调不同，yù 与 yú 声调也不同，地域意思是地区，不是低于。"}, {"text": "抵御", "is_correct": false, "explanation": "dǐ 与 dī 声调不同，yù 与 yú 声调也不同，抵御意思是抵挡，不是低于。"}], "explanations": {"低于": "正确。低于 dī yú 是目标词，表示比某个数或标准少。", "低语": "yǔ（第三声）与 yú（第二声）声调不同，低语意思是小声说话，不是低于。", "地域": "dì 与 dī 声调不同，yù 与 yú 声调也不同，地域意思是地区，不是低于。", "抵御": "dǐ 与 dī 声调不同，yù 与 yú 声调也不同，抵御意思是抵挡，不是低于。"}, "sentence_index": null, "correct_answer": "低于"}, "level_3": {"options": [{"text": "低于", "is_correct": true, "explanation": "正确。“今天的气温低于零度”，气温比零度低。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”表示归入某一类，气温不能属于零度，句意不通。"}, {"text": "位于", "is_correct": false, "explanation": "搭配：“位于”后接处所，“零度”不是地点，不能说“气温位于零度”。"}, {"text": "输于", "is_correct": false, "explanation": "语义：“输于”指竞争中失败，用在气温与零度的比较上不合理。"}], "explanations": {"低于": "正确。“今天的气温低于零度”，气温比零度低。", "属于": "语义：“属于”表示归入某一类，气温不能属于零度，句意不通。", "位于": "搭配：“位于”后接处所，“零度”不是地点，不能说“气温位于零度”。", "输于": "语义：“输于”指竞争中失败，用在气温与零度的比较上不合理。"}, "sentence_index": 0, "correct_answer": "低于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他低于我三分钟到学校。", "explanation": "这里应该用〈早于〉。低于比较的是数量或标准的高低，说先后时间要用“早于”，即“他早于我三分钟到学校”。"}, {"text": "这件衣服低于那件好看。", "explanation": "这里应该用〈不如〉。低于只用于可量化的标准或水平，“好看”这类评价不能用低于来比，应说“不如那件好看”。"}, {"text": "他低于我三岁。", "explanation": "这里应该用〈比……小〉。低于比较的是标准或数目的高低，不用来说两人相差几岁，应说“他比我小三岁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低于", "is_correct": true, "explanation": "正确。“这家商店的价格低于别的店”，价格比别的店低。"}, {"text": "归于", "is_correct": false, "explanation": "语义：“归于”指归属或归结，价格不能归于别的店，句意不通。"}, {"text": "处于", "is_correct": false, "explanation": "搭配：“处于”接状态或位置，“价格处于别的店”不能成立。"}, {"text": "隶属", "is_correct": false, "explanation": "语义：“隶属”指从属于某个机构，价格不能隶属于别的店。"}], "explanations": {"低于": "正确。“这家商店的价格低于别的店”，价格比别的店低。", "归于": "语义：“归于”指归属或归结，价格不能归于别的店，句意不通。", "处于": "搭配：“处于”接状态或位置，“价格处于别的店”不能成立。", "隶属": "语义：“隶属”指从属于某个机构，价格不能隶属于别的店。"}, "sentence_index": 6, "correct_answer": "低于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛我低于对手，很不甘心。", "explanation": "这里应该用〈输给〉。低于比较的是标准或数量，比赛的胜负要说“输给对手”，不说“低于对手”。"}, {"text": "我们决定低于价格，吸引更多顾客。", "explanation": "这里应该用〈降低〉。低于要接一个标准或数目作比较，不能直接带“价格”作宾语，应说“降低价格”。"}, {"text": "他低于头看书，眼镜都快掉了。", "explanation": "这里应该用〈低头〉。低于表示与标准相比的高低，不能表示身体向下弯的动作，应说“低头看书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的降水量比低于去年的平均值。", "corrected_sentence": "这个月的降水量低于去年的平均值。", "error_description": "错误：“比低于”双重比较。“低于”本身已表示比较，前面不能再加“比”。正确说法：这个月的降水量低于去年的平均值。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的雨量很低于去年同期。", "corrected_sentence": "这个月的雨量低于去年同期。", "error_description": "错误：“低于”本身表示比较，前面不能加程度副词“很”。应说“这个月的雨量低于去年同期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
