INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94239, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拟是先把想做的事想好，或者先写下来。", "primary_collocate": null, "pronunciation": "nǐ", "ipa": "ni²¹⁴", "syllable_count": 1, "sentences": [{"text": "他拟了一份名单。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我先拟个计划。", "target_word": "拟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在黑板上拟了一个题目。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发以前，我们先拟好了路线。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写文章以前，他先拟了一个提纲。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议结束后，秘书需要拟一份会议纪要。", "target_word": "拟", "complexity_tier": "T3", "furigana": "huì yì jié shù hòu, mì shū xū yào nǐ yí fèn huì yì jì yào.", "sentence_source": "generated"}, {"text": "经理让秘书把明天的会议安排拟出来。", "target_word": "拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在拟一封给客户的信。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了很久，才拟好一份发言稿。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会以前，请大家先拟好发言要点。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拟了", "label": "体标"}, {"form": "拟过", "label": "体标"}, {"form": "拟定", "label": "复合"}, {"form": "拟稿", "label": "复合"}], "register": "书面语", "sense_fingerprint": "事先想好并写出计划、名单、提纲等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94239, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拟", "is_correct": true, "explanation": "目标词：拟（nǐ，第三声），意思是事先想好并写出。"}, {"text": "泥", "is_correct": false, "explanation": "泥（ní，第二声）与拟（nǐ，第三声）声调不同，意思是泥土。"}, {"text": "理", "is_correct": false, "explanation": "理（lǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 l 不同，意思是道理。"}, {"text": "腻", "is_correct": false, "explanation": "腻（nì，第四声）与拟（nǐ，第三声）声调不同，意思是油腻。"}, {"text": "米", "is_correct": false, "explanation": "米（mǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 m 不同，意思是大米。"}], "explanations": {"拟": "目标词：拟（nǐ，第三声），意思是事先想好并写出。", "泥": "泥（ní，第二声）与拟（nǐ，第三声）声调不同，意思是泥土。", "理": "理（lǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 l 不同，意思是道理。", "腻": "腻（nì，第四声）与拟（nǐ，第三声）声调不同，意思是油腻。", "米": "米（mǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 m 不同，意思是大米。"}, "sentence_index": null, "correct_answer": "拟"}, "level_3": {"options": [{"text": "拟", "is_correct": true, "explanation": "正确：「拟」表示事先想好并写出，与「一份名单」搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语是食物，不能说「吃一份名单」。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的宾语是歌曲等，不能与「名单」搭配。"}, {"text": "生", "is_correct": false, "explanation": "语义：「生」指出生、生育或产生，不表示事先拟定名单。"}], "explanations": {"拟": "正确：「拟」表示事先想好并写出，与「一份名单」搭配，符合句意。", "吃": "搭配：「吃」的宾语是食物，不能说「吃一份名单」。", "唱": "搭配：「唱」的宾语是歌曲等，不能与「名单」搭配。", "生": "语义：「生」指出生、生育或产生，不表示事先拟定名单。"}, "sentence_index": 0, "correct_answer": "拟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拟了一张桌子。", "explanation": "这里误用了「拟」：它指事先想好并写出计划、名单等文字内容，不能用于制作桌子这类实物，应改用〈做〉。"}, {"text": "他拟了一件毛衣。", "explanation": "这里应该用〈织〉。拟指事先想好并写出计划、名单等文字内容，不能用于织毛衣这类手工制作。"}, {"text": "妈妈拟了一顿晚饭。", "explanation": "这里应该用〈做〉。拟只用于计划、名单、提纲等文字材料，不能用于做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94239, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拟", "is_correct": true, "explanation": "目标词：拟（nǐ，第三声），意思是事先想好并写出。"}, {"text": "礼", "is_correct": false, "explanation": "礼（lǐ，第三声）与拟（nǐ，第三声）声母不同，l 与 n 不同，意思是礼物。"}, {"text": "逆", "is_correct": false, "explanation": "逆（nì，第四声）与拟（nǐ，第三声）声调不同，意思是相反、违背。"}, {"text": "尼", "is_correct": false, "explanation": "尼（ní，第二声）与拟（nǐ，第三声）声调不同，意思是尼姑。"}, {"text": "李", "is_correct": false, "explanation": "李（lǐ，第三声）与拟（nǐ，第三声）声母不同，意思是李子或姓氏。"}], "explanations": {"拟": "目标词：拟（nǐ，第三声），意思是事先想好并写出。", "礼": "礼（lǐ，第三声）与拟（nǐ，第三声）声母不同，l 与 n 不同，意思是礼物。", "逆": "逆（nì，第四声）与拟（nǐ，第三声）声调不同，意思是相反、违背。", "尼": "尼（ní，第二声）与拟（nǐ，第三声）声调不同，意思是尼姑。", "李": "李（lǐ，第三声）与拟（nǐ，第三声）声母不同，意思是李子或姓氏。"}, "sentence_index": null, "correct_answer": "拟"}, "level_3": {"options": [{"text": "拟", "is_correct": true, "explanation": "正确：「拟出来」表示事先想好并写出，符合「会议安排」的语境。"}, {"text": "跑", "is_correct": false, "explanation": "配价：「跑」是不及物动词，不能带「把」字结构的宾语。"}, {"text": "笑", "is_correct": false, "explanation": "配价：「笑」是不及物动词，不能用「把会议安排笑出来」这种结构。"}, {"text": "闻", "is_correct": false, "explanation": "语义：「闻」指用鼻子感知气味，与「会议安排」不相关。"}], "explanations": {"拟": "正确：「拟出来」表示事先想好并写出，符合「会议安排」的语境。", "跑": "配价：「跑」是不及物动词，不能带「把」字结构的宾语。", "笑": "配价：「笑」是不及物动词，不能用「把会议安排笑出来」这种结构。", "闻": "语义：「闻」指用鼻子感知气味，与「会议安排」不相关。"}, "sentence_index": 6, "correct_answer": "拟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拟了一辆自行车。", "explanation": "这里误用了「拟」：它只指事先想好并写出计划、名单等文字内容，不能用于制作或修理自行车这类实物。"}, {"text": "农民拟了一棵树。", "explanation": "这里应该用〈栽〉。拟用于计划、名单类文字，不用于种植树木。"}, {"text": "他拟了一个电话。", "explanation": "这里应该用〈打〉。拟不用于打电话这类动作，「一个电话」应与「打」搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想先拟了一份提纲。", "corrected_sentence": "我想先拟一份提纲。", "error_description": "错误在「拟」后面多加了「了」。「想先拟」表示打算，后面的动作还没完成，应说「我想先拟一份提纲」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板让我们先拟着一份预算。", "corrected_sentence": "老板让我们先拟一份预算。", "error_description": "错误在「拟」后面多加了「着」。「拟」表示事先想好并写出，不表示持续状态，应说「先拟一份预算」，去掉「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
