INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94240, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拟是打算做某件事，多用于书面语。", "primary_collocate": null, "pronunciation": "nǐ", "ipa": "ni²¹⁴", "syllable_count": 1, "sentences": [{"text": "公司拟在明年开一家新店。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校拟于下月开始招生。", "target_word": "拟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "市里拟建一座新桥。", "target_word": "拟", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "校方拟在下学期增设两门选修课。", "target_word": "拟", "complexity_tier": "T3", "furigana": "xiào fāng nǐ zài xià xuéqī zēng shè liǎng mén xuǎn xiū kè.", "sentence_source": "generated"}, {"text": "他拟明天去上海出差。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们拟下周开会讨论此事。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府拟把这条老街改成步行街。", "target_word": "拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂拟增加两条生产线，明年开始用。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司拟下个月招聘十名新员工。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司拟共同开发一个新软件。", "target_word": "拟", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "打算或计划将要做某事（后接动词短语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拟", "is_correct": true, "explanation": "目标词：拟（nǐ，第三声），意思是打算做某事。"}, {"text": "泥", "is_correct": false, "explanation": "泥（ní，第二声）与拟（nǐ，第三声）声调不同，意思是泥土。"}, {"text": "理", "is_correct": false, "explanation": "理（lǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 l 不同，意思是道理。"}, {"text": "腻", "is_correct": false, "explanation": "腻（nì，第四声）与拟（nǐ，第三声）声调不同，意思是油腻。"}, {"text": "米", "is_correct": false, "explanation": "米（mǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 m 不同，意思是大米。"}], "explanations": {"拟": "目标词：拟（nǐ，第三声），意思是打算做某事。", "泥": "泥（ní，第二声）与拟（nǐ，第三声）声调不同，意思是泥土。", "理": "理（lǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 l 不同，意思是道理。", "腻": "腻（nì，第四声）与拟（nǐ，第三声）声调不同，意思是油腻。", "米": "米（mǐ，第三声）与拟（nǐ，第三声）声母不同，n 与 m 不同，意思是大米。"}, "sentence_index": null, "correct_answer": "拟"}, "level_3": {"options": [{"text": "拟", "is_correct": true, "explanation": "正确：「拟」表示打算，与后面的「在明年开一家新店」搭配，符合句意。"}, {"text": "生", "is_correct": false, "explanation": "语义：「生」指出生、生育，不能表示公司打算做某事。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能带「在明年开一家新店」这样的动作短语作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：「睡」是不及物动词，不能接动作短语作宾语。"}], "explanations": {"拟": "正确：「拟」表示打算，与后面的「在明年开一家新店」搭配，符合句意。", "生": "语义：「生」指出生、生育，不能表示公司打算做某事。", "吃": "搭配：「吃」不能带「在明年开一家新店」这样的动作短语作宾语。", "睡": "配价：「睡」是不及物动词，不能接动作短语作宾语。"}, "sentence_index": 0, "correct_answer": "拟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拟了一碗面。", "explanation": "这里误用了「拟」：它表示打算做某事，不能表示煮面、做饭这类动作，应改用〈煮〉。"}, {"text": "我拟昨天去了北京。", "explanation": "这里误用了「拟」：它表示对将来的打算，不能与已经过去的「昨天」搭配，应去掉「拟」。"}, {"text": "妈妈拟了一壶水。", "explanation": "这里应该用〈烧〉。拟表示打算做某事，不指烧水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94240, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拟", "is_correct": true, "explanation": "目标词：拟（nǐ，第三声），意思是打算做某事。"}, {"text": "女", "is_correct": false, "explanation": "nǚ（第三声）与拟（nǐ，第三声）韵母不同（ü 与 i），意思是女性。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与拟（nǐ，第三声）声母不同，l 与 n 不同，意思是里面。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与拟（nǐ，第三声）声调不同，意思是方向相反、违背。"}, {"text": "尼", "is_correct": false, "explanation": "ní（第二声）与拟（nǐ，第三声）声调不同，意思是尼姑、尼龙等。"}], "explanations": {"拟": "目标词：拟（nǐ，第三声），意思是打算做某事。", "女": "nǚ（第三声）与拟（nǐ，第三声）韵母不同（ü 与 i），意思是女性。", "里": "lǐ（第三声）与拟（nǐ，第三声）声母不同，l 与 n 不同，意思是里面。", "逆": "nì（第四声）与拟（nǐ，第三声）声调不同，意思是方向相反、违背。", "尼": "ní（第二声）与拟（nǐ，第三声）声调不同，意思是尼姑、尼龙等。"}, "sentence_index": null, "correct_answer": "拟"}, "level_3": {"options": [{"text": "拟", "is_correct": true, "explanation": "正确：「拟」表示打算，与「把这条老街改成步行街」搭配，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指用火加热或燃烧，不能表示政府打算改造街道。"}, {"text": "跑", "is_correct": false, "explanation": "配价：「跑」是不及物动词，不能带「把」字结构的宾语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：「哭」是不及物动词，不能用「把这条老街……」作宾语。"}], "explanations": {"拟": "正确：「拟」表示打算，与「把这条老街改成步行街」搭配，符合句意。", "烧": "语义：「烧」指用火加热或燃烧，不能表示政府打算改造街道。", "跑": "配价：「跑」是不及物动词，不能带「把」字结构的宾语。", "哭": "配价：「哭」是不及物动词，不能用「把这条老街……」作宾语。"}, "sentence_index": 6, "correct_answer": "拟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拟突然哭了。", "explanation": "这里误用了「拟」的「打算」义：它表示有意的计划，不能用于突然哭这种不由自主的情况。"}, {"text": "我拟明天下雨。", "explanation": "这里误用了「拟」的「打算」义：它只用于人能主动决定的事，不能用于天气变化，这里应该用〈希望〉表示期盼。"}, {"text": "他拟忘记了钥匙。", "explanation": "这里误用了「拟」：它表示有意的打算，「忘记了钥匙」是无意的遗忘，二者矛盾，应去掉「拟」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拟了在周末去看望奶奶。", "corrected_sentence": "他拟在周末去看望奶奶。", "error_description": "错误在「拟」后面多加了「了」。「拟」后接未来的计划，不能加「了」表示已完成，应说「他拟在周末去看望奶奶」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们拟着把合作方案提交给董事会。", "corrected_sentence": "他们拟把合作方案提交给董事会。", "error_description": "错误在「拟」后面多加了「着」。「拟」表示打算，不用「着」表示持续状态，应说「他们拟把合作方案提交给董事会」，去掉「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
