INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公司会议是公司里的人坐在一起，谈工作的聚会。", "primary_collocate": null, "pronunciation": "gōng sī huì yì", "ipa": "kʊŋ˥ sɹ̩˥ xueɪ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "公司会议开始前，大家都坐好了。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司会议上一直低着头。", "target_word": "公司会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司会议不长，只谈了三件工作。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个星期的公司会议改到下午了。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板在公司会议上夸了小王。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会议上大家轮流说自己的工作。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为公司会议准备了很多资料。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开公司会议的时候，请关上手机。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会议让我知道了别的部门在做什么。", "target_word": "公司会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的公司会议太长，我有点儿累。", "target_word": "公司会议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "场", "label": "量词"}], "register": "中性", "sense_fingerprint": "公司同事坐在一起谈工作的聚会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c3029d-e96d-4c4c-b73a-e938db1d64bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公司会议", "is_correct": true, "explanation": "正确：“公司会议”是同事坐在一起谈工作的聚会，会前大家坐好符合常理。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人的轻重，不是活动，不能说“体重开始前”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的属性，不是活动，不能“开始”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能作为开始的事件，句子不通。"}], "explanations": {"公司会议": "正确：“公司会议”是同事坐在一起谈工作的聚会，会前大家坐好符合常理。", "体重": "语义：“体重”指人的轻重，不是活动，不能说“体重开始前”。", "颜色": "语义：“颜色”是事物的属性，不是活动，不能“开始”。", "身高": "体貌：“身高”指人的高矮，不能作为开始的事件，句子不通。"}, "sentence_index": 0, "correct_answer": "公司会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新娘在公司会议上穿着白色婚纱。", "explanation": "这里应该用〈婚礼〉。公司会议是谈工作的聚会，穿婚纱要在婚礼上进行。"}, {"text": "法官在公司会议上宣判了犯人。", "explanation": "这里应该用〈法庭〉。公司会议是谈工作的聚会，宣判犯人要在法庭上进行。"}, {"text": "亲友们在公司会议上哭泣。", "explanation": "这里应该用〈葬礼〉。公司会议只用来谈工作，哀悼逝者要在葬礼上进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公司会议", "is_correct": true, "explanation": "正确：“为公司会议准备资料”是同事为会议做准备，符合语境。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭是吃的东西，不需要准备资料。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不是需要准备资料的活动。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指人的体重，不能作为准备资料的对象，句子不通。"}], "explanations": {"公司会议": "正确：“为公司会议准备资料”是同事为会议做准备，符合语境。", "晚饭": "语义：晚饭是吃的东西，不需要准备资料。", "体温": "语义：“体温”指身体的温度，不是需要准备资料的活动。", "体重": "体貌：“体重”指人的体重，不能作为准备资料的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "公司会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新郎在公司会议上举杯致辞。", "explanation": "这里应该用〈婚宴〉。公司会议是谈工作的聚会，举杯致辞祝酒要在婚宴上进行。"}, {"text": "牧民在公司会议上赶着羊群。", "explanation": "这里应该用〈草原〉。公司会议是谈工作的聚会，赶羊群要在草原上进行。"}, {"text": "病人在公司会议上做了手术。", "explanation": "这里应该用〈医院〉。公司会议是谈工作的聚会，做手术要在医院里进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天上午我们开一只公司会议谈销售计划。", "corrected_sentence": "明天上午我们开一次公司会议谈销售计划。", "error_description": "量词错误：会议应用量词“次”，不能用“只”（“只”多用于动物等物体），应说“开一次公司会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天下午的公司会议们很轻松。", "corrected_sentence": "今天下午的公司会议很轻松。", "error_description": "词缀错误：“们”只能加在指人的名词后面，不能加在“公司会议”后面，应说“公司会议很轻松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
