INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94243, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "剩是用过或吃过以后，还留下来一些。", "primary_collocate": null, "pronunciation": "shèng", "ipa": "ʂɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "盘子里只剩一块蛋糕了。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃完饭，桌上还剩很多菜。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱都花完了，只剩十块。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上没剩几个苹果。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的饭剩了很多，今天可以再吃。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水瓶里还剩一点水。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶喝完了，冰箱里什么也没剩。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把饭都吃了，一口也没剩。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的生活费花得差不多了，我的钱还剩两百块。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的菜做多了，晚上还剩不少。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剩了", "label": "体标"}, {"form": "剩下", "label": "复合"}], "register": "口语", "sense_fingerprint": "吃过用过之后留下一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a3a156-5f7f-41d1-8849-8ba4ee2579e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94243, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。剩 shèng 是目标词，表示吃用后留下一部分。"}, {"text": "升", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，升的意思是上升。"}, {"text": "省", "is_correct": false, "explanation": "shěng（第三声）与 shèng（第四声）声调不同，省的意思是节约或省份。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}], "explanations": {"剩": "正确。剩 shèng 是目标词，表示吃用后留下一部分。", "升": "shēng（第一声）与 shèng（第四声）声调不同，升的意思是上升。", "省": "shěng（第三声）与 shèng（第四声）声调不同，省的意思是节约或省份。", "绳": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}, "sentence_index": null, "correct_answer": "剩"}, "level_3": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。“盘子里只剩一块蛋糕了”，指吃过后余下一块。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指食用，“盘子里只吃一块蛋糕了”把剩余说成食用，句意不通。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”表示赠予或递送，盘中的蛋糕不能说“送”。"}, {"text": "端", "is_correct": false, "explanation": "搭配：“端”要接可以端起的器物或食物，“盘子里”的蛋糕不能说“只端一块”。"}], "explanations": {"剩": "正确。“盘子里只剩一块蛋糕了”，指吃过后余下一块。", "吃": "语义：“吃”指食用，“盘子里只吃一块蛋糕了”把剩余说成食用，句意不通。", "送": "语义：“送”表示赠予或递送，盘中的蛋糕不能说“送”。", "端": "搭配：“端”要接可以端起的器物或食物，“盘子里”的蛋糕不能说“只端一块”。"}, "sentence_index": 0, "correct_answer": "剩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我特意给你剩了座位。", "explanation": "这里应该用〈留〉。剩表示用后无意中留下，“特意”为别人保留的要用“留”，应说“特意给你留了座位”。"}, {"text": "他的心情剩了很多。", "explanation": "这里应该用〈充满〉。剩表示用后余下，只能说余下的具体东西、人或时间；把它用来形容心情的多少，是误当成了“多、充满”的意思，应说“他的心里充满了喜悦”。"}, {"text": "他把房间剩干净了。", "explanation": "这里应该用〈打扫〉。剩表示留下，不表示清理，要说“把房间打扫干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94243, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。剩 shèng 是目标词，表示余下。"}, {"text": "生", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，生的意思是出生或生长。"}, {"text": "声", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，声的意思是声音。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}], "explanations": {"剩": "正确。剩 shèng 是目标词，表示余下。", "生": "shēng（第一声）与 shèng（第四声）声调不同，生的意思是出生或生长。", "声": "shēng（第一声）与 shèng（第四声）声调不同，声的意思是声音。", "绳": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}, "sentence_index": null, "correct_answer": "剩"}, "level_3": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。“冰箱里什么也没剩”，指什么都没有留下。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”需要饮品作宾语，冰箱里的“什么”不能喝，句意不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”要接可以切开的食物，“冰箱里什么也没切”不成立。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”表示烹调，与冰箱里空无一物的情况不符。"}], "explanations": {"剩": "正确。“冰箱里什么也没剩”，指什么都没有留下。", "喝": "语义：“喝”需要饮品作宾语，冰箱里的“什么”不能喝，句意不通。", "切": "搭配：“切”要接可以切开的食物，“冰箱里什么也没切”不成立。", "煮": "语义：“煮”表示烹调，与冰箱里空无一物的情况不符。"}, "sentence_index": 6, "correct_answer": "剩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙剩在了车上，回家才想起来。", "explanation": "这里应该用〈落〉。剩表示用后余下，东西遗忘在某处要用“落”，应说“他把钥匙落在了车上”。"}, {"text": "他把钱剩给了朋友。", "explanation": "这里应该用〈送〉。剩表示留下，不能表示把东西给出去，应说“把钱送给了朋友”。"}, {"text": "这首歌剩得很好听。", "explanation": "这里应该用〈唱〉。剩表示用后余下，不能作得字补语描述歌曲好听；这句误把“剩”当成了表演动作的词，应说“这首歌唱得很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个周末，冰箱里还下剩两个西瓜。", "corrected_sentence": "这个周末，冰箱里还剩下两个西瓜。", "error_description": "错误：“下剩”语序颠倒。“剩下”是固定的复合词，前后顺序不能互换。正确说法：冰箱里还剩下两个西瓜。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天喝牛奶，不剩一点。", "corrected_sentence": "我昨天喝牛奶，没剩一点。", "error_description": "错误：“不剩”用错了否定词。表示过去已经发生、没有余下的情况要用“没”。正确说法：我昨天喝牛奶，没剩一点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
