INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94244, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "余下；别的都没有了，只留下一点人、事或时间。", "primary_collocate": null, "pronunciation": "shèng", "ipa": "ʂɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "离考试只剩三天了。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛快结束时，场上只剩五个人。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都回家了，教室里只剩小明一个人。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年快过完了，只剩两个月。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业都写完了，只剩最后一页。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，树上只剩几片叶子。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车里的油只剩一点儿了。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都走了，屋里就剩我一个人。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路已经走了一半，还剩五公里。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人都走了，只剩老师在等我。", "target_word": "剩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剩了", "label": "体标"}, {"form": "剩下", "label": "复合"}], "register": "口语", "sense_fingerprint": "别的都没有了，只余下一点人、事或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a3a156-5f7f-41d1-8849-8ba4ee2579e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94244, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。剩 shèng 是目标词，表示别的都没有了，只余下一点。"}, {"text": "升", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，升的意思是上升。"}, {"text": "省", "is_correct": false, "explanation": "shěng（第三声）与 shèng（第四声）声调不同，省的意思是节约或省份。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}], "explanations": {"剩": "正确。剩 shèng 是目标词，表示别的都没有了，只余下一点。", "升": "shēng（第一声）与 shèng（第四声）声调不同，升的意思是上升。", "省": "shěng（第三声）与 shèng（第四声）声调不同，省的意思是节约或省份。", "绳": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}, "sentence_index": null, "correct_answer": "剩"}, "level_3": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。“离考试只剩三天了”，指只余下三天。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“花”要接花费的钱或时间，“离考试只花三天了”说不通。"}, {"text": "欠", "is_correct": false, "explanation": "语义：“欠”指拖欠或欠债，句中说的是时间的余量，不能用“欠”。"}, {"text": "请", "is_correct": false, "explanation": "搭配：“请”指请假、请客，不能用来说离考试的时间。"}], "explanations": {"剩": "正确。“离考试只剩三天了”，指只余下三天。", "花": "搭配：“花”要接花费的钱或时间，“离考试只花三天了”说不通。", "欠": "语义：“欠”指拖欠或欠债，句中说的是时间的余量，不能用“欠”。", "请": "搭配：“请”指请假、请客，不能用来说离考试的时间。"}, "sentence_index": 0, "correct_answer": "剩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他剩了我的朋友，自己去了外地。", "explanation": "这里应该用〈丢下〉。剩表示余下，不能表示把人抛在一边，应说“丢下了我的朋友”。"}, {"text": "他的心情只剩很好，大家都笑了。", "explanation": "这里应该用〈愉快〉。剩表示用后余下，只能说余下的具体人、事或时间，不能用来描述心情的好坏；这句把“剩”误用成了形容词式的描述，应说“他的心情很愉快”。"}, {"text": "他走之前剩了一封信给我。", "explanation": "这里应该用〈留〉。剩表示别的都没有了只余下一点，不能表示主动把东西留给别人，应说“留了一封信给我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94244, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。剩 shèng 是目标词，表示余下。"}, {"text": "生", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，生的意思是出生或生长。"}, {"text": "声", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，声的意思是声音。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}], "explanations": {"剩": "正确。剩 shèng 是目标词，表示余下。", "生": "shēng（第一声）与 shèng（第四声）声调不同，生的意思是出生或生长。", "声": "shēng（第一声）与 shèng（第四声）声调不同，声的意思是声音。", "绳": "shéng（第二声）与 shèng（第四声）声调不同，绳的意思是绳子。"}, "sentence_index": null, "correct_answer": "剩"}, "level_3": {"options": [{"text": "剩", "is_correct": true, "explanation": "正确。“车里的油只剩一点儿了”，指余下的油很少。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”表示把液体倒出，句中说的是油的余量，不能用“倒”。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示燃烧消耗，与“余下”的意思不符，句意不通。"}, {"text": "抽", "is_correct": false, "explanation": "语义：“抽”指抽出，句中说的是油的余量，不能用“抽”，句意不通。"}], "explanations": {"剩": "正确。“车里的油只剩一点儿了”，指余下的油很少。", "倒": "语义：“倒”表示把液体倒出，句中说的是油的余量，不能用“倒”。", "烧": "语义：“烧”表示燃烧消耗，与“余下”的意思不符，句意不通。", "抽": "语义：“抽”指抽出，句中说的是油的余量，不能用“抽”，句意不通。"}, "sentence_index": 6, "correct_answer": "剩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期他剩了三次没交作业。", "explanation": "剩只说余下的东西、人或时间，不能用来计算次数，这里应说“漏交了三次作业”。"}, {"text": "我把书剩在家里了，没带来。", "explanation": "这里应该用〈落〉。剩表示余下，不能表示忘了带东西，应说“我把书落在家里了”。"}, {"text": "晚饭剩得很香。", "explanation": "这里应该用〈吃〉。剩表示用后余下，不能作得字补语描述吃饭的状态；这句误把“剩”当成了描述吃的动词，应说“晚饭吃得很香”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个星期剩只三天了。", "corrected_sentence": "这个星期只剩三天了。", "error_description": "错误：“剩只”语序错误。“只”是副词，应放在“剩”前面。正确说法：这个星期只剩三天了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把剩十块钱。", "corrected_sentence": "我还剩十块钱。", "error_description": "错误：“把”字句要求能处置人或物的动词，“剩”表示余下，不能用于“把”字句。正确说法：我还剩十块钱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
