INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南方和北方两个地区。", "primary_collocate": null, "pronunciation": "nán běi", "ipa": "nan˧˥ pei̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "中国南北的饭菜很不一样。", "target_word": "南北", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南北的天气差别很大。", "target_word": "南北", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去过中国南北很多地方。", "target_word": "南北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南北的人说话不太一样。", "target_word": "南北", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条铁路连着中国南北。", "target_word": "南北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南北的孩子都爱吃饺子。", "target_word": "南北", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他常年奔波在南北各地。", "target_word": "南北", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南北的习惯都不同，我们要互相了解。", "target_word": "南北", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在南北都住过。", "target_word": "南北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日南北都很热闹。", "target_word": "南北", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "南方和北方两个地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '803b8d38-3b31-4866-a82b-2e7f4534b9dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是地域，不能说“中国冰箱的饭菜”。"}, {"text": "南北", "is_correct": true, "explanation": "正确：南北指中国的南方和北方两地，作为地域名词修饰“饭菜”，与句意相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室指房间，不能作为地域范围修饰“饭菜”。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：人口是数量概念，不能与“饭菜很不一样”的地域差别构成修饰关系。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，不是地域，不能说“中国冰箱的饭菜”。", "南北": "正确：南北指中国的南方和北方两地，作为地域名词修饰“饭菜”，与句意相符。", "教室": "语义：教室指房间，不能作为地域范围修饰“饭菜”。", "人口": "搭配：人口是数量概念，不能与“饭菜很不一样”的地域差别构成修饰关系。"}, "sentence_index": 0, "correct_answer": "南北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下个月要去南北出差，那边的天气比较暖和。", "explanation": "这里应该用〈南方〉。南北是南方和北方两地的合称，不能当作一个出差的地点。"}, {"text": "我的老家在南北，冬天特别冷。", "explanation": "这里应该用〈北方〉。南北指两地合称，不能指老家所在的一个地区。"}, {"text": "他家在南北，离机场很近。", "explanation": "这里应该用〈北部〉。南北是两地的合称，不能指他家所在的一个区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办公室", "is_correct": false, "explanation": "语义：办公室是房间，不能表示“各地”的范围。"}, {"text": "南北", "is_correct": true, "explanation": "正确：南北指南方和北方两地，作为“各地”的范围，与“常年奔波”相符。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不是地点，不能与“奔波在……各地”搭配。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：黑板是物件，“奔波在”要求地域名词，黑板不能构成这样的搭配。"}], "explanations": {"办公室": "语义：办公室是房间，不能表示“各地”的范围。", "南北": "正确：南北指南方和北方两地，作为“各地”的范围，与“常年奔波”相符。", "小说": "语义：小说是文学作品，不是地点，不能与“奔波在……各地”搭配。", "黑板": "搭配：黑板是物件，“奔波在”要求地域名词，黑板不能构成这样的搭配。"}, "sentence_index": 6, "correct_answer": "南北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从超市买了很多南北带回家。", "explanation": "这里应该用〈东西〉。南北指南方和北方，不能表示“物品”。"}, {"text": "他在图书馆借了一本南北，很有意思。", "explanation": "这里应该用〈书〉。南北指南方和北方，不能指书籍。"}, {"text": "这首南北我听过很多遍了。", "explanation": "这里应该用〈歌〉。南北指南方和北方，不能指歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常年在很南北各地出差。", "corrected_sentence": "他常年在南北各地出差。", "error_description": "修饰错误：“南北”是名词，不能被程度副词“很”修饰，应说“他常年在南北各地出差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常年跑南北们做生意。", "corrected_sentence": "他常年跑南北做生意。", "error_description": "词形错误：“南北”是名词，后面不能加“们”，应说“跑南北做生意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
