INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回头是转过头去看后面。", "primary_collocate": null, "pronunciation": "huí tóu", "ipa": "xuei̯˧˥ tʰou̯˧˥", "syllable_count": 2, "sentences": [{"text": "他听到有人叫他，就回头看。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她走了几步，又回头笑了笑。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到声音，我马上回头。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别回头，一直往前走。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子走着走着，回头找妈妈。", "target_word": "回头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有回头，慢慢走远了。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师回头看了看大家。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车开远了，她还在回头望。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回头一看，后面一个人也没有。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗不停地回头看主人。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "转过头去看后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '803b8d38-3b31-4866-a82b-2e7f4534b9dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回答", "is_correct": false, "explanation": "配价：回答需要带受话对象或内容，不能直接接“看”。"}, {"text": "回头", "is_correct": true, "explanation": "正确：回头表示转过头去看，与“听到有人叫他”的动作相符。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆指想起过去的事，不能与“看”连用表示转身去看。"}, {"text": "回信", "is_correct": false, "explanation": "搭配：回信指写信回复，不能与“看”搭配。"}], "explanations": {"回答": "配价：回答需要带受话对象或内容，不能直接接“看”。", "回头": "正确：回头表示转过头去看，与“听到有人叫他”的动作相符。", "回忆": "语义：回忆指想起过去的事，不能与“看”连用表示转身去看。", "回信": "搭配：回信指写信回复，不能与“看”搭配。"}, "sentence_index": 0, "correct_answer": "回头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把回头放在包里。", "explanation": "这里应该用〈钥匙〉。回头是副词或动词，不能作名词指物品。"}, {"text": "老师回头了一个消息。", "explanation": "这里应该用〈宣布〉。回头不能带“消息”作宾语。"}, {"text": "我回头了作业。", "explanation": "这里应该用〈做〉。回头不能带“作业”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回收", "is_correct": false, "explanation": "语义：回收指收回物品，不能与“看了看大家”搭配。"}, {"text": "回头", "is_correct": true, "explanation": "正确：回头表示转过头去，与“老师……看了看大家”的动作相符。"}, {"text": "回访", "is_correct": false, "explanation": "配价：回访要带访问对象，不能直接接“看”。"}, {"text": "回归", "is_correct": false, "explanation": "语义：回归指返回原来的状态或地方，不能表示看人。"}], "explanations": {"回收": "语义：回收指收回物品，不能与“看了看大家”搭配。", "回头": "正确：回头表示转过头去，与“老师……看了看大家”的动作相符。", "回访": "配价：回访要带访问对象，不能直接接“看”。", "回归": "语义：回归指返回原来的状态或地方，不能表示看人。"}, "sentence_index": 6, "correct_answer": "回头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他回头了一杯水。", "explanation": "这里应该用〈端〉。回头不能带''水''作宾语。"}, {"text": "她回头了一封信，很专心。", "explanation": "这里应该用〈写〉。回头不能带''信''作宾语。"}, {"text": "他回头了一个电话。", "explanation": "这里应该用〈接〉。回头不能带''电话''作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他回头过看了一眼。", "corrected_sentence": "他回头看了一眼。", "error_description": "错误形式：“回头过看”。正确形式：“回头看”。“过”不能插在“回头”和“看”之间，此句不需要体标，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她走远了，还在很回头看。", "corrected_sentence": "她走远了，还在回头看。", "error_description": "修饰错误：“回头”是动词，不能被程度副词“很”修饰，应说“她走远了，还在回头看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
