INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "过一会儿再做，以后。", "primary_collocate": null, "pronunciation": "huí tóu", "ipa": "xuei̯˧˥ tʰou̯˧˥", "syllable_count": 2, "sentences": [{"text": "我现在有点忙，回头给你打电话。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先走吧，回头我再告诉你。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事回头再说吧。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "回头我把照片发给你。", "target_word": "回头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说回头请我们吃饭。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我先去开会，回头见。", "target_word": "回头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "东西先放这儿，回头我来拿。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "回头有空，我们一起去看电影。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在没时间，回头我回你消息。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说回头给我买新书包。", "target_word": "回头", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "过一会儿再做，以后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '803b8d38-3b31-4866-a82b-2e7f4534b9dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚刚", "is_correct": false, "explanation": "体貌：刚刚表示刚发生，与“现在有点忙”要做的事时间不符。"}, {"text": "回头", "is_correct": true, "explanation": "正确：回头表示过一会儿、以后，与“现在有点忙”形成先后关系，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "语义：从来表示一向如此，不能用于此处一次性的打电话。"}, {"text": "早就", "is_correct": false, "explanation": "语义：早就指很久以前，与“现在有点忙”的时间矛盾。"}], "explanations": {"刚刚": "体貌：刚刚表示刚发生，与“现在有点忙”要做的事时间不符。", "回头": "正确：回头表示过一会儿、以后，与“现在有点忙”形成先后关系，符合句意。", "从来": "语义：从来表示一向如此，不能用于此处一次性的打电话。", "早就": "语义：早就指很久以前，与“现在有点忙”的时间矛盾。"}, "sentence_index": 0, "correct_answer": "回头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把回头放在桌子上。", "explanation": "这里应该用〈书〉。回头是副词或动词，不能作名词指书籍。"}, {"text": "妈妈做的回头很好吃。", "explanation": "这里应该用〈饺子〉。回头是副词或动词，不能指食物。"}, {"text": "我回头了一个秘密。", "explanation": "这里应该用〈发现〉。回头作副词，不能带''秘密''作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "体貌：已经表示动作已完成，与将来要做的安排矛盾。"}, {"text": "回头", "is_correct": true, "explanation": "正确：回头表示以后、过一会儿，与“先放这儿”形成先后关系，符合句意。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：曾经表示过去的经历，不能用于将来的安排。"}, {"text": "又", "is_correct": false, "explanation": "语义：又表示重复，与这里一次性的安排不符。"}], "explanations": {"已经": "体貌：已经表示动作已完成，与将来要做的安排矛盾。", "回头": "正确：回头表示以后、过一会儿，与“先放这儿”形成先后关系，符合句意。", "曾经": "体貌：曾经表示过去的经历，不能用于将来的安排。", "又": "语义：又表示重复，与这里一次性的安排不符。"}, "sentence_index": 6, "correct_answer": "回头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我回头了这家公司，工作很努力。", "explanation": "这里应该用〈进〉。回头不能带''公司''作宾语。"}, {"text": "回头的天气很好，我们去公园吧。", "explanation": "这里应该用〈今天〉。回头是副词，不能用''的''修饰名词''天气''。"}, {"text": "我回头了那本书，看完了。", "explanation": "这里应该用〈读〉。回头不能带''书''作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回头了我们再一起去吃饭吧。", "corrected_sentence": "回头我们再一起去吃饭吧。", "error_description": "体貌错误：“回头”作副词表示以后，后面不能加“了”，应说“回头我们再一起去吃饭吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很回头我给你打电话。", "corrected_sentence": "回头我给你打电话。", "error_description": "修饰错误：“回头”是副词，不能被程度副词“很”修饰，应说“回头我给你打电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94253, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "犹豫", "is_correct": true, "explanation": "反义：“犹豫”指拿不定主意，与“主意已定、决心不变”的“坚定”正相反。"}, {"text": "活泼", "is_correct": false, "explanation": "无反义关系：“活泼”形容性格或气氛，与决心是否改变无关。"}, {"text": "温和", "is_correct": false, "explanation": "无反义关系：“温和”形容性情或态度平和，不与“决心不变”相对。"}, {"text": "严肃", "is_correct": false, "explanation": "无反义关系：“严肃”形容态度认真庄重，不是“坚定”的反义词。"}], "correct_answer": "犹豫", "explanations": {"犹豫": "反义：“犹豫”指拿不定主意，与“主意已定、决心不变”的“坚定”正相反。", "活泼": "无反义关系：“活泼”形容性格或气氛，与决心是否改变无关。", "温和": "无反义关系：“温和”形容性情或态度平和，不与“决心不变”相对。", "严肃": "无反义关系：“严肃”形容态度认真庄重，不是“坚定”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94253, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动摇", "is_correct": true, "explanation": "反义：“动摇”指主意或立场不稳，与“决心不变”的“坚定”相对。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容思路明白或事物分明，与决心是否改变无关。"}, {"text": "热烈", "is_correct": false, "explanation": "无反义关系：“热烈”形容情绪或场面激烈，不与“坚定”相对。"}, {"text": "平凡", "is_correct": false, "explanation": "无反义关系：“平凡”形容普通、不突出，与“决心不变”没有对应关系。"}], "correct_answer": "动摇", "explanations": {"动摇": "反义：“动摇”指主意或立场不稳，与“决心不变”的“坚定”相对。", "清楚": "无反义关系：“清楚”形容思路明白或事物分明，与决心是否改变无关。", "热烈": "无反义关系：“热烈”形容情绪或场面激烈，不与“坚定”相对。", "平凡": "无反义关系：“平凡”形容普通、不突出，与“决心不变”没有对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94253, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "坚定是心里拿定了主意，怎么也不改变。", "primary_collocate": null, "pronunciation": "jiān dìng", "ipa": "tɕjɛn˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她的眼神很坚定，没有一点害怕。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚定地对老师说：“我不会放弃。”", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都劝他，但他的决心很坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明坚定地选了自己喜欢的专业。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用坚定的声音回答了问题。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的想法很坚定，谁说也不会改。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚定地说不去，谁也劝不了。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员的信心非常坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚定地相信，只要努力就能成功。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话让我的决定更坚定了。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坚定不移", "label": "复合"}, {"form": "坚定地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "主意已定，决心不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a3a156-5f7f-41d1-8849-8ba4ee2579e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94253, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坚定", "is_correct": true, "explanation": "坚定：心里拿定了主意，怎么也不改变。"}, {"text": "检定", "is_correct": false, "explanation": "检定（jiǎn dìng）与坚定（jiān dìng）第一音节声调不同：第三声与第一声。检定意思是检查、核定。"}, {"text": "鉴定", "is_correct": false, "explanation": "鉴定（jiàn dìng）与坚定（jiān dìng）第一音节声调不同：第四声与第一声。鉴定意思是鉴别、评定。"}, {"text": "尖顶", "is_correct": false, "explanation": "尖顶（jiān dǐng）与坚定（jiān dìng）第二音节声调不同：第三声与第四声。尖顶意思是尖的顶端。"}, {"text": "签订", "is_correct": false, "explanation": "签订（qiān dìng）与坚定（jiān dìng）第一音节声母不同：q 与 j 的送气不同。签订意思是签署合同、协议。"}], "explanations": {"坚定": "坚定：心里拿定了主意，怎么也不改变。", "检定": "检定（jiǎn dìng）与坚定（jiān dìng）第一音节声调不同：第三声与第一声。检定意思是检查、核定。", "鉴定": "鉴定（jiàn dìng）与坚定（jiān dìng）第一音节声调不同：第四声与第一声。鉴定意思是鉴别、评定。", "尖顶": "尖顶（jiān dǐng）与坚定（jiān dìng）第二音节声调不同：第三声与第四声。尖顶意思是尖的顶端。", "签订": "签订（qiān dìng）与坚定（jiān dìng）第一音节声母不同：q 与 j 的送气不同。签订意思是签署合同、协议。"}, "sentence_index": null, "correct_answer": "坚定"}, "level_3": {"options": [{"text": "坚定", "is_correct": true, "explanation": "正确：“坚定”形容眼神稳定、不动摇，与后句“没有一点害怕”相符。"}, {"text": "胆怯", "is_correct": false, "explanation": "语义：“胆怯”指因害怕而不敢，与后句“没有一点害怕”矛盾。"}, {"text": "惊慌", "is_correct": false, "explanation": "语义：“惊慌”指受惊后慌乱，与后句“没有一点害怕”矛盾。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：“硬朗”多用于身体、字迹或风格，不用来形容眼神。"}], "explanations": {"坚定": "正确：“坚定”形容眼神稳定、不动摇，与后句“没有一点害怕”相符。", "胆怯": "语义：“胆怯”指因害怕而不敢，与后句“没有一点害怕”矛盾。", "惊慌": "语义：“惊慌”指受惊后慌乱，与后句“没有一点害怕”矛盾。", "硬朗": "搭配：“硬朗”多用于身体、字迹或风格，不用来形容眼神。"}, "sentence_index": 0, "correct_answer": "坚定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥很坚定，能承受很大的重量。", "explanation": "这里应该用〈坚固〉。“坚定”形容人的意志或决心，说桥梁等物体的牢固要用“坚固”。"}, {"text": "明天的会议时间还没有坚定，请大家等通知。", "explanation": "这里应该用〈确定〉。“坚定”指意志不变，时间、事情定下来要用“确定”。"}, {"text": "这块石头很坚定，很难敲碎。", "explanation": "这里应该用〈坚硬〉。“坚定”不用于形容物体的硬度，石头的硬要说“坚硬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚定", "is_correct": true, "explanation": "正确：“坚定地说不去”表示态度决绝，与后句“谁也劝不了”相符。"}, {"text": "犹豫", "is_correct": false, "explanation": "语义：“犹豫”表示拿不定主意，与后句“谁也劝不了”的坚决态度矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列有序，不能修饰一个人说话的方式。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼神，不能修饰说话的方式。"}], "explanations": {"坚定": "正确：“坚定地说不去”表示态度决绝，与后句“谁也劝不了”相符。", "犹豫": "语义：“犹豫”表示拿不定主意，与后句“谁也劝不了”的坚决态度矛盾。", "整齐": "搭配：“整齐”形容排列有序，不能修饰一个人说话的方式。", "明亮": "搭配：“明亮”形容光线或眼神，不能修饰说话的方式。"}, "sentence_index": 6, "correct_answer": "坚定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这扇门装得很坚定，很难打开。", "explanation": "这里应该用〈牢固〉。“坚定”说人的意志，门、墙等物体装得稳固要用“牢固”。"}, {"text": "这家公司的股价最近很坚定。", "explanation": "这里应该用〈坚挺〉。股价上涨稳定说“坚挺”，“坚定”只用于人的意志或立场。"}, {"text": "这种布料很坚定，洗多少次也不坏。", "explanation": "这里应该用〈坚韧〉。“坚定”形容意志，布料的耐用和韧性要说“坚韧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个坚定地人，从不轻易放弃。", "corrected_sentence": "他是一个坚定的人，从不轻易放弃。", "error_description": "“坚定”修饰名词“人”时要用结构助词“的”，不能用“地”。“地”用来修饰动词或形容词。正确说法是“坚定的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的决心坚定很。", "corrected_sentence": "她的决心坚定得很。", "error_description": "错误：状态补语前漏掉了结构助词“得”。形容词作补语说明程度时要用“得”，应说“坚定得很”，不说“坚定很”。正确说法：她的决心坚定得很。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
