INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94254, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动摇", "is_correct": true, "explanation": "反义：“动摇”指立场或信念不稳，与“不动摇”的“坚定”相对。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容思路明白或事物分明，与立场是否稳固无关。"}, {"text": "活跃", "is_correct": false, "explanation": "无反义关系：“活跃”形容积极、有生气，与立场是否稳固无关。"}, {"text": "冷静", "is_correct": false, "explanation": "无反义关系：“冷静”形容头脑清醒、不慌乱，不与“坚定”构成反义。"}], "correct_answer": "动摇", "explanations": {"动摇": "反义：“动摇”指立场或信念不稳，与“不动摇”的“坚定”相对。", "清楚": "无反义关系：“清楚”形容思路明白或事物分明，与立场是否稳固无关。", "活跃": "无反义关系：“活跃”形容积极、有生气，与立场是否稳固无关。", "冷静": "无反义关系：“冷静”形容头脑清醒、不慌乱，不与“坚定”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94254, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "稳定牢固，不动摇。", "primary_collocate": null, "pronunciation": "jiān dìng", "ipa": "tɕjɛn˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在这个问题上，他的立场一直很坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间要有坚定的信任。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在困难面前，他的信念依然坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有坚定的信仰，从来不动摇。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的支持让我的信心更坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生坚定的态度让病人放心了。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的和平政策一直很坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间有着坚定的友谊。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风雨再大，他的脚步也很坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们支持他，因为他的原则非常坚定。", "target_word": "坚定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坚定不移", "label": "复合"}, {"form": "坚定地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "立场、信念等稳固，不动摇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a3a156-5f7f-41d1-8849-8ba4ee2579e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94254, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坚定", "is_correct": true, "explanation": "坚定：立场、信念等稳固，不动摇。"}, {"text": "检定", "is_correct": false, "explanation": "检定（jiǎn dìng）与坚定（jiān dìng）第一音节声调不同：第三声与第一声。检定意思是检查、核定。"}, {"text": "鉴定", "is_correct": false, "explanation": "鉴定（jiàn dìng）与坚定（jiān dìng）第一音节声调不同：第四声与第一声。鉴定意思是鉴别、评定。"}, {"text": "尖顶", "is_correct": false, "explanation": "尖顶（jiān dǐng）与坚定（jiān dìng）第二音节声调不同：第三声与第四声。尖顶意思是尖的顶端。"}, {"text": "签订", "is_correct": false, "explanation": "签订（qiān dìng）与坚定（jiān dìng）第一音节声母不同：q 与 j 的送气不同。签订意思是签署合同、协议。"}], "explanations": {"坚定": "坚定：立场、信念等稳固，不动摇。", "检定": "检定（jiǎn dìng）与坚定（jiān dìng）第一音节声调不同：第三声与第一声。检定意思是检查、核定。", "鉴定": "鉴定（jiàn dìng）与坚定（jiān dìng）第一音节声调不同：第四声与第一声。鉴定意思是鉴别、评定。", "尖顶": "尖顶（jiān dǐng）与坚定（jiān dìng）第二音节声调不同：第三声与第四声。尖顶意思是尖的顶端。", "签订": "签订（qiān dìng）与坚定（jiān dìng）第一音节声母不同：q 与 j 的送气不同。签订意思是签署合同、协议。"}, "sentence_index": null, "correct_answer": "坚定"}, "level_3": {"options": [{"text": "坚定", "is_correct": true, "explanation": "正确：“立场一直很坚定”指立场稳固，与“一直”所表示的始终如一相符。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼睛，不说立场明亮。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或门庭冷落，不用来形容立场。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不用来形容立场。"}], "explanations": {"坚定": "正确：“立场一直很坚定”指立场稳固，与“一直”所表示的始终如一相符。", "明亮": "搭配：“明亮”形容光线或眼睛，不说立场明亮。", "冷清": "搭配：“冷清”形容场所或门庭冷落，不用来形容立场。", "嘹亮": "搭配：“嘹亮”形容声音，不用来形容立场。"}, "sentence_index": 0, "correct_answer": "坚定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼的地基很坚定，经得起地震。", "explanation": "这里应该用〈坚固〉。“坚定”的“稳定牢固”义多用于立场、信念、步伐等，形容地基、建筑的牢固要用“坚固”。"}, {"text": "这种材料很坚定，不容易断。", "explanation": "这里应该用〈坚韧〉。“坚定”多用于立场、信念等，形容材料有韧性、不易断要用“坚韧”。"}, {"text": "这件事的结果还没有坚定。", "explanation": "这里应该用〈确定〉。“坚定”指立场或信念不变，事情的结果定下来要用“确定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚定", "is_correct": true, "explanation": "正确：“和平政策一直很坚定”指政策稳固、不改变，与“和平”和“一直”相符。"}, {"text": "好战", "is_correct": false, "explanation": "语义：“好战”指喜欢发动战争，与“和平政策”的含义相矛盾。"}, {"text": "高亢", "is_correct": false, "explanation": "搭配：“高亢”形容声音或情绪激昂，不用来形容政策。"}, {"text": "冷淡", "is_correct": false, "explanation": "搭配：“冷淡”形容人的态度，不用来形容政策。"}], "explanations": {"坚定": "正确：“和平政策一直很坚定”指政策稳固、不改变，与“和平”和“一直”相符。", "好战": "语义：“好战”指喜欢发动战争，与“和平政策”的含义相矛盾。", "高亢": "搭配：“高亢”形容声音或情绪激昂，不用来形容政策。", "冷淡": "搭配：“冷淡”形容人的态度，不用来形容政策。"}, "sentence_index": 6, "correct_answer": "坚定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两块木板连接得很坚定。", "explanation": "这里应该用〈牢固〉。“坚定”多用于立场、信念等，两块木板连接稳固要用“牢固”。"}, {"text": "这块岩石很坚定。", "explanation": "这里应该用〈坚硬〉。“坚定”不用于形容物体的硬度，岩石的硬要说“坚硬”。"}, {"text": "这家公司的股价很坚定。", "explanation": "这里应该用〈坚挺〉。股价稳定上涨说“坚挺”，“坚定”多用于立场、信念等，不用于股价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这个原则有坚定地信念。", "corrected_sentence": "他对这个原则有坚定的信念。", "error_description": "“坚定”修饰名词“信念”时要用结构助词“的”，不能用“地”。正确说法是“坚定的信念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经历这次事故后，他的信念更坚定着。", "corrected_sentence": "经历这次事故后，他的信念更坚定了。", "error_description": "表示信念变得更稳固，句末应用“了”表示变化，不用“着”。“着”一般表示动作或状态持续，不用于这样的变化。正确说法是“更坚定了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b077b82-4e39-4b73-b21e-c84aaad996d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
