INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94255, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大街是城里又宽又长、车和人很多的路。", "primary_collocate": null, "pronunciation": "dà jiē", "ipa": "ta˥˩ tɕje˥˥", "syllable_count": 2, "sentences": [{"text": "大街上有很多车和人。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走在大街上，听到很吵的声音。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大街又宽又长。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大街上的人都跑回家。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大街上等朋友。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在大街上不能跑。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大街两边都是商店和饭馆。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过大街时，要看红绿灯。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，大街上的灯亮着。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家前面就是一条大街。", "target_word": "大街", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "大街小巷", "label": "复合"}], "register": "中性", "sense_fingerprint": "城里又宽又长、车人很多的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94c76b39-0b43-41b7-acc8-e7c4649e2034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大街", "is_correct": true, "explanation": "“大街上”指城里又宽又长、车和人很多的路，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：方位词“上”不与“厨房”搭配，应说“厨房里”，而且厨房里不会有很多车。"}, {"text": "大海", "is_correct": false, "explanation": "语义：海上不会有很多车，“大街”指城里的道路。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“教室”的方位应说“教室里”，“教室上”不通，而且教室里没有车。"}], "explanations": {"大街": "“大街上”指城里又宽又长、车和人很多的路，符合句意。", "厨房": "搭配：方位词“上”不与“厨房”搭配，应说“厨房里”，而且厨房里不会有很多车。", "大海": "语义：海上不会有很多车，“大街”指城里的道路。", "教室": "搭配：“教室”的方位应说“教室里”，“教室上”不通，而且教室里没有车。"}, "sentence_index": 0, "correct_answer": "大街"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一条大街，又窄又短。", "explanation": "这里应该用〈小路〉。大街是城里又宽又长的路，不能用来形容又窄又短的路。"}, {"text": "这条大街很大，我们每天在这里做饭。", "explanation": "这里应该用〈厨房〉。大街是道路，不能用来做饭。"}, {"text": "我们在大街上洗澡，水很热。", "explanation": "这里应该用〈浴室〉。大街是露天的道路，不能用来洗澡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大街", "is_correct": true, "explanation": "“两边”指道路的两侧，大街两侧是商店和饭馆，符合句意。"}, {"text": "山", "is_correct": false, "explanation": "语义：山的两边不会是商店和饭馆，句子说的是城里的街道。"}, {"text": "床", "is_correct": false, "explanation": "语义：床的两边不会是商店和饭馆，句子说的是街边的店铺。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“两边”一般用于道路或建筑，“厕所两边”不这样说，而且厕所两边不会有商店和饭馆。"}], "explanations": {"大街": "“两边”指道路的两侧，大街两侧是商店和饭馆，符合句意。", "山": "语义：山的两边不会是商店和饭馆，句子说的是城里的街道。", "床": "语义：床的两边不会是商店和饭馆，句子说的是街边的店铺。", "厕所": "搭配：“两边”一般用于道路或建筑，“厕所两边”不这样说，而且厕所两边不会有商店和饭馆。"}, "sentence_index": 6, "correct_answer": "大街"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天坐大街去学校。", "explanation": "这里应该用〈公共汽车〉。大街是城里的路，不能“坐”，坐的应是交通工具。"}, {"text": "我把钥匙放在大街的抽屉里。", "explanation": "这里应该用〈桌子〉。大街是道路，不能有抽屉，放钥匙的抽屉应属于〈桌子〉。"}, {"text": "这条小大街很热闹。", "explanation": "这里应该用〈小街〉。大街指宽阔繁华的主要道路，不能说“小大街”，窄的道路应说〈小街〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他沿着一个大街慢慢走。", "corrected_sentence": "他沿着一条大街慢慢走。", "error_description": "量词错误：“大街”是道路，量词应用“条”，不能用“个”。正确说法是“一条大街”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察已经大街封起来了。", "corrected_sentence": "警察已经把大街封起来了。", "error_description": "漏掉“把”：错误形式是“警察已经大街封起来了”，正确形式是“警察已经把大街封起来了”。施事“警察”后面要用“把”引出受事“大街”，再接动词“封起来”；没有“把”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9334db56-29c7-4e1a-86ca-d7d4f4b2f2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
