INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法上表示动作已经完成的时态。", "primary_collocate": null, "pronunciation": "wán chéng shí", "ipa": "wan˧˥ ʈʂʰəŋ˧˥ ʂʅ˧˥", "syllable_count": 3, "sentences": [{"text": "老师今天在课上讲了英语的完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子用的是完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "完成时表示动作已经完成。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语里没有英语那样的完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还不太会用完成时造句。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "完成时和过去时有什么不同？", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上有一课专门讲完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把完成时的用法写在本子上。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道语法题考的是完成时。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了完成时，我能说清楚事情做完了没有。", "target_word": "完成时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现在完成时", "label": "复合"}, {"form": "过去完成时", "label": "复合"}, {"form": "将来完成时", "label": "复合"}], "register": "书面", "sense_fingerprint": "语法术语，表示动作已经完成的时态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完成时", "is_correct": true, "explanation": "正确：“完成时”是语法术语，可以作为课上讲的内容，句意通顺。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”是食物，不是课上讲的语法内容，“讲了英语的早餐”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不能作为英语课上讲的内容。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：“讲”后面接的是知识或内容，“电梯”不是可以讲的对象，搭配不成立。"}], "explanations": {"完成时": "正确：“完成时”是语法术语，可以作为课上讲的内容，句意通顺。", "早餐": "语义：“早餐”是食物，不是课上讲的语法内容，“讲了英语的早餐”说不通。", "体温": "语义：“体温”指身体的温度，不能作为英语课上讲的内容。", "电梯": "搭配：“讲”后面接的是知识或内容，“电梯”不是可以讲的对象，搭配不成立。"}, "sentence_index": 0, "correct_answer": "完成时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "英语里的完成时表示经常发生的动作。", "explanation": "这里应该用〈一般现在时〉。完成时强调动作已经做完，经常发生的动作要用一般现在时。"}, {"text": "英语里的完成时表示动作正在进行。", "explanation": "这里应该用〈进行时〉。完成时表示动作已经做完，正在进行的动作要用进行时。"}, {"text": "英语里的完成时表示动作还没有开始。", "explanation": "这里应该用〈将来时〉。完成时表示动作已经做完，还没开始的动作要用将来时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完成时", "is_correct": true, "explanation": "正确：“完成时”是语法术语，书上可以专门讲它，句意通顺。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”是穿在脚上的鞋，书上一课专门讲它，句意很奇怪。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：“饿”是形容词，不能作“讲”的对象，“专门讲饿”说不通。"}, {"text": "慢慢", "is_correct": false, "explanation": "搭配：“慢慢”是副词，不能作“讲”的对象，“专门讲慢慢”说不通。"}], "explanations": {"完成时": "正确：“完成时”是语法术语，书上可以专门讲它，句意通顺。", "拖鞋": "语义：“拖鞋”是穿在脚上的鞋，书上一课专门讲它，句意很奇怪。", "饿": "搭配：“饿”是形容词，不能作“讲”的对象，“专门讲饿”说不通。", "慢慢": "搭配：“慢慢”是副词，不能作“讲”的对象，“专门讲慢慢”说不通。"}, "sentence_index": 6, "correct_answer": "完成时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师今天讲了一朵完成时。", "explanation": "这里应该用〈种〉。“完成时”是时态的类别，要用量词“种”；“朵”用于花，不能用于时态。"}, {"text": "学了完成时，我能说清楚事情还在做。", "explanation": "这里应该用〈进行时〉。说事情还在做要用进行时，完成时表示动作已经完成。"}, {"text": "老师让我们用完成时描述明天要做的事。", "explanation": "这里应该用〈将来时〉。描述明天要做的事要用将来时，完成时说的是已经做完的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "语法书上列了两座完成时。", "corrected_sentence": "语法书上列了两种完成时。", "error_description": "错误：“两座完成时”，应为“两种完成时”。完成时是时态的类别，数类别要用量词“种”；“座”用于山、楼等，不能用于时态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这节课我们学的完成时表示动作正在进行。", "corrected_sentence": "这节课我们学的完成时表示动作已经完成。", "error_description": "错误：“表示动作正在进行”，应为“表示动作已经完成”。完成时强调动作已经做完，不能用来说正在进行的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
