INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对位是两个东西正好放在对的地方。", "primary_collocate": null, "pronunciation": "duì wèi", "ipa": "twei̯⁵¹ wei̯⁵¹", "syllable_count": 2, "sentences": [{"text": "这两个零件的对位很准。", "target_word": "对位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "盖子和瓶口的对位不对，拧不上。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "装瓷砖时，每块砖的对位都要看准。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两张纸的对位出了问题，印出来的字是歪的。", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拼图每块的对位都很重要，错一点就拼不上。", "target_word": "对位", "complexity_tier": "T3", "furigana": "pīn tú měi kuài de duì wèi dōu hěn zhòng yào, cuò yì diǎn jiù pīn bu shàng.", "sentence_source": "generated"}, {"text": "他用尺子量了一下，才知道对位差了一点。", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器的对位准，做出来的东西才整齐。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左右两扇门的对位不好，中间有一条大缝。", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在墙上画了线，对位就容易多了。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做衣服时，两片布的对位要特别小心。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两件东西相互摆放得正好、位置相合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94259, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对位", "is_correct": true, "explanation": "正确答案：对位 duì wèi，指两个东西正好放在对的地方。"}, {"text": "退位", "is_correct": false, "explanation": "tuì wèi 与 duì wèi 声母不同（t 送气，d 不送气），意思是退位，指让出职位。"}, {"text": "对外", "is_correct": false, "explanation": "wài 与 wèi 韵母不同（ai 与 ei），意思是对外，指面向外界。"}, {"text": "队尾", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是队伍的末尾。"}], "explanations": {"对位": "正确答案：对位 duì wèi，指两个东西正好放在对的地方。", "退位": "tuì wèi 与 duì wèi 声母不同（t 送气，d 不送气），意思是退位，指让出职位。", "对外": "wài 与 wèi 韵母不同（ai 与 ei），意思是对外，指面向外界。", "队尾": "wěi（第三声）与 wèi（第四声）声调不同，意思是队伍的末尾。"}, "sentence_index": null, "correct_answer": "对位"}, "level_3": {"options": [{"text": "对位", "is_correct": true, "explanation": "正确：「对位」指两个零件放在对应的位置，与「很准」搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：零件没有味道，「这两个零件的味道很准」说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「准」可以形容位置或尺寸，不能形容价格。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：「容貌」指人的外貌，不能用来描写零件。"}], "explanations": {"对位": "正确：「对位」指两个零件放在对应的位置，与「很准」搭配。", "味道": "语义：零件没有味道，「这两个零件的味道很准」说不通。", "价格": "搭配：「准」可以形容位置或尺寸，不能形容价格。", "容貌": "体貌：「容貌」指人的外貌，不能用来描写零件。"}, "sentence_index": 0, "correct_answer": "对位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱货的对位很重，搬起来很费力。", "explanation": "这里应该用〈重量〉。对位指两物相互吻合的关系，不指轻重，说物体的分量要用重量。"}, {"text": "这本书的对位很厚，放不进书架。", "explanation": "这里应该用〈厚度〉。对位指两物相互吻合，不能用来形容厚薄。"}, {"text": "传送带的对位很快，零件一个个送了过来。", "explanation": "这里应该用〈速度〉。对位指两物的吻合关系，不指快慢，说运动的快慢要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对位", "is_correct": true, "explanation": "正确：「对位」指部件之间相互吻合，与「做出来的东西才整齐」相呼应。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「准」不能用来形容年龄，「机器的年龄准」说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：「准」不能用来形容寿命，「机器的寿命准」说不通。"}, {"text": "气味", "is_correct": false, "explanation": "语义：机器没有气味可以「准」，与「做出来的东西才整齐」没有关系。"}], "explanations": {"对位": "正确：「对位」指部件之间相互吻合，与「做出来的东西才整齐」相呼应。", "年龄": "搭配：「准」不能用来形容年龄，「机器的年龄准」说不通。", "寿命": "搭配：「准」不能用来形容寿命，「机器的寿命准」说不通。", "气味": "语义：机器没有气味可以「准」，与「做出来的东西才整齐」没有关系。"}, "sentence_index": 6, "correct_answer": "对位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的对位很高，做出来的东西很精细。", "explanation": "这里应该用〈精度〉。对位指部件之间的吻合，不能说高低，衡量加工准确程度要用精度。"}, {"text": "这两片布的对位要朝东，缝起来才好看。", "explanation": "这里应该用〈方向〉。对位指两物对应的吻合，不指朝向。"}, {"text": "这块布的对位很鲜艳。", "explanation": "这里应该用〈颜色〉。对位指部件之间的吻合，不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两块玻璃的对位没有对准了。", "corrected_sentence": "这两块玻璃的对位没有对准。", "error_description": "「没有」否定已发生的事，句末不能再加「了」。应说「这两块玻璃的对位没有对准」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两张纸的对位偏得一点。", "corrected_sentence": "两张纸的对位偏了一点。", "error_description": "「偏」后的补语应用「了」表示已经偏离，「偏得」后要接程度词（如「偏得厉害」），不能接「一点」。应说「两张纸的对位偏了一点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
