INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐中指不同声部之间的配合。", "primary_collocate": null, "pronunciation": "duì wèi", "ipa": "twei̯⁵¹ wei̯⁵¹", "syllable_count": 2, "sentences": [{"text": "这首曲子的对位很美。", "target_word": "对位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个声部的对位写得很好。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在学校学过对位，会写简单的小曲。", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴和小提琴的对位让这首歌更有层次。", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这两段旋律的对位不太自然。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合唱团练了很久，才把高音和低音的对位唱好。", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段赋格的对位很复杂。", "target_word": "对位", "complexity_tier": "T3", "furigana": "zhè duàn fù gé de duì wèi hěn fù zá.", "sentence_source": "generated"}, {"text": "乐队在排练，指挥一直在听各声部的对位。", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴赫的曲子里，对位是最重要的写法。", "target_word": "对位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听这首赋格曲，你能听出几个声部的对位吗？", "target_word": "对位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对位法", "label": "复合"}], "register": "专业", "sense_fingerprint": "音乐中不同声部之间的配合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对位", "is_correct": true, "explanation": "正确答案：对位 duì wèi，音乐中指不同声部之间的配合。"}, {"text": "退位", "is_correct": false, "explanation": "tuì wèi 与 duì wèi 声母不同（t 送气，d 不送气），意思是退位，指让出职位。"}, {"text": "对外", "is_correct": false, "explanation": "wài 与 wèi 韵母不同（ai 与 ei），意思是对外，指面向外界。"}, {"text": "队尾", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是队伍的末尾。"}], "explanations": {"对位": "正确答案：对位 duì wèi，音乐中指不同声部之间的配合。", "退位": "tuì wèi 与 duì wèi 声母不同（t 送气，d 不送气），意思是退位，指让出职位。", "对外": "wài 与 wèi 韵母不同（ai 与 ei），意思是对外，指面向外界。", "队尾": "wěi（第三声）与 wèi（第四声）声调不同，意思是队伍的末尾。"}, "sentence_index": null, "correct_answer": "对位"}, "level_3": {"options": [{"text": "对位", "is_correct": true, "explanation": "正确：「对位」是音乐术语，指声部的配合，与「很美」搭配。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「美」可以形容曲子，不能形容价格。"}, {"text": "体重", "is_correct": false, "explanation": "语义：曲子没有体重，「这首曲子的体重很美」说不通。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：「容貌」指人的外貌，不能用来形容曲子。"}], "explanations": {"对位": "正确：「对位」是音乐术语，指声部的配合，与「很美」搭配。", "价格": "搭配：「美」可以形容曲子，不能形容价格。", "体重": "语义：曲子没有体重，「这首曲子的体重很美」说不通。", "容貌": "体貌：「容貌」指人的外貌，不能用来形容曲子。"}, "sentence_index": 0, "correct_answer": "对位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋的对位很合适，穿上很舒服。", "explanation": "这里应该用〈尺码〉。对位是音乐术语，指不同声部之间的配合，不能用来说鞋的大小。"}, {"text": "这个箱子的对位很轻，一只手就能提起来。", "explanation": "这里应该用〈重量〉。对位指音乐中声部之间的配合，不指物体轻重。"}, {"text": "这块石头的对位很圆，像个鸡蛋。", "explanation": "这里应该用〈形状〉。对位指音乐中声部之间的配合，不能形容外形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validatio