INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对位", "is_correct": true, "explanation": "正确：「对位」指声部之间的配合，与「很复杂」搭配。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：「复杂」不能用来形容速度，「这段赋格的速度很复杂」说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：赋格是音乐作品，没有寿命，与「很复杂」也不搭配。"}, {"text": "气味", "is_correct": false, "explanation": "语义：赋格没有气味，「这段赋格的气味很复杂」说不通。"}], "explanations": {"对位": "正确：「对位」指声部之间的配合，与「很复杂」搭配。", "速度": "搭配：「复杂」不能用来形容速度，「这段赋格的速度很复杂」说不通。", "寿命": "语义：赋格是音乐作品，没有寿命，与「很复杂」也不搭配。", "气味": "语义：赋格没有气味，「这段赋格的气味很复杂」说不通。"}, "sentence_index": 6, "correct_answer": "对位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首曲子的对位很快，弹起来很有气势。", "explanation": "这里应该用〈速度〉。对位指声部的配合，不能说快慢。"}, {"text": "他弹奏时对位很大，声音很厚。", "explanation": "这里应该用〈力度〉。对位指声部的配合，不指力量的大小。"}, {"text": "这支小提琴的对位很亮。", "explanation": "这里应该用〈音色〉。对位指声部的配合，不能用来形容音色明暗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首曲子地对位很美。", "corrected_sentence": "这首曲子的对位很美。", "error_description": "「这首曲子」修饰名词「对位」，中间应该用「的」，不能用「地」。应说「这首曲子的对位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的对位写很清楚，声部分明。", "corrected_sentence": "他的对位写得很清楚，声部分明。", "error_description": "动词「写」后应加补语标记「得」，应说「写得很清楚」，不能说「写很清楚」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94261, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大写", "is_correct": true, "explanation": "正确答案。“大写”与“小写”在金额或数字书写形式上互为反义。"}, {"text": "数字", "is_correct": false, "explanation": "“数字”是数目字符的总称，不是“小写”的反义词，二者不构成对立。"}, {"text": "字母", "is_correct": false, "explanation": "“字母”是文字符号，不是“小写”的反义词，二者不构成对立。"}, {"text": "账单", "is_correct": false, "explanation": "“账单”是账目单据，与“小写”没有反义关系。"}], "correct_answer": "大写", "explanations": {"大写": "正确答案。“大写”与“小写”在金额或数字书写形式上互为反义。", "数字": "“数字”是数目字符的总称，不是“小写”的反义词，二者不构成对立。", "字母": "“字母”是文字符号，不是“小写”的反义词，二者不构成对立。", "账单": "“账单”是账目单据，与“小写”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94261, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大写", "is_correct": true, "explanation": "正确答案。“大写”与“小写”在金额或数字书写形式上互为反义。"}, {"text": "草书", "is_correct": false, "explanation": "“草书”是字体名称，与“小写”没有反义关系。"}, {"text": "银行", "is_correct": false, "explanation": "“银行”是金融机构，与“小写”没有反义关系。"}, {"text": "收据", "is_correct": false, "explanation": "“收据”是凭证，与“小写”没有反义关系。"}], "correct_answer": "大写", "explanations": {"大写": "正确答案。“大写”与“小写”在金额或数字书写形式上互为反义。", "草书": "“草书”是字体名称，与“小写”没有反义关系。", "银行": "“银行”是金融机构，与“小写”没有反义关系。", "收据": "“收据”是凭证，与“小写”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94261, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "小写是金额或数字用阿拉伯数字（如 5000）的写法，与“大写”（汉字数字）相对。", "primary_collocate": null, "pronunciation": "xiǎo xiě", "ipa": "ɕjɑʊ˨˩ ɕjɛ˨˩", "syllable_count": 2, "sentences": [{"text": "这张支票上的金额，大写和小写不一样。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里填上金额的小写。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "付款单上的金额，先写小写，再写大写。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数字的大写是“叁”，小写是3。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写数字的时候，用的是小写。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同里的金额，小写是5000元，大写是伍仟元。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行单子上的大写和小写要一样。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你把金额的小写写错了，要重写。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收据上只写了小写，没有写大写。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "填支票时，小写要写在方格里。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小写金额", "label": "复合"}, {"form": "小寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小写：金额或数字的阿拉伯数字写法，与汉字大写相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94261, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小写", "is_correct": true, "explanation": "正确答案。小写指金额或数字用阿拉伯数字的写法，与大写相对。"}, {"text": "小些", "is_correct": false, "explanation": "xiē（第一声）与 xiě（第三声）声调不同，意思是稍微小一点。"}, {"text": "小鞋", "is_correct": false, "explanation": "xié（第二声）与 xiě（第三声）声调不同，意思是小码的鞋。"}, {"text": "小姐", "is_correct": false, "explanation": "jiě 与 xiě 声母不同（j 与 x），意思是年轻女子或对女子的称呼。"}], "explanations": {"小写": "正确答案。小写指金额或数字用阿拉伯数字的写法，与大写相对。", "小些": "xiē（第一声）与 xiě（第三声）声调不同，意思是稍微小一点。", "小鞋": "xié（第二声）与 xiě（第三声）声调不同，意思是小码的鞋。", "小姐": "jiě 与 xiě 声母不同（j 与 x），意思是年轻女子或对女子的称呼。"}, "sentence_index": null, "correct_answer": "小写"}, "level_3": {"options": [{"text": "小写", "is_correct": true, "explanation": "正确答案。“小写”与前文的“大写”对举，指金额用阿拉伯数字的写法。"}, {"text": "小数", "is_correct": false, "explanation": "语义：“小数”是数的一种，不是书写形式，与“大写”不成对。"}, {"text": "小号", "is_correct": false, "explanation": "搭配：“小号”说尺寸，不用来与“大写”对举书写方式。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”指账目单据，不是金额的书写形式。"}], "explanations": {"小写": "正确答案。“小写”与前文的“大写”对举，指金额用阿拉伯数字的写法。", "小数": "语义：“小数”是数的一种，不是书写形式，与“大写”不成对。", "小号": "搭配：“小号”说尺寸，不用来与“大写”对举书写方式。", "账单": "语义：“账单”指账目单据，不是金额的书写形式。"}, "sentence_index": 0, "correct_answer": "小写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张收据的金额要用小写写成汉字。", "explanation": "这里应该用〈大写〉。金额写成汉字要用大写，小写是阿拉伯数字，不能写成汉字。"}, {"text": "他写字的时候把字写得很小，我们叫这种写法为小写。", "explanation": "“小写”指金额或数字的阿拉伯数字写法，不指字写得小，这里用法不对。"}, {"text": "这双鞋我穿小写的，你穿大号的。", "explanation": "这里应该用〈小号〉。鞋子的尺码说“小号”，“小写”指金额或数字的阿拉伯数字写法，不能用来说鞋的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小写", "is_correct": true, "explanation": "正确答案。银行单子上的大写和小写都要填写，且须一致。"}, {"text": "字母", "is_correct": false, "explanation": "语义：“字母”不是金额的书写形式，与“大写”不成对。"}, {"text": "草书", "is_correct": false, "explanation": "语义：“草书”是字体，与“大写”不对举，句中说的是金额的写法。"}, {"text": "大号", "is_correct": false, "explanation": "搭配：“大号”说尺寸，不用来和“大写”对举书写方式。"}], "explanations": {"小写": "正确答案。银行单子上的大写和小写都要填写，且须一致。", "字母": "语义：“字母”不是金额的书写形式，与“大写”不成对。", "草书": "语义：“草书”是字体，与“大写”不对举，句中说的是金额的写法。", "大号": "搭配：“大号”说尺寸，不用来和“大写”对举书写方式。"}, "sentence_index": 6, "correct_answer": "小写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个汉字的小写是什么？", "explanation": "“小写”指金额或数字的阿拉伯数字写法，不能用来指汉字。"}, {"text": "这张支票上的小写是我的名字。", "explanation": "“小写”指金额的数字写法，不能用来指人的名字。"}, {"text": "我每天都用小写来刷牙。", "explanation": "“小写”是书写形式，不指刷牙的动作，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "合同上金额的小写5000元。", "corrected_sentence": "合同上金额的小写是5000元。", "error_description": "错误形式：“小写”后面漏了判断动词“是”，直接接“5000元”。正确形式：“的小写是5000元”。判断句要用“是”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "填写支票时，金额要小写写在方格里。", "corrected_sentence": "填写支票时，金额要用小写写在方格里。", "error_description": "错误形式：“小写”前漏了介词“用”。正确形式：“用小写写”。“用……写”表示书写所用的方式，不能直接把“小写”放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
