INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "字母的小号写法，与大写相对。", "primary_collocate": null, "pronunciation": "xiǎo xiě", "ipa": "ɕjɑʊ˨˩ ɕjɛ˨˩", "syllable_count": 2, "sentences": [{"text": "英文名字的第一个字母要用大写，后面的用小写。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字母是小写的，不是大写的。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上的密码要分大写和小写。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这个单词全部改成小写。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机键盘上默认的字母是小写。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字母的小写比大写简单。", "target_word": "小写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把网址里的字母都写成了小写。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写英文的时候，除了名字，其他字母一般用小写。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么写英文字母的大写和小写。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字母写成小写，看起来像另一个字母。", "target_word": "小写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小写字母", "label": "复合"}, {"form": "小寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小写：字母的小号写法，与大写相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小写", "is_correct": true, "explanation": "正确答案。小写指字母的小号写法，与大写相对。"}, {"text": "小歇", "is_correct": false, "explanation": "xiē（第一声）与 xiě（第三声）声调不同，意思是稍作休息。"}, {"text": "小鞋", "is_correct": false, "explanation": "xié（第二声）与 xiě（第三声）声调不同，意思是小码的鞋。"}, {"text": "小姐", "is_correct": false, "explanation": "jiě 与 xiě 声母不同（j 与 x），意思是年轻女子或对女子的称呼。"}], "explanations": {"小写": "正确答案。小写指字母的小号写法，与大写相对。", "小歇": "xiē（第一声）与 xiě（第三声）声调不同，意思是稍作休息。", "小鞋": "xié（第二声）与 xiě（第三声）声调不同，意思是小码的鞋。", "小姐": "jiě 与 xiě 声母不同（j 与 x），意思是年轻女子或对女子的称呼。"}, "sentence_index": null, "correct_answer": "小写"}, "level_3": {"options": [{"text": "小写", "is_correct": true, "explanation": "正确答案。“后面的用小写”与前句“第一个字母用大写”对举，指字母的小号写法。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：“后面的用汉字”与英文字母的书写无关，句意不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：“数字”指数目字符，不是字母的书写方式，句意不通。"}, {"text": "拼音", "is_correct": false, "explanation": "语义：“拼音”是给汉字注音的字母，与英文字母的大小写无关，句意不通。"}], "explanations": {"小写": "正确答案。“后面的用小写”与前句“第一个字母用大写”对举，指字母的小号写法。", "汉字": "语义：“后面的用汉字”与英文字母的书写无关，句意不通。", "数字": "语义：“数字”指数目字符，不是字母的书写方式，句意不通。", "拼音": "语义：“拼音”是给汉字注音的字母，与英文字母的大小写无关，句意不通。"}, "sentence_index": 0, "correct_answer": "小写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家就住在小写旁边。", "explanation": "这里应该用〈小区〉。住的地方说“小区”，“小写”只指字母的小号写法，不指地方。"}, {"text": "这个汉字的小写是什么？", "explanation": "“小写”只用于有大小写之分的拉丁字母，汉字没有大小写，这里用法不对。"}, {"text": "妈妈经常哼小写。", "explanation": "这里应该用〈小调〉。小调是一种曲调，要说“哼小调”，“小写”不指歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小写", "is_correct": true, "explanation": "正确答案。“写成了小写”指把字母改成小号写法。"}, {"text": "小数", "is_correct": false, "explanation": "语义：“小数”指十进制数，不指字母的写法，句意不通。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”不是书写形式，“写成了账单”不合语义。"}, {"text": "小时", "is_correct": false, "explanation": "语义：“小时”是时间单位，不是字母的写法，“写成了小时”不通。"}], "explanations": {"小写": "正确答案。“写成了小写”指把字母改成小号写法。", "小数": "语义：“小数”指十进制数，不指字母的写法，句意不通。", "账单": "语义：“账单”不是书写形式，“写成了账单”不合语义。", "小时": "语义：“小时”是时间单位，不是字母的写法，“写成了小时”不通。"}, "sentence_index": 6, "correct_answer": "小写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的小写是M号。", "explanation": "这里应该用〈小号〉。衣服尺码说“小号”，“小写”只指字母的小号写法。"}, {"text": "我每天晚上都看小写，很有意思。", "explanation": "这里应该用〈小说〉。小说是文学作品，“小写”只指字母的小号写法，不能用来指看的书。"}, {"text": "他拉得一手好小写，老师很喜欢。", "explanation": "这里应该用〈小提琴〉。“拉”的对象是乐器，“小写”不指乐器，不能用来说拉琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个字母的小写写很清楚。", "corrected_sentence": "这个字母的小写写得很清楚。", "error_description": "错误形式：动词“写”后面漏了补语标记“得”，说成“写很清楚”。正确形式：“写得很清楚”。“很”不能直接放在动词后面作补语，要用“得”引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个大写字母K的小写k。", "corrected_sentence": "这个大写字母K的小写是k。", "error_description": "错误形式：“小写”后面漏了判断动词“是”，直接接“k”。正确形式：“的小写是k”。判断句要用“是”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
