INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94263, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小镇是比城市小、人不多的地方。", "primary_collocate": null, "pronunciation": "xiǎo zhèn", "ipa": "ɕjaʊ˨˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "我家在一个安静的小镇。", "target_word": "小镇", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小镇里的人不多，大家都认识。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从城市坐车到小镇要一个小时。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇比城市安静多了。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小镇的晚上很安静，路上没有几个人。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在小镇上开了一家小店。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小镇来到大城市工作。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在小镇住过两年，很喜欢那里。", "target_word": "小镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇里有一条河，河边种着很多树。", "target_word": "小镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到周末，城里的人都想去小镇玩。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "小鎮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比城市小、人口少、生活安静的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小镇", "is_correct": true, "explanation": "正确：「小镇」是比城市小、人不多的地方，「安静的小镇」符合句意。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：夜市通常热闹，与「安静」矛盾。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场通常人多、嘈杂，与「安静」矛盾。"}, {"text": "演唱会", "is_correct": false, "explanation": "搭配：「安静」不能修饰演唱会这类热闹的活动。"}], "explanations": {"小镇": "正确：「小镇」是比城市小、人不多的地方，「安静的小镇」符合句意。", "夜市": "语义：夜市通常热闹，与「安静」矛盾。", "菜市场": "语义：菜市场通常人多、嘈杂，与「安静」矛盾。", "演唱会": "搭配：「安静」不能修饰演唱会这类热闹的活动。"}, "sentence_index": 0, "correct_answer": "小镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇有一百万人。", "explanation": "这里应该用〈城市〉。小镇人口少，不能说有一百万人，这样的人口规模要说城市。"}, {"text": "我们在小镇的地铁站附近住过两年。", "explanation": "这里误用了「小镇」：小镇规模小，一般没有地铁，这种情况属于城市，应改用〈城市〉。"}, {"text": "这个小镇有五十座高楼大厦和十条地铁线。", "explanation": "这里误用了「小镇」：小镇规模小、人不多，五十座高楼和十条地铁线属于城市，应改用〈城市〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小镇", "is_correct": true, "explanation": "正确：「小镇」与「大城市」对比，「她从小镇来到大城市工作」符合句意。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是人可以「从……来到大城市工作」的地方。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是人生活过的地方，与「来到大城市工作」的语境不符。"}, {"text": "卧室", "is_correct": false, "explanation": "搭配：卧室是住宅内的房间，不能作为「来到大城市」的起点。"}], "explanations": {"小镇": "正确：「小镇」与「大城市」对比，「她从小镇来到大城市工作」符合句意。", "海洋": "语义：海洋不是人可以「从……来到大城市工作」的地方。", "厨房": "语义：厨房是做饭的地方，不是人生活过的地方，与「来到大城市工作」的语境不符。", "卧室": "搭配：卧室是住宅内的房间，不能作为「来到大城市」的起点。"}, "sentence_index": 6, "correct_answer": "小镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小镇有三万平方公里。", "explanation": "这里误用了「小镇」：它指规模小、人不多的地方，三万平方公里的面积属于省级地区，应说〈省〉。"}, {"text": "这个小镇有很多国际机场。", "explanation": "这里应该用〈首都〉。国际机场多见于首都或大城市，小镇规模小，不会有很多国际机场。"}, {"text": "这个小镇有三千张病床。", "explanation": "这里应该用〈医院〉。三千张病床是医院的规模，小镇规模小，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想住在一条小镇上。", "corrected_sentence": "我想住在一个小镇上。", "error_description": "错误在量词。「小镇」应用量词「个」或「座」，不用「条」，「条」多用于河、路。应说「一个小镇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个安静地小镇。", "corrected_sentence": "这是一个安静的小镇。", "error_description": "「安静」修饰名词「小镇」，中间应该用「的」，不能用「地」。应说「一个安静的小镇」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
