INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "规模较小的镇子。", "primary_collocate": null, "pronunciation": "xiǎo zhèn", "ipa": "ɕjaʊ˨˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "这个小镇只有一条街。", "target_word": "小镇", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小镇很小，走一圈只要十分钟。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小镇有一所学校和一家医院。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小镇中间有一个小广场。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，小镇的路上都是水。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把家搬到海边的小镇。", "target_word": "小镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇不大，有名的饭馆只有两家。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座小镇有三百多年的历史。", "target_word": "小镇", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在山里的小镇长大，没去过大城市。", "target_word": "小镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客很少来这个小镇，所以这里很安静。", "target_word": "小镇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "小鎮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "面积小、街道少、规模不大的镇子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小镇", "is_correct": true, "explanation": "正确：「小镇」规模小、街道少，「这个小镇只有一条街」符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海没有街道，与「只有一条街」矛盾。"}, {"text": "大都市", "is_correct": false, "explanation": "语义：大都市街道很多，不可能「只有一条街」。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：手机不是地方，不能说「只有一条街」。"}], "explanations": {"小镇": "正确：「小镇」规模小、街道少，「这个小镇只有一条街」符合句意。", "大海": "语义：大海没有街道，与「只有一条街」矛盾。", "大都市": "语义：大都市街道很多，不可能「只有一条街」。", "手机": "搭配：手机不是地方，不能说「只有一条街」。"}, "sentence_index": 0, "correct_answer": "小镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇有很多条地铁线。", "explanation": "这里应该用〈城市〉。小镇街道少、规模小，不会有很多条地铁线，这样的情况属于城市。"}, {"text": "他在一个有三百万人口的小镇长大。", "explanation": "这里误用了「小镇」：它指规模较小的镇子，三百万人口的规模属于城市，应改用〈城市〉。"}, {"text": "这个小镇有五十万人口。", "explanation": "这里应该用〈县城〉。小镇规模不大，不能说有五十万人口，这样的规模要说县城。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小镇", "is_correct": true, "explanation": "正确：「小镇不大」与后面「有名的饭馆只有两家」相符，句意通顺。"}, {"text": "北京", "is_correct": false, "explanation": "语义：北京是大城市，不会说「不大」，与句子的前半句矛盾。"}, {"text": "银河", "is_correct": false, "explanation": "语义：银河非常大，不能说「不大」。"}, {"text": "寒舍", "is_correct": false, "explanation": "语义：「寒舍」是对自己家的谦称，家里不会有「有名的饭馆」，与句意不符。"}], "explanations": {"小镇": "正确：「小镇不大」与后面「有名的饭馆只有两家」相符，句意通顺。", "北京": "语义：北京是大城市，不会说「不大」，与句子的前半句矛盾。", "银河": "语义：银河非常大，不能说「不大」。", "寒舍": "语义：「寒舍」是对自己家的谦称，家里不会有「有名的饭馆」，与句意不符。"}, "sentence_index": 6, "correct_answer": "小镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小镇有三十多条高架桥。", "explanation": "这里误用了「小镇」：它指规模较小的镇子，三十多条高架桥属于城市规模，应改用〈城市〉。"}, {"text": "这个小镇的人口有两千万。", "explanation": "这里应该用〈首都〉。两千万人口是首都的规模，小镇人口少，不能这样说。"}, {"text": "这个小镇每天有两百个航班。", "explanation": "这里应该用〈机场〉。每天两百个航班是机场的规模，小镇规模小，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山脚下有一条小镇。", "corrected_sentence": "山脚下有一座小镇。", "error_description": "错误在量词。「小镇」应用量词「座」或「个」，不用「条」，「条」多用于河、路。应说「一座小镇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个规模不大小镇。", "corrected_sentence": "这是一个规模不大的小镇。", "error_description": "错误在修饰语后面漏了「的」。「规模不大」修饰「小镇」时要加「的」，应说「规模不大的小镇」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
