INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94265, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "往来是两个人或两个地方，你去我也去，常常走动。", "primary_collocate": null, "pronunciation": "wǎng lái", "ipa": "wɑŋ²¹⁴ lai̯³⁵", "syllable_count": 2, "sentences": [{"text": "我们两家常常往来。", "target_word": "往来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他和邻居往来很密切。", "target_word": "往来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两个村子隔着一条河，人们却常往来。", "target_word": "往来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从吵了架，他们就不再往来了。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王和我是老同学，这些年一直往来。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个城市离得很近，朋友们周末常往来。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是亲戚，过年时两家总要互相往来。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和他只是同事，平时很少往来。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毕业以后，我们和老师还往来过几年。", "target_word": "往来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家几十年来一直互相往来。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "往来过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人与人、家与家之间互相走动、常来常去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "往来", "is_correct": true, "explanation": "正确：「往来」指两家之间互相走动，与「常常」「两家」搭配。"}, {"text": "出生", "is_correct": false, "explanation": "语义：「出生」指人或事物开始存在，「两家常常出生」说不通。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：「倒塌」指建筑等倒下，不能用来描写两家人的关系。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：「喜欢」要带宾语，「我们两家常常喜欢」缺少宾语，说不通。"}], "explanations": {"往来": "正确：「往来」指两家之间互相走动，与「常常」「两家」搭配。", "出生": "语义：「出生」指人或事物开始存在，「两家常常出生」说不通。", "倒塌": "语义：「倒塌」指建筑等倒下，不能用来描写两家人的关系。", "喜欢": "配价：「喜欢」要带宾语，「我们两家常常喜欢」缺少宾语，说不通。"}, "sentence_index": 0, "correct_answer": "往来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这份礼物往来给了老师。", "explanation": "这里应该用〈送〉。往来指双方之间的走动交往，不表示把东西交给别人，也不能直接带物作宾语。"}, {"text": "我想在商场往来一件外套。", "explanation": "这里应该用〈买〉。往来不表示购买东西，也不能直接带物作宾语。"}, {"text": "他往来了一棵小树，把它种在院子里。", "explanation": "这里应该用〈栽〉。往来表示来回走动或交往，不能带「树」作宾语，也不表示种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往来", "is_correct": true, "explanation": "正确：「互相往来」指两家在过年时互相走动，与「亲戚」「过年」相呼应。"}, {"text": "战斗", "is_correct": false, "explanation": "语义：亲戚之间过年时不会「互相战斗」，与语境冲突。"}, {"text": "离开", "is_correct": false, "explanation": "配价：「离开」要带宾语，且不能说「互相离开」，搭配不成立。"}, {"text": "生病", "is_correct": false, "explanation": "语义：「互相生病」说不通，与「过年时两家总要」的语境不合。"}], "explanations": {"往来": "正确：「互相往来」指两家在过年时互相走动，与「亲戚」「过年」相呼应。", "战斗": "语义：亲戚之间过年时不会「互相战斗」，与语境冲突。", "离开": "配价：「离开」要带宾语，且不能说「互相离开」，搭配不成立。", "生病": "语义：「互相生病」说不通，与「过年时两家总要」的语境不合。"}, "sentence_index": 6, "correct_answer": "往来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱往来给了儿子，自己什么也没留。", "explanation": "这里应该用〈汇〉。往来指双方之间的走动交往，不表示把钱转给别人。"}, {"text": "学生往来了黑板上的字，抄在本子上。", "explanation": "这里应该用〈看〉。往来指双方之间的走动交往，不能带「字」作宾语，也不表示看。"}, {"text": "这台机器往来了一个小时，终于停了。", "explanation": "这里应该用〈运转〉。往来指人或车辆之间的走动交往，不指机器运转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们两家以前往来了过很多年。", "corrected_sentence": "我们两家以前往来过很多年。", "error_description": "「往来」后的体标「过」与「了」不能同时出现，应说「往来过很多年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我与他经常往来他，关系很好。", "corrected_sentence": "我与他经常往来，关系很好。", "error_description": "「往来」是不及物动词，不能直接带「他」作宾语，对象要用「与他」引出。应说「我与他经常往来」，去掉后面的「他」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94266, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94266, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94266, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来和去，往返移动。", "primary_collocate": null, "pronunciation": "wǎng lái", "ipa": "wɑŋ²¹⁴ lai̯³⁵", "syllable_count": 2, "sentences": [{"text": "街上行人往来不断。", "target_word": "往来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桥上车辆往来，非常热闹。", "target_word": "往来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车站里，旅客往来匆匆。", "target_word": "往来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河上有很多小船往来，一天都不停。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年前，路上往来的人特别多。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路太窄，两个方向的车不能同时往来。", "target_word": "往来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "港口里，货船和渡船往来频繁。", "target_word": "往来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人们在两国之间往来，做了不少生意。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下班时，地铁口的人群往来穿梭。", "target_word": "往来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的路上，家长和孩子往来不停。", "target_word": "往来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "往来过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或车船来来去去、往返不停", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "往来", "is_correct": true, "explanation": "正确：「往来不断」指行人来来去去，与「街上行人」搭配。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：「下雨」是天气，不是人的行为，「街上行人下雨不断」说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：行人在街上睡觉不断，与「街上」的热闹场景不合。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：「喜欢」要带宾语，「街上行人喜欢不断」缺少宾语，说不通。"}], "explanations": {"往来": "正确：「往来不断」指行人来来去去，与「街上行人」搭配。", "下雨": "语义：「下雨」是天气，不是人的行为，「街上行人下雨不断」说不通。", "睡觉": "语义：行人在街上睡觉不断，与「街上」的热闹场景不合。", "喜欢": "配价：「喜欢」要带宾语，「街上行人喜欢不断」缺少宾语，说不通。"}, "sentence_index": 0, "correct_answer": "往来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把这箱货往来给了客户。", "explanation": "这里应该用〈送〉。往来只表示来回移动，不表示把东西交给别人，也不能带「货」作宾语。"}, {"text": "我往来了这张纸，把它画成了地图。", "explanation": "这里应该用〈拿〉。往来只表示来回移动，不能带「纸」作宾语，「往来了这张纸」说不通。"}, {"text": "我把这些书往来在桌子上，全都摆好了。", "explanation": "这里应该用〈摆〉。往来表示来回移动，不表示把东西放置在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往来", "is_correct": true, "explanation": "正确：「往来频繁」指船只来来去去，与「港口里」「货船和渡船」搭配。"}, {"text": "下降", "is_correct": false, "explanation": "语义：「下降频繁」说不通，「下降」指从高处往低处，与船只往来无关。"}, {"text": "出生", "is_correct": false, "explanation": "语义：「出生」指人或事物开始存在，「货船和渡船出生频繁」说不通。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：「倒塌」指建筑等倒下，不能用来描写船只的移动。"}], "explanations": {"往来": "正确：「往来频繁」指船只来来去去，与「港口里」「货船和渡船」搭配。", "下降": "语义：「下降频繁」说不通，「下降」指从高处往低处，与船只往来无关。", "出生": "语义：「出生」指人或事物开始存在，「货船和渡船出生频繁」说不通。", "倒塌": "语义：「倒塌」指建筑等倒下，不能用来描写船只的移动。"}, "sentence_index": 6, "correct_answer": "往来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把行李往来放在地上，没有带走。", "explanation": "这里应该用〈放〉。往来指来回走动，不表示把东西放下。"}, {"text": "我们在花园里往来了一朵花。", "explanation": "这里应该用〈摘〉。往来不表示摘取植物。"}, {"text": "他往来了一封信，寄给了朋友。", "explanation": "这里应该用〈写〉。往来表示来回移动或交往，不表示写信，也不能带「信」作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上的汽车往来了不断。", "corrected_sentence": "街上的汽车往来不断。", "error_description": "「往来不断」是固定结构，「往来」与「不断」之间不能插入「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "货车把两个城市之间往来。", "corrected_sentence": "货车在两个城市之间往来。", "error_description": "「往来」是不及物动词，不能用「把」字结构。表示在某处来回行驶，应用「在」引出处所，把「把」改为「在」，说「货车在两个城市之间往来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
