INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94267, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找着是找到了想找的东西。", "primary_collocate": null, "pronunciation": "zhǎo zháo", "ipa": "ʈʂaʊ̯˨˩ ʈʂaʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "找了一个小时，我终于找着钥匙了。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机丢了，现在还没找着。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书包里找着了那本词典。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈找着一件旧毛衣，给了弟弟。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天丢的钱包，今天早上找着了。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要的那张照片，我找着了。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找着朋友的电话号码，马上打了过去。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在院子里找着了自己的玩具。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找遍了房间，也没找着眼镜。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师找着了丢失的作业本，很高兴。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找不着", "label": "否定式"}, {"form": "找得着", "label": "可能补语"}], "register": "口语", "sense_fingerprint": "找着：找到了丢失或想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找着", "is_correct": true, "explanation": "正确：“找着”表示找到了想找的东西，与前面“找了一个小时”的寻找过程相接。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“钥匙”作宾语，句子不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物或水，不能说煮钥匙。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”不能带“钥匙”作宾语，句子不通。"}], "explanations": {"找着": "正确：“找着”表示找到了想找的东西，与前面“找了一个小时”的寻找过程相接。", "吃": "搭配：“吃”不能带“钥匙”作宾语，句子不通。", "煮": "搭配：“煮”的对象是食物或水，不能说煮钥匙。", "吹": "搭配：“吹”不能带“钥匙”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "找着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找着了很大的脾气，把桌子拍了一下。", "explanation": "这里应该用〈发〉。找着指找到想找的东西，脾气不能去找，要说发脾气。"}, {"text": "我找着了两个小时，就把作业写完了。", "explanation": "这里应该用〈花〉。找着指找到想找的东西，时间不能被找到，要说花了两个小时。"}, {"text": "我找着了一个念头，决定去旅行。", "explanation": "这里应该用〈想到〉。找着指找到想找的东西，念头是想出来的，要说想到一个念头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找着", "is_correct": true, "explanation": "正确：“找着”表示找到了朋友的电话号码，所以马上打了过去。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是记不住，与“马上打了过去”需要知道号码相矛盾。"}, {"text": "删掉", "is_correct": false, "explanation": "语义：“删掉”是去除，号码已经没有了，就无法打过去。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”的对象多是希望、努力之类，不能说放弃电话号码。"}], "explanations": {"找着": "正确：“找着”表示找到了朋友的电话号码，所以马上打了过去。", "忘记": "语义：“忘记”是记不住，与“马上打了过去”需要知道号码相矛盾。", "删掉": "语义：“删掉”是去除，号码已经没有了，就无法打过去。", "放弃": "搭配：“放弃”的对象多是希望、努力之类，不能说放弃电话号码。"}, "sentence_index": 6, "correct_answer": "找着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟找着了一个感冒，要去看医生。", "explanation": "这里应该用〈得〉。找着指找到想找的东西，感冒不能去找，要说得了感冒。"}, {"text": "他找着了一场大雨，只好回家。", "explanation": "这里应该用〈遇上〉。找着指找到想找的东西，大雨是天气现象，无法寻找，只能说遇上。"}, {"text": "妈妈找着了一个好笑的梦，早上高兴地告诉我们。", "explanation": "这里应该用〈做〉。找着指找到想找的东西，梦是睡着后做出来的，不能去找，要说做了一个好笑的梦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于找着过眼镜。", "corrected_sentence": "他终于找着了眼镜。", "error_description": "错误形式是“找着过眼镜”，把表示完成的“了”换成了“过”。“过”表示曾经有过的经历，与“终于”说明的最终结果不符。正确形式是“找着了眼镜”，“找着”后用“了”表示已经找到。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈刚才终于找着过她的围巾。", "corrected_sentence": "妈妈刚才终于找着了她的围巾。", "error_description": "错误形式是“找着过她的围巾”。“刚才终于”说的是这一次找的结果，不能用表示经历的“过”。正确形式是“找着了她的围巾”，“找着”后用“了”表示已经找到。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
