INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94268, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找到；找的结果达到了。", "primary_collocate": null, "pronunciation": "zhǎo zháo", "ipa": "ʈʂaʊ̯˨˩ ʈʂaʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我在地图上找着了学校的位置。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找了半天，他才找着出口。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山下找着一家小饭馆。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你找着工作了吗？", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她找着一个好房子，下个月搬家。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我四处找人帮忙，可是没找着。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子找着妈妈，不哭了。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上找着了很多有用的资料。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家书店很难找，我找了很久才找着。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "终于找着路了，我们快走吧。", "target_word": "找着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找不着", "label": "否定式"}, {"form": "找得着", "label": "可能补语"}], "register": "口语", "sense_fingerprint": "找着：找的结果达到，找到人、地方或工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找着", "is_correct": true, "explanation": "正确：“找着”表示找的结果达到了，找到了学校的位置。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说喝位置。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”用于食物，地图上的位置不能烤。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”不能带“位置”作宾语，句子不通。"}], "explanations": {"找着": "正确：“找着”表示找的结果达到了，找到了学校的位置。", "喝": "搭配：“喝”的对象是饮品，不能说喝位置。", "烤": "搭配：“烤”用于食物，地图上的位置不能烤。", "穿": "搭配：“穿”不能带“位置”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "找着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我找着了一股很大的力气，一下子就搬起了箱子。", "explanation": "这里应该用〈使出〉。找着指找到想找的东西，力气不能被找到，要说使出很大的力气。"}, {"text": "我找着了一个愿望，想去旅行。", "explanation": "这里应该用〈许下〉。找着指找到想找的东西，愿望不能去找，要说许下一个愿望。"}, {"text": "我找着了一场大哭，心里好受多了。", "explanation": "这里应该用〈哭〉。找着指找到想找的东西，大哭是动作，不能被找到，要说哭了一场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找着", "is_correct": true, "explanation": "正确：“找着”表示找到了妈妈，所以孩子不哭了。"}, {"text": "失去", "is_correct": false, "explanation": "语义：“失去”是没有了，孩子失去妈妈就会哭，与“不哭了”矛盾。"}, {"text": "抛", "is_correct": false, "explanation": "搭配：“抛”的对象是物品，不能说抛妈妈。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物或水，不能说煮妈妈。"}], "explanations": {"找着": "正确：“找着”表示找到了妈妈，所以孩子不哭了。", "失去": "语义：“失去”是没有了，孩子失去妈妈就会哭，与“不哭了”矛盾。", "抛": "搭配：“抛”的对象是物品，不能说抛妈妈。", "煮": "搭配：“煮”的对象是食物或水，不能说煮妈妈。"}, "sentence_index": 6, "correct_answer": "找着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找着了一个大大的哈欠，就去睡觉了。", "explanation": "这里应该用〈打〉。找着指找到想找的东西，哈欠是动作，不能被找到，要说打了一个大大的哈欠。"}, {"text": "我找着了一场大雪，很开心。", "explanation": "这里应该用〈遇上〉。找着指找到想找的东西，大雪是天气现象，无法寻找，只能遇上。"}, {"text": "妈妈找着了一天的时光，很珍惜。", "explanation": "这里应该用〈度过〉。找着指找到具体可找的东西，时光是时间，不能寻找，要说度过一天的时光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在书架上一下子找着过那本小说。", "corrected_sentence": "我在书架上一下子找着了那本小说。", "error_description": "错误形式是“一下子找着过那本小说”，“一下子”描述刚发生的一次性动作，与表示曾经有过经历的“过”不相容。正确形式是“一下子找着了那本小说”，用“了”表示这次已经找到。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在超市刚刚找着过妹妹的鞋子。", "corrected_sentence": "他在超市刚刚找着了妹妹的鞋子。", "error_description": "错误形式是“刚刚找着过妹妹的鞋子”。“刚刚”说的是这一次的结果，不能用表示经历的“过”。正确形式是“找着了妹妹的鞋子”，用“了”表示已经找到。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94269, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "投降", "is_correct": true, "explanation": "投降：放弃抵抗，与“抵抗”的意思相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "与“抵抗”没有反义关系，“欢迎”是热情接待。"}, {"text": "观察", "is_correct": false, "explanation": "与“抵抗”没有反义关系，“观察”是仔细看。"}, {"text": "等待", "is_correct": false, "explanation": "与“抵抗”没有反义关系，“等待”是停下来等候。"}], "correct_answer": "投降", "explanations": {"投降": "投降：放弃抵抗，与“抵抗”的意思相反。", "欢迎": "与“抵抗”没有反义关系，“欢迎”是热情接待。", "观察": "与“抵抗”没有反义关系，“观察”是仔细看。", "等待": "与“抵抗”没有反义关系，“等待”是停下来等候。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
