INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94269, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抵抗是有人打你时不退，用力顶住。", "primary_collocate": null, "pronunciation": "dǐ kàng", "ipa": "ti²¹⁴ kʰɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "那个坏人打他，他用力抵抗，没有后退。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷想抢她的包，她拼命抵抗。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人打过来，弟弟没有跑，一直抵抗。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人抵抗三个坏人，受了伤。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人抓住她的手，她用力抵抗，大声叫。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学推我，我用力抵抗着，没有倒下。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大狗的进攻，小男孩不怕，勇敢地抵抗。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人又打又踢，她抵抗了很久。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方用力推他，他用肩膀抵抗，站得很稳。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不抵抗，他们会一直打你。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵抗了", "label": "完成体"}, {"form": "抵抗着", "label": "持续体"}, {"form": "抵抗过", "label": "经验体"}, {"form": "抵抗力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "被人攻击时不后退，用力顶住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89da991-ce23-4a2a-800d-16d17cb3d807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "抵抗：用力顶住对方的攻击，与“没有后退”呼应。"}, {"text": "撤退", "is_correct": false, "explanation": "语义：撤退就是向后退，与“没有后退”直接矛盾。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎是热情接待，与“打他”“用力”的对抗场面不符。"}, {"text": "承认", "is_correct": false, "explanation": "搭配：“用力”一般不修饰“承认”，“用力承认”不自然。"}], "explanations": {"抵抗": "抵抗：用力顶住对方的攻击，与“没有后退”呼应。", "撤退": "语义：撤退就是向后退，与“没有后退”直接矛盾。", "欢迎": "语义：欢迎是热情接待，与“打他”“用力”的对抗场面不符。", "承认": "搭配：“用力”一般不修饰“承认”，“用力承认”不自然。"}, "sentence_index": 0, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥能抵抗三吨的重量。", "explanation": "这里应该用〈承受〉。抵抗强调主动对抗外来的侵害，桥承受重量要用〈承受〉。"}, {"text": "他抵抗了朋友的邀请，没有去参加聚会。", "explanation": "这里应该用〈拒绝〉。抵抗针对外来的威胁或侵害，拒绝邀请要用〈拒绝〉。"}, {"text": "老师抵抗了学生的礼物，高兴地接过来了。", "explanation": "这里应该用〈接受〉。抵抗是用力顶住外来的威胁，不用于礼物，接受礼物要用〈接受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "抵抗：面对进攻用力顶住，与“勇敢”呼应。"}, {"text": "喜欢", "is_correct": false, "explanation": "体貌：“喜欢”是心理状态动词，不能用“勇敢地”描写动作。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑与“勇敢地”矛盾，与面对进攻时不退缩的叙述相反。"}, {"text": "规避", "is_correct": false, "explanation": "语域：“规避”是较书面的用语，与童话式叙述不协调，且与“不怕”的语气相反。"}], "explanations": {"抵抗": "抵抗：面对进攻用力顶住，与“勇敢”呼应。", "喜欢": "体貌：“喜欢”是心理状态动词，不能用“勇敢地”描写动作。", "逃跑": "语义：逃跑与“勇敢地”矛盾，与面对进攻时不退缩的叙述相反。", "规避": "语域：“规避”是较书面的用语，与童话式叙述不协调，且与“不怕”的语气相反。"}, "sentence_index": 6, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师很抵抗这篇文章。", "explanation": "这里应该用〈欣赏〉。抵抗是用力顶住外来的威胁，不用于对文章的喜爱，表示喜欢文章要用〈欣赏〉。"}, {"text": "大家热烈抵抗新来的同学。", "explanation": "这里应该用〈欢迎〉。抵抗针对威胁，迎接新同学要用〈欢迎〉。"}, {"text": "他很快抵抗了这个好消息。", "explanation": "这里应该用〈接受〉。好消息不是需要顶住的威胁，听到好消息要用〈接受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗抵抗了着，不肯进屋。", "corrected_sentence": "小狗抵抗着，不肯进屋。", "error_description": "“了”和“着”不能同时用在同一个动词后面，表示持续状态只用“着”，应说“抵抗着”，不能说“抵抗了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有抵抗住了，一下子倒下了。", "corrected_sentence": "他没有抵抗住，一下子倒下了。", "error_description": "“没有”否定已发生的动作时，动词后不再加“了”，应说“没有抵抗住”，不能说“没有抵抗住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
