INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力量对抗，不让对方得逞。", "primary_collocate": null, "pronunciation": "dǐ kàng", "ipa": "ti²¹⁴ kʰɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "人民团结起来，抵抗敌人的进攻。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队用枪抵抗外国的侵略。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们拿着工具，抵抗来抢东西的人。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的人抵抗了三天，敌人没有进来。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们坚持抵抗，不让敌人过河。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人攻进城里，守军还在抵抗。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小国的人民没有放弃，一直抵抗大国的控制。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用石头抵抗坏人，保护了村子。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人来了，大家把门关上，一起抵抗。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家很小，但是人民坚决抵抗侵略。", "target_word": "抵抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵抗了", "label": "完成体"}, {"form": "抵抗着", "label": "持续体"}, {"form": "抵抗过", "label": "经验体"}, {"form": "抵抗力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用力量对抗敌人或外来的侵害，不让对方得逞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89da991-ce23-4a2a-800d-16d17cb3d807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "抵抗：用力对抗敌人的进攻，与“团结起来”一致。"}, {"text": "投降", "is_correct": false, "explanation": "语义：投降是放弃抵抗，与“团结起来”的语境相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”一般不与“进攻”搭配，说“欢迎敌人的进攻”不成话。"}, {"text": "喜欢", "is_correct": false, "explanation": "体貌：“喜欢”表示心理状态，不能表示用力对抗的动作。"}], "explanations": {"抵抗": "抵抗：用力对抗敌人的进攻，与“团结起来”一致。", "投降": "语义：投降是放弃抵抗，与“团结起来”的语境相反。", "欢迎": "搭配：“欢迎”一般不与“进攻”搭配，说“欢迎敌人的进攻”不成话。", "喜欢": "体貌：“喜欢”表示心理状态，不能表示用力对抗的动作。"}, "sentence_index": 0, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们抵抗了远道而来的客人，热情地招待他们。", "explanation": "这里应该用〈迎接〉。抵抗是顶住外来的进攻，迎接远道而来的客人要用〈迎接〉。"}, {"text": "我们抵抗了这个好消息。", "explanation": "这里应该用〈接受〉。抵抗是对抗威胁，好消息不需要顶住，要用〈接受〉。"}, {"text": "老师抵抗了一个学生的问题，很认真地想了一会儿。", "explanation": "这里应该用〈回答〉。抵抗是对抗外来的进攻，回应学生的问题要用〈回答〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "抵抗：不接受外来的控制，与“没有放弃”“一直”一致。"}, {"text": "理睬", "is_correct": false, "explanation": "配价：“理睬”的对象是人或对方的话，不能直接带“控制”作宾语。"}, {"text": "反驳", "is_correct": false, "explanation": "配价：“反驳”的对象是观点或言论，“控制”不能被反驳。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”的对象是喜事或节日，不能与“大国的控制”搭配。"}], "explanations": {"抵抗": "抵抗：不接受外来的控制，与“没有放弃”“一直”一致。", "理睬": "配价：“理睬”的对象是人或对方的话，不能直接带“控制”作宾语。", "反驳": "配价：“反驳”的对象是观点或言论，“控制”不能被反驳。", "庆祝": "搭配：“庆祝”的对象是喜事或节日，不能与“大国的控制”搭配。"}, "sentence_index": 6, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很抵抗他的成绩，他的成绩总是很好。", "explanation": "这里应该用〈羡慕〉。抵抗是顶住外来威胁，不用于对别人成绩的态度，表示羡慕要用〈羡慕〉。"}, {"text": "人民努力抵抗家园，大家都很辛苦。", "explanation": "这里应该用〈建设〉。抵抗针对外来侵害，建设家园要用〈建设〉。"}, {"text": "大家热烈抵抗新来的邻居。", "explanation": "这里应该用〈欢迎〉。抵抗针对威胁，迎接新邻居要用〈欢迎〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们抵抗了过敌人的进攻，很有经验。", "corrected_sentence": "他们抵抗过敌人的进攻，很有经验。", "error_description": "“了”和“过”不能同时用在同一个动词后面。表示经历用“抵抗过”，不能说“抵抗了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌人攻势很猛，但他们终于抵抗了住。", "corrected_sentence": "敌人攻势很猛，但他们终于抵抗住了。", "error_description": "结果补语“住”应紧跟动词，“了”放在句末，应说“抵抗住了”，不能说“抵抗了住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
