INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "招是举起手向别人摇一摇，让他过来。", "primary_collocate": null, "pronunciation": "zhāo", "ipa": "ʈʂaʊ̯˥", "syllable_count": 1, "sentences": [{"text": "妈妈站在门口，向我招了招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他朝我招招手，让我快点过来。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师招着手说：“大家过来！”", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不敢过来，你对它招招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学在对面向我招了招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在河对岸招着手，叫我们过去。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朝他招了几下手，他没看见。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察朝司机招了招手，让他过来。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷对孙子招了招手，孙子跑过去了。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你招一招手，他就会过来的。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招招", "label": "重叠"}, {"form": "招了", "label": "体标"}, {"form": "招着", "label": "体标"}, {"form": "招手", "label": "复合"}], "register": "口语", "sense_fingerprint": "举手摇一摇，示意别人走过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。"}, {"text": "找", "is_correct": false, "explanation": "找（zhǎo，第三声）只改变声调，意思是寻找，不是示意人过来。"}, {"text": "抄", "is_correct": false, "explanation": "抄（chāo）声母由 zh 变为 ch，意思是抄写。"}, {"text": "烧", "is_correct": false, "explanation": "烧（shāo）声母由 zh 变为 sh，意思是燃烧。"}, {"text": "罩", "is_correct": false, "explanation": "罩（zhào，第四声）只改变声调，意思是遮盖。"}, {"text": "糟", "is_correct": false, "explanation": "糟（zāo）声母由 zh 变为 z，意思是糟糕。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。", "找": "找（zhǎo，第三声）只改变声调，意思是寻找，不是示意人过来。", "抄": "抄（chāo）声母由 zh 变为 ch，意思是抄写。", "烧": "烧（shāo）声母由 zh 变为 sh，意思是燃烧。", "罩": "罩（zhào，第四声）只改变声调，意思是遮盖。", "糟": "糟（zāo）声母由 zh 变为 z，意思是糟糕。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：这里的“招”表示用手势示意，“招了招手”是固定说法。"}, {"text": "挥", "is_correct": false, "explanation": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，要说“挥了挥手”。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”是出声叫人，“招手”是打手势，句中说的是手势，不是喊叫。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇”可以说“摇手”，但“摇了招手”不成词，与“招手”搭配不通。"}], "explanations": {"招": "正确：这里的“招”表示用手势示意，“招了招手”是固定说法。", "挥": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，要说“挥了挥手”。", "喊": "语义：“喊”是出声叫人，“招手”是打手势，句中说的是手势，不是喊叫。", "摇": "搭配：“摇”可以说“摇手”，但“摇了招手”不成词，与“招手”搭配不通。"}, "sentence_index": 0, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈朝我招了招手，让我别过去。", "explanation": "这里应该用〈摆〉。“摆手”表示让人走开，“招手”表示叫人过来，与“别过去”正好相反。"}, {"text": "他向我招手，表示拒绝。", "explanation": "这里应该用〈摇〉。“招手”表示叫人过来，表示拒绝要说“摇手”或“摆手”。"}, {"text": "老师朝我招了招头，让我过来。", "explanation": "这里应该用〈点〉。“招”是用手示意，不能用于头；用头示意要说“点头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。"}, {"text": "周", "is_correct": false, "explanation": "周（zhōu，第一声）只改变韵母，意思是星期或周围。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo）声母由 zh 变为 ch，意思是超过。"}, {"text": "照", "is_correct": false, "explanation": "照（zhào，第四声）只改变声调，意思是照射或拍照。"}, {"text": "遭", "is_correct": false, "explanation": "遭（zāo）声母由 zh 变为 z，意思是遭遇。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）在这里指举手摇一摇，示意人过来。", "周": "周（zhōu，第一声）只改变韵母，意思是星期或周围。", "超": "超（chāo）声母由 zh 变为 ch，意思是超过。", "照": "照（zhào，第四声）只改变声调，意思是照射或拍照。", "遭": "遭（zāo）声母由 zh 变为 z，意思是遭遇。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：这里的“招”表示用手势示意，“招了几下手”指打过几次手势。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹，句中说的是打手势，不是咬人或咬东西。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是用刀分开，“切了几下手”说的不是手势，句意不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”一般用于球或脚能碰到的东西，“踢了几下手”不成搭配。"}], "explanations": {"招": "正确：这里的“招”表示用手势示意，“招了几下手”指打过几次手势。", "咬": "语义：“咬”是用牙齿夹，句中说的是打手势，不是咬人或咬东西。", "切": "语义：“切”是用刀分开，“切了几下手”说的不是手势，句意不通。", "踢": "搭配：“踢”一般用于球或脚能碰到的东西，“踢了几下手”不成搭配。"}, "sentence_index": 6, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师用手招了招远处的操场，让我们去那里。", "explanation": "这里应该用〈指〉。“招”是对人打手势叫人过来，指地方要用“指”。"}, {"text": "他朝我招了招眼，示意我别说话。", "explanation": "这里应该用〈眨〉。这一义项的“招”只指用手示意，不能用于眼睛；用眼睛示意要说“眨眼”。"}, {"text": "他朝我招了招手，让我离开这里。", "explanation": "这里应该用〈摆〉。“招手”是叫人过来，让人离开要“摆手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务员把我们招了招手。", "corrected_sentence": "服务员朝我们招了招手。", "error_description": "错误：“把我们”，应为“朝我们”。“招手”是打手势叫人，对象要用“朝”引出，不能用“把”把对方当成处置对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在窗口招了着手，叫我们进屋。", "corrected_sentence": "她在窗口招着手，叫我们进屋。", "error_description": "错误：“招了着手”，应为“招着手”。“了”表示完成，“着”表示持续，两者不能叠用；这里是持续的动作，只用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手势叫人来；招引。", "primary_collocate": null, "pronunciation": "zhāo", "ipa": "ʈʂaʊ̯˥", "syllable_count": 1, "sentences": [{"text": "老师在门口招了招手，我就走过去了。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路边招了一辆出租车。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甜甜的花香招来了很多蜜蜂。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户一直开着，会招蚊子进来。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的小吃摊招来了很多游客。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着向远处的朋友招招手。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里亮着的灯招来了不少小虫子。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别乱说，小心招来麻烦。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板朝服务员招了招手，要结账。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的香味招了不少客人。", "target_word": "招", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招招", "label": "重叠"}, {"form": "招了", "label": "体标"}, {"form": "招着", "label": "体标"}, {"form": "招来", "label": "复合"}, {"form": "招手", "label": "复合"}], "register": "口语", "sense_fingerprint": "用手势叫人过来，或招引、引来人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）指用手势叫人过来，或招引。"}, {"text": "找", "is_correct": false, "explanation": "找（zhǎo，第三声）与招只有声调不同，意思是寻找，不是叫人过来。"}, {"text": "照", "is_correct": false, "explanation": "照（zhào，第四声）与招只有声调不同，意思是照射或拍照。"}, {"text": "抄", "is_correct": false, "explanation": "抄（chāo）与招的声母不同：zh 换成 ch，意思是抄写。"}, {"text": "烧", "is_correct": false, "explanation": "烧（shāo）与招的声母不同：zh 换成 sh，意思是燃烧。"}, {"text": "糟", "is_correct": false, "explanation": "糟（zāo）与招的声母不同：zh 换成 z，意思是坏、乱。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）指用手势叫人过来，或招引。", "找": "找（zhǎo，第三声）与招只有声调不同，意思是寻找，不是叫人过来。", "照": "照（zhào，第四声）与招只有声调不同，意思是照射或拍照。", "抄": "抄（chāo）与招的声母不同：zh 换成 ch，意思是抄写。", "烧": "烧（shāo）与招的声母不同：zh 换成 sh，意思是燃烧。", "糟": "糟（zāo）与招的声母不同：zh 换成 z，意思是坏、乱。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招了招手”是固定说法，这里的“招”表示用手势叫人，只有“招”能填入空格。"}, {"text": "挥", "is_correct": false, "explanation": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，句中不能这样说。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”是大声叫，“招手”是打手势，句中说的是手势，不是喊叫。"}, {"text": "指", "is_correct": false, "explanation": "语义：“指”是用手指点，与“招手”不同，“指了招手”说不通。"}], "explanations": {"招": "正确：“招了招手”是固定说法，这里的“招”表示用手势叫人，只有“招”能填入空格。", "挥": "搭配：“挥”后面已有“招手”，“挥了招手”不成词，句中不能这样说。", "喊": "语义：“喊”是大声叫，“招手”是打手势，句中说的是手势，不是喊叫。", "指": "语义：“指”是用手指点，与“招手”不同，“指了招手”说不通。"}, "sentence_index": 0, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他朝我招了招手，让我快点走开。", "explanation": "这里应该用〈摆〉。“摆手”表示让人走开，“招手”表示叫人过来，与“让我快点走开”正好相反。"}, {"text": "老师在教室里招了我的名字。", "explanation": "这里应该用〈叫〉。“招”用于招手或招引人、虫、麻烦，不能用于呼唤名字；叫名字要用“叫”。"}, {"text": "老师今天招了我们的作业本，让大家交上来。", "explanation": "这里应该用〈收〉。“招”指招来人、虫或用手叫人，不能用于收作业；收作业要说“收”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招”（zhāo，第一声）在这里指招引，使人或虫子来到。"}, {"text": "周", "is_correct": false, "explanation": "周（zhōu，第一声）只改变韵母，意思是星期或周围。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo）与招的声母不同：zh 换成 ch，意思是超过。"}, {"text": "罩", "is_correct": false, "explanation": "罩（zhào，第四声）与招只有声调不同，意思是遮盖。"}, {"text": "遭", "is_correct": false, "explanation": "遭（zāo）与招的声母不同：zh 换成 z，意思是遭遇。"}], "explanations": {"招": "正确：“招”（zhāo，第一声）在这里指招引，使人或虫子来到。", "周": "周（zhōu，第一声）只改变韵母，意思是星期或周围。", "超": "超（chāo）与招的声母不同：zh 换成 ch，意思是超过。", "罩": "罩（zhào，第四声）与招只有声调不同，意思是遮盖。", "遭": "遭（zāo）与招的声母不同：zh 换成 z，意思是遭遇。"}, "sentence_index": null, "correct_answer": "招"}, "level_3": {"options": [{"text": "招", "is_correct": true, "explanation": "正确：“招来”表示引来，灯光引来小虫子，只有“招”符合句意。"}, {"text": "驱", "is_correct": false, "explanation": "语义：“驱”是驱赶，与“灯招来虫子”的引来意思相反。"}, {"text": "逃", "is_correct": false, "explanation": "配价：“逃”是不及物动词，后面不能直接带“小虫子”作宾语。"}, {"text": "吓", "is_correct": false, "explanation": "语义：“吓”是使人害怕，灯光不会把小虫子吓来，句意不通。"}], "explanations": {"招": "正确：“招来”表示引来，灯光引来小虫子，只有“招”符合句意。", "驱": "语义：“驱”是驱赶，与“灯招来虫子”的引来意思相反。", "逃": "配价：“逃”是不及物动词，后面不能直接带“小虫子”作宾语。", "吓": "语义：“吓”是使人害怕，灯光不会把小虫子吓来，句意不通。"}, "sentence_index": 6, "correct_answer": "招"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我招了一杯茶，请王老师坐下。", "explanation": "这里应该用〈倒〉。“招”不能用于倒茶；倒茶要说“倒”。"}, {"text": "他朝我招了招头，表示不同意。", "explanation": "这里应该用〈摇〉。“摇头”表示否定或不同意，“招”只用于手，不能用于头。"}, {"text": "他在远处招了一把伞，让我们快点过来。", "explanation": "这里应该用〈举〉。“招”指用手势叫人或招引，不能用于伞；举起伞要说“举”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天晚上开着灯，会招去很多蚊子。", "corrected_sentence": "夏天晚上开着灯，会招来很多蚊子。", "error_description": "错误：“招去”，应为“招来”。“来”表示向说话人或灯所在的地方靠近，蚊子是飞过来的，不能用“去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在外面乱讲话，结果招走了一大堆麻烦。", "corrected_sentence": "他在外面乱讲话，结果招来了一大堆麻烦。", "error_description": "错误：“招走”，应为“招来”。“招”是把人或事物引到身边，要用“来”，不能用“走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
