INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94273, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "招生是学校请新的学生来读书。", "primary_collocate": null, "pronunciation": "zhāo shēng", "ipa": "ʈʂɑʊ˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这所小学每年九月招生。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今年计划招生五百人。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校什么时候开始招生？", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那所中学今年不招生。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到夏天，各个大学都忙着招生。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为了招生，做了很多广告。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所幼儿园九月招生，你可以去报名。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校网站上说，下个月开始招生。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校明年不招生了。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学校下周开始招生，让家长准备材料。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招生简章", "label": "复合"}, {"form": "招生计划", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校请新学生来读书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招生", "is_correct": true, "explanation": "正确答案。学校每年九月招收新学生，符合句意。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：“退休”的主语是人，学校不能说退休。"}, {"text": "调查", "is_correct": false, "explanation": "语义：“调查”是查问情况，与九月的入学事务无关。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语是人，学校不能结婚。"}], "explanations": {"招生": "正确答案。学校每年九月招收新学生，符合句意。", "退休": "搭配：“退休”的主语是人，学校不能说退休。", "调查": "语义：“调查”是查问情况，与九月的入学事务无关。", "结婚": "搭配：“结婚”的主语是人，学校不能结婚。"}, "sentence_index": 0, "correct_answer": "招生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂今年在招生，要招五十个工人。", "explanation": "这里应该用〈招工〉。招生只用于学校、培训班招收学生，工厂招人要说“招工”。"}, {"text": "这个小店招生了很多顾客。", "explanation": "这里的“招生”指学校或培训班招收学生，不能用来说店铺吸引顾客。"}, {"text": "学校今年招生了五个老师。", "explanation": "这里应该用〈招聘〉。招生只招收学生，招聘老师要说“招聘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招生", "is_correct": true, "explanation": "正确答案。幼儿园九月招生，家长可以去报名，符合句意。"}, {"text": "结业", "is_correct": false, "explanation": "语义：“结业”指课程结束，与九月报名的句意不合。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：“搬家”指迁居，不能说幼儿园九月搬家。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”的主语是人，幼儿园不能说生病。"}], "explanations": {"招生": "正确答案。幼儿园九月招生，家长可以去报名，符合句意。", "结业": "语义：“结业”指课程结束，与九月报名的句意不合。", "搬家": "语义：“搬家”指迁居，不能说幼儿园九月搬家。", "生病": "搭配：“生病”的主语是人，幼儿园不能说生病。"}, "sentence_index": 6, "correct_answer": "招生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在家招生朋友，很热情。", "explanation": "这里应该用〈招待〉。招待用于接待客人，招生只指学校招收学生。"}, {"text": "她招生了一个孩子做女儿。", "explanation": "这里应该用〈收养〉。招生只用于学校招收学生，不能用来说收养孩子。"}, {"text": "学校招生了一条小狗。", "explanation": "招生的对象是学生，不能用来说招收动物，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校昨天招生着五百人。", "corrected_sentence": "学校昨天招生了五百人。", "error_description": "错误形式：“招生”后面用了“着”，说成“学校昨天招生着五百人”。正确形式：“学校昨天招生了五百人”。“昨天”指向一个已完成的具体时间，动作已经结束，应用“了”；“着”表示持续的状态，不能用于已完成的具体事件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所幼儿园去年九月招生着。", "corrected_sentence": "这所幼儿园去年九月招生了。", "error_description": "错误形式：“招生”后面用了“着”，说成“去年九月招生着”。正确形式：“去年九月招生了”。“去年九月”是已经过去的具体时间，动作已经完成，应该用“了”；“着”表示持续，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
