INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94274, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学校或培训班招收新学生。", "primary_collocate": null, "pronunciation": "zhāo shēng", "ipa": "ʈʂɑʊ˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这个英语培训班一月份开始招生。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈班暑假招生，现在可以报名。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书法班下个月招生，价格不贵。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家培训学校常年招生。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个游泳班夏天招生，价格不贵。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美术班招生的时候，老师会免费试课。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "培训班今天正式招生，来了很多家长。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校招生的消息已经贴在门口了。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所职业学校全年招生，随时可以报名。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了招生，培训班送了一本练习册。", "target_word": "招生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招生简章", "label": "复合"}, {"form": "招生计划", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校或培训班招收新学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招生", "is_correct": true, "explanation": "正确答案。英语培训班一月份开始招收新学员，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语是人，培训班不能说结婚。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与一月份开始的培训无关。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”的主语是人，培训班不能说生病。"}], "explanations": {"招生": "正确答案。英语培训班一月份开始招收新学员，符合句意。", "结婚": "搭配：“结婚”的主语是人，培训班不能说结婚。", "退休": "语义：“退休”指离开工作岗位，与一月份开始的培训无关。", "生病": "搭配：“生病”的主语是人，培训班不能说生病。"}, "sentence_index": 0, "correct_answer": "招生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅招生了五个服务员。", "explanation": "这里应该用〈雇用〉。招生只用于学校、培训班招收学生，餐厅雇人不能说“招生”。"}, {"text": "这家商场搞活动，招生了很多顾客。", "explanation": "这里的“招生”指招收学生，不能用来说商场吸引顾客。"}, {"text": "学校招生了十名志愿者。", "explanation": "这里应该用〈招募〉。招生指招收学生，招募志愿者要说“招募”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招生", "is_correct": true, "explanation": "正确答案。培训班今天正式招生，家长来了很多，符合句意。"}, {"text": "停电", "is_correct": false, "explanation": "语义：“停电”指没有电，与培训班今天正式招生的句意不合。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：“搬家”指迁居，与正式开始的培训无关。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”的主语是人，培训班不能说生病。"}], "explanations": {"招生": "正确答案。培训班今天正式招生，家长来了很多，符合句意。", "停电": "语义：“停电”指没有电，与培训班今天正式招生的句意不合。", "搬家": "语义：“搬家”指迁居，与正式开始的培训无关。", "生病": "搭配：“生病”的主语是人，培训班不能说生病。"}, "sentence_index": 6, "correct_answer": "招生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他招生了远道而来的客人。", "explanation": "这里应该用〈接待〉。招生只用于招收学生，不能用来说接待客人。"}, {"text": "培训班招生了一台电脑。", "explanation": "招生的对象是学生，不能用来说招收电脑这样的物品，这里用法不对。"}, {"text": "我们公司正在招生员工。", "explanation": "这里应该用〈招聘〉。招生只指学校招收学生，公司招人要说“招聘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家画室今年春天已经招生着。", "corrected_sentence": "这家画室今年春天已经招生了。", "error_description": "错误形式：“已经”后面用了“着”，说成“已经招生着”。正确形式：“已经招生了”。“已经”表示动作已经完成，要与“了”搭配，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个培训班刚刚开始把招生。", "corrected_sentence": "这个培训班刚刚开始招生。", "error_description": "错误形式：“把”字句中“把招生”后面缺少动词，句子不成立。正确形式：“开始招生”。“开始”后直接接动词“招生”，不需要“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拿起", "is_correct": true, "explanation": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”指快速移动，与“放下”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "无关：“看”指用眼睛观察，与“放下”不构成反义。"}, {"text": "洗", "is_correct": false, "explanation": "无关：“洗”指用水去除污垢，与“放下”的动作没有反义关系。"}], "correct_answer": "拿起", "explanations": {"拿起": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。", "跑": "无关：“跑”指快速移动，与“放下”没有反义关系。", "看": "无关：“看”指用眼睛观察，与“放下”不构成反义。", "洗": "无关：“洗”指用水去除污垢，与“放下”的动作没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拿起", "is_correct": true, "explanation": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。"}, {"text": "唱", "is_correct": false, "explanation": "无关：“唱”指发出歌声，与“放下”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "无关：“写”指写字，与“放下”不构成反义。"}, {"text": "睡", "is_correct": false, "explanation": "无关：“睡”指闭眼休息，与“放下”没有对立关系。"}], "correct_answer": "拿起", "explanations": {"拿起": "反义：“拿起”是把东西握到手中，与“放下”把东西放到别处方向相反。", "唱": "无关：“唱”指发出歌声，与“放下”没有反义关系。", "写": "无关：“写”指写字，与“放下”不构成反义。", "睡": "无关：“睡”指闭眼休息，与“放下”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放下是把拿着的东西放到别的地方。", "primary_collocate": null, "pronunciation": "fàng xià", "ipa": "fɑŋ˥˩ ɕiɑ˥˩", "syllable_count": 2, "sentences": [{"text": "他把书包放下，坐到了椅子上。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把杯子放下，别拿着了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈放下菜篮，去开门。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下筷子，说自己吃饱了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先把东西放下，再慢慢说。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟放下手里的玩具，跑出去玩。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师放下粉笔，转身看着大家。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手机放下，认真听课。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放下了行李，坐在床边休息。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下报纸，喝了一口茶。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放下了", "label": "体标"}, {"form": "放不下", "label": "否定可能式"}, {"form": "放得下", "label": "可能式"}], "register": "中性", "sense_fingerprint": "把手里拿着的东西放到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把拿着的书包放到别处，与“坐到了椅子上”前后衔接自然。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉、抛出，书包被扔掉就不能再带着坐下，与“放下”的放置义不同。"}, {"text": "举起", "is_correct": false, "explanation": "语义：“举起”是把东西向上抬着，书包被举着就很难再“坐到椅子上”，两个动作互相冲突。"}, {"text": "放进", "is_correct": false, "explanation": "配价：“放进”后要说明放进哪里，“把书包放进”缺少处所，句子不完整。"}], "explanations": {"放下": "放下：把拿着的书包放到别处，与“坐到了椅子上”前后衔接自然。", "扔": "语义：“扔”是丢掉、抛出，书包被扔掉就不能再带着坐下，与“放下”的放置义不同。", "举起": "语义：“举起”是把东西向上抬着，书包被举着就很难再“坐到椅子上”，两个动作互相冲突。", "放进": "配价：“放进”后要说明放进哪里，“把书包放进”缺少处所，句子不完整。"}, "sentence_index": 0, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部老电影在城里放下了三天，没有人去看。", "explanation": "这里应该用〈放映〉。放下指把拿着的东西放到别处，电影在影院播出要说放映。"}, {"text": "他放下门，走进了屋里。", "explanation": "这里应该用〈关上〉。放下指把拿着的东西放到别处，门要说关上。"}, {"text": "这家公司下个月要放下一款新手机。", "explanation": "这里应该用〈推出〉。放下指把拿着的东西放到别处，新产品上市要说推出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把手里的粉笔放到别处，与“转身看着大家”前后衔接自然。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，老师手里拿着粉笔，不会用“咬”来描述把粉笔放下的动作。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”多用于衣服、纸张等可以折叠的东西，粉笔不能叠。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”要说挂在哪里，“老师挂粉笔”缺少处所，句子不完整。"}], "explanations": {"放下": "放下：把手里的粉笔放到别处，与“转身看着大家”前后衔接自然。", "咬": "语义：“咬”指用牙齿夹住，老师手里拿着粉笔，不会用“咬”来描述把粉笔放下的动作。", "叠": "搭配：“叠”多用于衣服、纸张等可以折叠的东西，粉笔不能叠。", "挂": "配价：“挂”要说挂在哪里，“老师挂粉笔”缺少处所，句子不完整。"}, "sentence_index": 6, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放下一句狠话，转身就走了。", "explanation": "这里应该用〈撂下〉。放下指把具体的东西放到别处；“狠话”不能被放下，说完话就走要说撂下一句话。"}, {"text": "门卫检查了证件，就放下了那辆车，让它进了大门。", "explanation": "这里应该用〈放行〉。放下指把拿着的东西放到别处，允许车辆通过要说放行。"}, {"text": "她一句话也没说，只是放下了眼泪。", "explanation": "这里应该用〈流下〉。“放下”的对象是能拿在手里、放到别处的具体物品，眼泪要说流下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我放下手里的那本钥匙，去开了门。", "corrected_sentence": "我放下手里的那把钥匙，去开了门。", "error_description": "量词错误：“本”用于书册，钥匙应用“把”计量；应说“那把钥匙”。“放下”本身没有错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把伞放下着，进屋来吧。", "corrected_sentence": "请把伞放下，进屋来吧。", "error_description": "“放下”后面不能再加“着”；“放下”已是完成的结果，应直接说“请把伞放下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
