INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把手里拿着的东西放在某处；卸下。", "primary_collocate": null, "pronunciation": "fàng xià", "ipa": "fɑŋ˥˩ ɕiɑ˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸放下背包，擦了擦头上的汗。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们放下肩上的箱子，休息一会儿。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了家门口，我放下了手里的袋子。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶放下手里的针线，站起来迎接我们。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把重重的行李放下吧，我们到了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下手里的电话，走出了办公室。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明放下书包，先去洗手。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机放下乘客的行李，就开车走了。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人放下担子，坐在路边喘气。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累了就放下手里的东西，歇一歇。", "target_word": "放下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放下了", "label": "体标"}, {"form": "放不下", "label": "否定可能式"}, {"form": "放得下", "label": "可能式"}], "register": "中性", "sense_fingerprint": "把手里拿着或身上背着的东西放在某处，卸下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把背着或拿着的背包放到别处，与“擦了擦头上的汗”前后衔接。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是用力掷落，与“擦了擦头上的汗”的平静动作不协调。"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”多用于推车、推门等，“推背包”不是常见搭配。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”是用针线连起来，“爸爸缝背包”与“擦了擦头上的汗”毫不衔接。"}], "explanations": {"放下": "放下：把背着或拿着的背包放到别处，与“擦了擦头上的汗”前后衔接。", "摔": "语义：“摔”是用力掷落，与“擦了擦头上的汗”的平静动作不协调。", "推": "搭配：“推”多用于推车、推门等，“推背包”不是常见搭配。", "缝": "语义：“缝”是用针线连起来，“爸爸缝背包”与“擦了擦头上的汗”毫不衔接。"}, "sentence_index": 0, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她放下了眼泪，什么也没说。", "explanation": "这里应该用〈流下〉。“放下”的对象是能拿在手里、放到别处的具体物品，眼泪不能这样处理，要说流下眼泪。"}, {"text": "剧团下个月要放下一场新戏。", "explanation": "这里应该用〈上演〉。放下指把拿着的东西放到别处，新戏开演要说上演。"}, {"text": "妈妈每天早上开车放下我去学校。", "explanation": "这里应该用〈送〉。放下指把拿着的东西放到别处，开车带人到学校要说送我去学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放下", "is_correct": true, "explanation": "放下：把背着的书包卸下放好，再“先去洗手”，前后衔接自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是把东西放进嘴里，与“小明放下书包，先去洗手”的意思完全不符。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”多用于衣服、纸张，“叠书包”不是常见搭配。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指把物体拆开，“拆书包”不是正常说法，与“先去洗手”也不衔接。"}], "explanations": {"放下": "放下：把背着的书包卸下放好，再“先去洗手”，前后衔接自然。", "吃": "语义：“吃”是把东西放进嘴里，与“小明放下书包，先去洗手”的意思完全不符。", "叠": "搭配：“叠”多用于衣服、纸张，“叠书包”不是常见搭配。", "拆": "搭配：“拆”指把物体拆开，“拆书包”不是正常说法，与“先去洗手”也不衔接。"}, "sentence_index": 6, "correct_answer": "放下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放下一句话，头也不回地走了。", "explanation": "这里应该用〈撂下〉。撂下一句话指说完就离开，“放下”只用于把具体的东西放到别处，不能搭配“话”。"}, {"text": "这场比赛被放下了一周。", "explanation": "这里应该用〈推迟〉。放下指把拿着的东西放到别处，比赛时间往后移要说推迟。"}, {"text": "他放下胆子，走上了舞台。", "explanation": "这里应该用〈放开〉。放下指把拿着的东西放到别处，“胆子”要说放开胆子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把背包放下在地上，擦了擦汗。", "corrected_sentence": "他把背包放在地上，擦了擦汗。", "error_description": "“放下”后不能直接接“在＋处所”；要说明放的位置应说“放在地上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这本背包放下，先歇一会儿。", "corrected_sentence": "请把这个背包放下，先歇一会儿。", "error_description": "量词错误：“本”用于书册，背包不能用“本”计量；应说“这个背包”。“放下”本身没有错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
