INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94277, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时机是做一件事最合适的那个时候。", "primary_collocate": null, "pronunciation": "shí jī", "ipa": "ʂɻ̩˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "现在是说这件事的好时机。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等一个好时机再告诉她。", "target_word": "时机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买东西要选对时机。", "target_word": "时机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在最好的时机卖了房子。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你来的时机真好，我们刚好缺人。", "target_word": "时机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开口之前，先看看时机对不对。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话很会选时机，从不让人难堪。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事要有耐心，时机没到不要急。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我找了很久，终于等到了时机。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司在合适的时机上了市。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "時機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做一件事最合适的那个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94277, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时机", "is_correct": true, "explanation": "正确答案。时机：做一件事最合适的那个时候。"}, {"text": "实际", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，声母韵母相同，意思是真实的情况。"}, {"text": "时期", "is_correct": false, "explanation": "qī（第一声）与 jī（第一声）声母不同（q/j），意思是一段时间。"}, {"text": "死机", "is_correct": false, "explanation": "sǐ（第三声）与 shí（第二声）声母与声调都不同（s/sh），意思是电脑等设备失去响应。"}], "explanations": {"时机": "正确答案。时机：做一件事最合适的那个时候。", "实际": "jì（第四声）与 jī（第一声）声调不同，声母韵母相同，意思是真实的情况。", "时期": "qī（第一声）与 jī（第一声）声母不同（q/j），意思是一段时间。", "死机": "sǐ（第三声）与 shí（第二声）声母与声调都不同（s/sh），意思是电脑等设备失去响应。"}, "sentence_index": null, "correct_answer": "时机"}, "level_3": {"options": [{"text": "时机", "is_correct": true, "explanation": "正确：“好时机”指做这件事最合适的时候，与“这件事的好”搭配。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期指学校的学习阶段，与“说这件事”无关。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“说这件事的好”一般修饰时机，不说“好钥匙”。"}, {"text": "考卷", "is_correct": false, "explanation": "语义：考卷是考试用的纸，与“说这件事”无关。"}], "explanations": {"时机": "正确：“好时机”指做这件事最合适的时候，与“这件事的好”搭配。", "学期": "语义：学期指学校的学习阶段，与“说这件事”无关。", "钥匙": "搭配：“说这件事的好”一般修饰时机，不说“好钥匙”。", "考卷": "语义：考卷是考试用的纸，与“说这件事”无关。"}, "sentence_index": 0, "correct_answer": "时机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用了很长时机才卖掉房子。", "explanation": "这里应该用〈时间〉。时机指做事最合适的那一刻，不能用来表示时间的长短。"}, {"text": "会议时机请大家保持安静。", "explanation": "这里应该用〈期间〉。时机不表示一段时间的范围，会议的整个过程要用〈期间〉。"}, {"text": "他的时机是一米八。", "explanation": "这里应该用〈身高〉。时机是做事的有利时刻，不能用来描述身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时机", "is_correct": true, "explanation": "正确：“会选时机”指挑选合适的时候，与“选”搭配。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“选”可以带时机、词语等宾语，“空气”不能被挑选成说话的时机。"}, {"text": "天色", "is_correct": false, "explanation": "配价：“会选天色”不成立，天色不能被选择。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“选鞋子”与“说话”无关，句中的“选”指挑选说话的时机。"}], "explanations": {"时机": "正确：“会选时机”指挑选合适的时候，与“选”搭配。", "空气": "配价：“选”可以带时机、词语等宾语，“空气”不能被挑选成说话的时机。", "天色": "配价：“会选天色”不成立，天色不能被选择。", "鞋子": "语义：“选鞋子”与“说话”无关，句中的“选”指挑选说话的时机。"}, "sentence_index": 6, "correct_answer": "时机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经三十岁了，时机不小了。", "explanation": "这里应该用〈年龄〉。时机是做事的有利时刻，不能用来说人的岁数大小。"}, {"text": "那个时机的人很朴素。", "explanation": "这里应该用〈时代〉。时机指具体的合适时刻，不能指较长的历史阶段。"}, {"text": "我的时机是五十公斤。", "explanation": "这里应该用〈体重〉。时机不能用来表示体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们选了一只好时机开新店。", "corrected_sentence": "他们选了一个好时机开新店。", "error_description": "量词错误：“时机”应说“一个好时机”，不能说“一只好时机”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是大家都认可好时机。", "corrected_sentence": "这是大家都认可的好时机。", "error_description": "定语缺少“的”：“大家都认可的好时机”中，“大家都认可”修饰“好时机”，需加“的”，不能省略成“大家都认可好时机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
