INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对做某事最有利的时间和机会。", "primary_collocate": null, "pronunciation": "shí jī", "ipa": "ʂɻ̩˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "现在不是买房的好时机。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在合适的时机说出了想法。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做生意要看准时机。", "target_word": "时机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "时机还没到，我们再等等。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她抓住时机，换了新工作。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时机很好，快点告诉他吧。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直等着好时机，想开自己的店。", "target_word": "时机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "错过这次时机，就很难再有机会了。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们得把时机选对，再开始做。", "target_word": "时机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有等到时机，就急着出国了。", "target_word": "时机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "時機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对做某事有利的时间和机会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94278, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时机", "is_correct": true, "explanation": "正确答案。时机：对做某事最有利的时间和机会。"}, {"text": "实际", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，声母韵母相同，意思是真实的情况。"}, {"text": "时期", "is_correct": false, "explanation": "qī（第一声）与 jī（第一声）声母不同（q/j），意思是一段时间。"}, {"text": "死机", "is_correct": false, "explanation": "sǐ（第三声）与 shí（第二声）声母与声调都不同（s/sh），意思是电脑等设备失去响应。"}], "explanations": {"时机": "正确答案。时机：对做某事最有利的时间和机会。", "实际": "jì（第四声）与 jī（第一声）声调不同，声母韵母相同，意思是真实的情况。", "时期": "qī（第一声）与 jī（第一声）声母不同（q/j），意思是一段时间。", "死机": "sǐ（第三声）与 shí（第二声）声母与声调都不同（s/sh），意思是电脑等设备失去响应。"}, "sentence_index": null, "correct_answer": "时机"}, "level_3": {"options": [{"text": "时机", "is_correct": true, "explanation": "正确：“好时机”指对买房有利的时机，与“买房的好”搭配。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期指学校的学习阶段，与买房无关。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“买房的好”一般修饰时机、价格、地段，不说“好钥匙”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学生用的书，与买房无关。"}], "explanations": {"时机": "正确：“好时机”指对买房有利的时机，与“买房的好”搭配。", "学期": "语义：学期指学校的学习阶段，与买房无关。", "钥匙": "搭配：“买房的好”一般修饰时机、价格、地段，不说“好钥匙”。", "课本": "语义：课本是学生用的书，与买房无关。"}, "sentence_index": 0, "correct_answer": "时机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在这里住了很长时机。", "explanation": "这里应该用〈时间〉。时机指做事最合适的那一刻，不能用来表示时间的长短。"}, {"text": "下雨的时机我们在家看书。", "explanation": "这里应该用〈时候〉。时机强调对做事有利的时刻，描述普通的时间点要用〈时候〉。"}, {"text": "借书的时机是三十天。", "explanation": "这里应该用〈期限〉。时机不指一段固定的期限，不能用来规定借书的天数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时机", "is_correct": true, "explanation": "正确：“等着好时机”指等待对做事有利的时机，与“等着”搭配。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“等”要求的对象是时机、机会这类东西，不能等“空气”。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“等着鞋子”与“想开自己的店”不相关，等的应是做事的时机。"}, {"text": "方向", "is_correct": false, "explanation": "配价：“等着”要求等待的对象是时机，“方向”不能被等待。"}], "explanations": {"时机": "正确：“等着好时机”指等待对做事有利的时机，与“等着”搭配。", "空气": "配价：“等”要求的对象是时机、机会这类东西，不能等“空气”。", "鞋子": "语义：“等着鞋子”与“想开自己的店”不相关，等的应是做事的时机。", "方向": "配价：“等着”要求等待的对象是时机，“方向”不能被等待。"}, "sentence_index": 6, "correct_answer": "时机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经三十岁了，时机不小了。", "explanation": "这里应该用〈年龄〉。时机是做事的有利时刻，不能用来说人的岁数大小。"}, {"text": "那个时机的人很朴素。", "explanation": "这里应该用〈时代〉。时机指具体的合适时刻，不能指较长的历史阶段。"}, {"text": "他的时机有十年了。", "explanation": "这里应该用〈工龄〉。时机不表示工作的年限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要抓住这只好时机，马上行动。", "corrected_sentence": "我们要抓住这次好时机，马上行动。", "error_description": "量词错误：“时机”一般用“次”或“个”，应说“这次好时机”，不能说“这只好时机”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们等到了大家都认可时机。", "corrected_sentence": "他们等到了大家都认可的时机。", "error_description": "定语缺少“的”：“大家都认可的时机”中，“大家都认可”修饰“时机”，需加“的”，不能省略成“大家都认可时机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利", "is_correct": true, "explanation": "“不利”与“有利”互为反义，指对人或事没有好处。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌美，与“有利”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”的反义是吵闹，与“有利”的好处义无关。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描述态度，与“有利”没有反义关系。"}], "correct_answer": "不利", "explanations": {"不利": "“不利”与“有利”互为反义，指对人或事没有好处。", "漂亮": "“漂亮”形容外貌美，与“有利”没有反义关系。", "安静": "“安静”的反义是吵闹，与“有利”的好处义无关。", "认真": "“认真”描述态度，与“有利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利", "is_correct": true, "explanation": "“不利”与“有利”互为反义，指对人或事没有好处。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁程度，与“有利”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“有利”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情，与“有利”没有反义关系。"}], "correct_answer": "不利", "explanations": {"不利": "“不利”与“有利”互为反义，指对人或事没有好处。", "干净": "“干净”形容清洁程度，与“有利”没有反义关系。", "聪明": "“聪明”形容人的智力，与“有利”没有反义关系。", "高兴": "“高兴”形容心情，与“有利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有利是对人有好处。", "primary_collocate": null, "pronunciation": "yǒu lì", "ipa": "joʊ˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "早睡早起对身体很有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个天气对农民有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动对健康有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做对大家都有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语对你找工作有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安静的环境对学习有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同对我们很有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃早饭对孩子有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格下降对买房的人有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水对皮肤有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利于", "label": "复合"}], "register": "中性", "sense_fingerprint": "对人或事有好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '980ebab6-654b-45aa-acc6-731014f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示对人或事有好处，与“早睡早起对身体”的语境相符。"}, {"text": "有名", "is_correct": false, "explanation": "语义：“有名”说名气大，与“对身体”的好处无关，句意不通。"}, {"text": "有趣", "is_correct": false, "explanation": "搭配：“有趣”形容事物的趣味，不能用来修饰“身体”。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌，不能说“对身体很好看”。"}], "explanations": {"有利": "“有利”表示对人或事有好处，与“早睡早起对身体”的语境相符。", "有名": "语义：“有名”说名气大，与“对身体”的好处无关，句意不通。", "有趣": "搭配：“有趣”形容事物的趣味，不能用来修饰“身体”。", "好看": "搭配：“好看”形容外貌，不能说“对身体很好看”。"}, "sentence_index": 0, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很有利，我坐了一下午都不累。", "explanation": "这里应该用〈舒适〉。有利表示对人或事有好处，说椅子坐着是否舒适应用“舒适”，不能用“有利”。"}, {"text": "听到这个消息，他很有利。", "explanation": "这里应该用〈高兴〉。有利用于事情对某方有好处，不用来描述人的心情。"}, {"text": "这件衣服很有利，穿着不大不小。", "explanation": "这里应该用〈合身〉。有利说的是对人或事有好处，衣服大小合适应说“合身”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示对人有好处，与“这份合同对我们”的语境相符。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌，合同不能用来形容“好看”。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“快乐”形容人的心情，合同不能快乐，句意不通。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”形容外观排列，与“对我们很”的好处义不相容。"}], "explanations": {"有利": "“有利”表示对人有好处，与“这份合同对我们”的语境相符。", "好看": "搭配：“好看”形容外貌，合同不能用来形容“好看”。", "快乐": "语义：“快乐”形容人的心情，合同不能快乐，句意不通。", "整齐": "语义：“整齐”形容外观排列，与“对我们很”的好处义不相容。"}, "sentence_index": 6, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有利地跑完了全程。", "explanation": "这里应该用〈快〉。有利表示对人或事有好处，修饰跑步的速度应说“快”，不能用“有利”。"}, {"text": "这首歌很有利，我每天都听。", "explanation": "这里应该用〈好听〉。有利用于事情对某方有好处，不用来评价歌曲的好坏。"}, {"text": "他的字写得很有利，老师都看得清。", "explanation": "这里应该用〈工整〉。有利表示对人或事有好处，评价字写得是否整齐应说“工整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样做有利大家的身心健康。", "corrected_sentence": "这样做有利于大家的身心健康。", "error_description": "搭配错误：“有利”后面带宾语要用“有利于”，“有利大家”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
