INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利", "is_correct": true, "explanation": "“不利”与“有利”互为反义，指情况对事情没有帮助。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容清晰程度，与“有利”没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描述态度，与“有利”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌美，与“有利”没有反义关系。"}], "correct_answer": "不利", "explanations": {"不利": "“不利”与“有利”互为反义，指情况对事情没有帮助。", "清楚": "“清楚”形容清晰程度，与“有利”没有反义关系。", "认真": "“认真”描述态度，与“有利”没有反义关系。", "漂亮": "“漂亮”形容外貌美，与“有利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
