INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有好处，有帮助的。", "primary_collocate": null, "pronunciation": "yǒu lì", "ipa": "joʊ˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "这对你的工作有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的条件对我们很有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，风向对他们有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息对公司有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书对写作有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有利的位置让他先看到了球。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找一个有利的时间。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春雨对种地有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天复习对考试有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的经验对这次谈判有利。", "target_word": "有利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利于", "label": "复合"}], "register": "中性", "sense_fingerprint": "条件或情况有帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '980ebab6-654b-45aa-acc6-731014f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示情况对事情有帮助，与“这对你的工作”的语境相符。"}, {"text": "有名", "is_correct": false, "explanation": "语义：“有名”说名气大，与“这对你的工作”的影响无关，句意不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不能用来评价“工作”的影响。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”形容态度，不能作为“这”对工作影响的评价。"}], "explanations": {"有利": "“有利”表示情况对事情有帮助，与“这对你的工作”的语境相符。", "有名": "语义：“有名”说名气大，与“这对你的工作”的影响无关，句意不通。", "漂亮": "搭配：“漂亮”形容外貌，不能用来评价“工作”的影响。", "认真": "语义：“认真”形容态度，不能作为“这”对工作影响的评价。"}, "sentence_index": 0, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她今天的样子很有利。", "explanation": "这里应该用〈漂亮〉。有利用于事情或条件带来的好处，不用来评价人的外貌。"}, {"text": "他有利地唱完了那首歌。", "explanation": "这里应该用〈动听〉。有利表示对人或事有好处，不用来修饰唱歌的效果，评价歌声应说“动听”。"}, {"text": "这支笔很有利，写字很快。", "explanation": "这里应该用〈好用〉。有利表示对人或事有好处，评价笔的好坏应说“好用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利", "is_correct": true, "explanation": "“有利”表示情况有帮助，与“找一个……的时间”的语境相符。"}, {"text": "有名", "is_correct": false, "explanation": "语义：“有名”说名气大，不能用来修饰“时间”。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌，时间不能用“好看”来形容。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”形容排列，与“找一个……的时间”的语义不搭。"}], "explanations": {"有利": "“有利”表示情况有帮助，与“找一个……的时间”的语境相符。", "有名": "语义：“有名”说名气大，不能用来修饰“时间”。", "好看": "搭配：“好看”形容外貌，时间不能用“好看”来形容。", "整齐": "语义：“整齐”形容排列，与“找一个……的时间”的语义不搭。"}, "sentence_index": 6, "correct_answer": "有利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雨让他的心情很有利。", "explanation": "这里应该用〈愉快〉。有利用于事情对某方有好处，不用来描述人的心情。"}, {"text": "这张床很有利，睡得很香。", "explanation": "这里应该用〈舒服〉。有利表示对人或事有好处，床躺着好不好应说“舒服”。"}, {"text": "我的弟弟很有利，每次考试都拿第一。", "explanation": "这里应该用〈优秀〉。有利表示事情对某方有好处，不用来评价人的成绩或能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个条件有利我们的谈判。", "corrected_sentence": "这个条件有利于我们的谈判。", "error_description": "搭配错误：“有利”后面带宾语要用“有利于”，“有利我们”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aac0c13-4afd-43dc-9a11-79d3f8e15a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
