INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94281, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乐团是很多人一起用乐器演奏音乐的队伍。", "primary_collocate": null, "pronunciation": "yuè tuán", "ipa": "ɥɛ˥˩ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "学校有一个小乐团。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐团有五十多个人。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在乐团里拉小提琴。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐团每个星期六下午练习。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐想加入城里的乐团。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐团的指挥站在台前。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个乐团用很多乐器演奏了一首老歌。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们组了一个乐团，在公园里表演。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐团里的人都很爱音乐。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的乐团明年要去北京。", "target_word": "乐团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}], "register": "中性", "sense_fingerprint": "很多人一起用乐器演奏音乐的队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3b207d-7c24-48b9-bf1d-e4e2b943cf6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94281, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监狱", "is_correct": false, "explanation": "语义：监狱是关押犯人的地方，学校里不会有这样的设施，与“学校有一个小”的语境冲突。"}, {"text": "乐团", "is_correct": true, "explanation": "乐团是由演奏者组成的团体，学校可以有一个小乐团，符合语境。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“小”不能修饰“大海”，“小大海”自相矛盾。"}, {"text": "坟墓", "is_correct": false, "explanation": "语义：坟墓与校园的语境完全不符，学校不会有坟墓。"}], "explanations": {"监狱": "语义：监狱是关押犯人的地方，学校里不会有这样的设施，与“学校有一个小”的语境冲突。", "乐团": "乐团是由演奏者组成的团体，学校可以有一个小乐团，符合语境。", "大海": "搭配：“小”不能修饰“大海”，“小大海”自相矛盾。", "坟墓": "语义：坟墓与校园的语境完全不符，学校不会有坟墓。"}, "sentence_index": 0, "correct_answer": "乐团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的乐团昨天到灾区去救人。", "explanation": "这里应该用〈救援队〉。救人是救援队的工作；乐团是用乐器演奏音乐的团体，不承担救援任务。"}, {"text": "我们的乐团每天给病人看病。", "explanation": "这里应该用〈医疗队〉。给病人看病是医疗队的工作；乐团是用乐器演奏音乐的团体，不给人看病。"}, {"text": "这个乐团的警察每天在街上抓小偷。", "explanation": "这里应该用〈警队〉。抓小偷是警队的工作；乐团指用乐器演奏音乐的团体，不指警察队伍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录音室", "is_correct": false, "explanation": "语义：录音室是录音的场所，不会用乐器演奏老歌。"}, {"text": "乐团", "is_correct": true, "explanation": "乐团是用乐器演奏的团体，“那个乐团演奏了一首老歌”符合语境。"}, {"text": "车队", "is_correct": false, "explanation": "语义：车队是行驶的车辆组成的队伍，不会用乐器演奏老歌。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借书阅读的地方，不能用乐器演奏。"}], "explanations": {"录音室": "语义：录音室是录音的场所，不会用乐器演奏老歌。", "乐团": "乐团是用乐器演奏的团体，“那个乐团演奏了一首老歌”符合语境。", "车队": "语义：车队是行驶的车辆组成的队伍，不会用乐器演奏老歌。", "图书馆": "语义：图书馆是借书阅读的地方，不能用乐器演奏。"}, "sentence_index": 6, "correct_answer": "乐团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个乐团明天晚上开门。", "explanation": "这里应该用〈音乐厅〉。开门的是场所；乐团指一群演奏者，不能“开门”。"}, {"text": "这个乐团去年在郊外种了很多玉米。", "explanation": "这里应该用〈农场〉。种玉米是农场的工作；乐团指用乐器演奏音乐的团体，不是农业生产单位。"}, {"text": "那个乐团每天在球场上踢球。", "explanation": "这里应该用〈球员〉。乐团用乐器演奏音乐，不踢球；踢球的是球员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟加入了一只乐团。", "corrected_sentence": "我弟弟加入了一个乐团。", "error_description": "量词错误：乐团应与“个”或“支”搭配，“只”用于动物。正确的说法是“加入了一个乐团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个乐团们很努力地练习。", "corrected_sentence": "这个乐团很努力地练习。", "error_description": "数量不一致：“这个”表单数，“们”表复数，二者矛盾。删去“们”，应说“这个乐团很努力地练习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b02ac858-00bf-4279-bca6-2da408780e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
