INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "历史家是研究和写过去发生的事的人。", "primary_collocate": null, "pronunciation": "lì shǐ jiā", "ipa": "li˥˩ ʂɻ̩˨˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他想长大以后当历史家。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位历史家写了很多书。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史家常常去图书馆找旧资料。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸的朋友是一位历史家。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史家说，那件事发生在一百年前。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个历史家研究中国的古代生活。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的历史家要先看很多材料，再写文章。", "target_word": "历史家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认识一位很有名的历史家。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位历史家今天要来我们学校讲话。", "target_word": "历史家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史家把旧信件里的故事写成了书。", "target_word": "历史家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "研究并写下过去发生的事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c3029d-e96d-4c4c-b73a-e938db1d64bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史家", "is_correct": true, "explanation": "历史家：研究和记录过去事情的人，符合“长大以后当”的句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能“长大以后当”它。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“当”后面要接职业或身份，“咖啡”不是职业。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不会“长大以后当”某种职业。"}], "explanations": {"历史家": "历史家：研究和记录过去事情的人，符合“长大以后当”的句意。", "石头": "语义：石头不是人，不能“长大以后当”它。", "咖啡": "搭配：“当”后面要接职业或身份，“咖啡”不是职业。", "河流": "语义：河流是自然景物，不会“长大以后当”某种职业。"}, "sentence_index": 0, "correct_answer": "历史家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位历史家每天在电视上报道今天的新闻。", "explanation": "这里应该用〈记者〉。历史家研究和写过去发生的事，报道今天的新闻是记者的工作。"}, {"text": "这位历史家预测了明年的经济形势。", "explanation": "这里应该用〈经济学家〉。历史家研究的是过去的事，预测明年的经济形势是经济学家的工作。"}, {"text": "这位历史家每天都预报明天的天气。", "explanation": "这里应该用〈天气预报员〉。历史家研究的是过去的事，不预报明天的天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史家", "is_correct": true, "explanation": "历史家：先看材料再写文章的研究者，符合句意。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作不需要看材料写文章，句中要的是研究者。"}, {"text": "木匠", "is_correct": false, "explanation": "语义：木匠做的是木工活，与先看材料再写文章的句意不符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机的工作是开车，不需要先看很多材料再写文章。"}], "explanations": {"历史家": "历史家：先看材料再写文章的研究者，符合句意。", "厨师": "语义：厨师的工作不需要看材料写文章，句中要的是研究者。", "木匠": "语义：木匠做的是木工活，与先看材料再写文章的句意不符。", "司机": "语义：司机的工作是开车，不需要先看很多材料再写文章。"}, "sentence_index": 6, "correct_answer": "历史家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位历史家研究化学反应。", "explanation": "这里应该用〈化学家〉。历史家研究和写过去发生的事，不研究化学反应。"}, {"text": "这位历史家给病人治病。", "explanation": "这里应该用〈医生〉。历史家研究历史，不给病人治病。"}, {"text": "这位历史家设计了一座大桥。", "explanation": "这里应该用〈工程师〉。历史家研究历史，不负责设计大桥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只历史家正在图书馆看旧报纸。", "corrected_sentence": "那位历史家正在图书馆看旧报纸。", "error_description": "错误：“那只历史家”。正确：“那位历史家”。“只”是动物的量词，说人要用“位”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位很有名历史家正在写一本新书。", "corrected_sentence": "那位很有名的历史家正在写一本新书。", "error_description": "错误：“很有名历史家”，漏掉了“的”。正确：“很有名的历史家”。“很有名”修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
