INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每月是每一个月都有。", "primary_collocate": null, "pronunciation": "měi yuè", "ipa": "meɪ˨˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我每月给妈妈寄一次钱。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每月发一次工资。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每月看两本书。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杂志每月出一期。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每月开一次家长会。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每月都去图书馆借书。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每月十号，我要交房租。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每月去医院检查一次身体。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店每月都有新的打折活动。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年有十二个月，我每月都读一本书。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每一个月都有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94285, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每月", "is_correct": true, "explanation": "正确：“每月”表示每个月都发生一次，与“一次”相合，能正确填入这里。"}, {"text": "每秒", "is_correct": false, "explanation": "语义：“每秒”的间隔太短，每秒寄一次钱与常理不符。"}, {"text": "每小时", "is_correct": false, "explanation": "搭配：寄钱通常按月或按年定期进行，不能与“每小时”搭配。"}, {"text": "每分钟", "is_correct": false, "explanation": "语义：每分钟给妈妈寄一次钱，周期过短，与句子的日常语境矛盾。"}], "explanations": {"每月": "正确：“每月”表示每个月都发生一次，与“一次”相合，能正确填入这里。", "每秒": "语义：“每秒”的间隔太短，每秒寄一次钱与常理不符。", "每小时": "搭配：寄钱通常按月或按年定期进行，不能与“每小时”搭配。", "每分钟": "语义：每分钟给妈妈寄一次钱，周期过短，与句子的日常语境矛盾。"}, "sentence_index": 0, "correct_answer": "每月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每月都在春节回老家。", "explanation": "〈每月〉指每个月都有一次，春节一年只有一次，这里应该用〈每年〉。"}, {"text": "我每月天天都跑步。", "explanation": "〈每月〉的周期与“天天”指的每一天相冲突，这里应该用〈每天〉。"}, {"text": "我的心脏每月跳八十下。", "explanation": "心跳的计量单位是〈每分钟〉，这里不能用〈每月〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每月", "is_correct": true, "explanation": "正确：“每月十号”表示每个月的十号，与“十号”相合，能正确填入这里。"}, {"text": "每周", "is_correct": false, "explanation": "搭配：“十号”指月中的日期，“每周”没有固定的十号，不能搭配。"}, {"text": "每小时", "is_correct": false, "explanation": "语义：“十号”是月中的日期，每小时没有固定的十号，与句意矛盾。"}, {"text": "每天", "is_correct": false, "explanation": "语义：每天都是十号不成立，日期每月才固定一次，与句意矛盾。"}], "explanations": {"每月": "正确：“每月十号”表示每个月的十号，与“十号”相合，能正确填入这里。", "每周": "搭配：“十号”指月中的日期，“每周”没有固定的十号，不能搭配。", "每小时": "语义：“十号”是月中的日期，每小时没有固定的十号，与句意矛盾。", "每天": "语义：每天都是十号不成立，日期每月才固定一次，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "每月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本周刊每月出一期。", "explanation": "〈周刊〉是每周出一期的刊物，这里的“每月”应改为〈每周〉。"}, {"text": "今天我每月打了三次电话。", "explanation": "〈每月〉指每个月重复一次的周期，与指当天的“今天”相冲突，这里应该用〈每天〉。"}, {"text": "这份晚报每月出一版。", "explanation": "〈晚报〉是每日出版的报纸，这里的“每月”应改为〈每日〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每月很给爸爸打电话。", "corrected_sentence": "我每月都给爸爸打电话。", "error_description": "错误形式：在“每月”后面用了程度副词“很”，说成“我每月很给爸爸打电话”。正确形式：“我每月都给爸爸打电话”。“很”一般修饰形容词，不能修饰“给爸爸打电话”这样的动作；表示每个月都这样做，可以用“都”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每月了给爸爸写一封信。", "corrected_sentence": "他每月给爸爸写一封信。", "error_description": "错误形式：“了”被放在了“每月”之后。正确形式：去掉“了”，说“他每月给爸爸写一封信”。原因：“了”是动态助词，不能附着在时间状语“每月”后面，这里也不需要表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
