INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每个月；每一个月份。", "primary_collocate": null, "pronunciation": "měi yuè", "ipa": "meɪ˨˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我每月的花费不太多。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每月的工资是八千块。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每月最后一天，公司会开会。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每月的电费要三百多块。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每月存一千块钱。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租每月要交一次。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李每月坐飞机回家。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每月能看几场电影？", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班每月考一次试。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每月都给我打电话。", "target_word": "每月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每个月份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1585aaa-08ed-4e88-aadc-77ee5176d44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每月", "is_correct": true, "explanation": "正确：“我每月的花费”指每个月的花费，与句意相合，能正确填入这里。"}, {"text": "每秒钟", "is_correct": false, "explanation": "语义：“每秒钟”的时间太短，不能用来说明个人的花费。"}, {"text": "每世纪", "is_correct": false, "explanation": "语义：“每世纪”的时间跨度过大，不能用来说明个人每月的花费。"}, {"text": "每百年", "is_correct": false, "explanation": "语义：“每百年”的周期与“不太多的花费”所描述的日常开销不符。"}], "explanations": {"每月": "正确：“我每月的花费”指每个月的花费，与句意相合，能正确填入这里。", "每秒钟": "语义：“每秒钟”的时间太短，不能用来说明个人的花费。", "每世纪": "语义：“每世纪”的时间跨度过大，不能用来说明个人每月的花费。", "每百年": "语义：“每百年”的周期与“不太多的花费”所描述的日常开销不符。"}, "sentence_index": 0, "correct_answer": "每月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每月的高考让他很紧张。", "explanation": "〈高考〉一年只举行一次，修饰它应该用〈每年的〉，不能用〈每月的〉。"}, {"text": "我们每月的周报都很长。", "explanation": "〈周报〉是每周一次的报告，修饰它应该用〈每周的〉，不能用〈每月的〉。"}, {"text": "我每月的早饭都在家吃。", "explanation": "〈早饭〉每天吃一次，修饰它应该用〈每天的〉，不能用〈每月的〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每月", "is_correct": true, "explanation": "正确：“小李每月坐飞机回家”表示每个月回家一次，与句意相合，能正确填入这里。"}, {"text": "每秒", "is_correct": false, "explanation": "语义：“每秒”的间隔太短，坐飞机回家不可能每秒发生。"}, {"text": "每小时", "is_correct": false, "explanation": "搭配：坐飞机回家是长途出行，不按小时计算。"}, {"text": "每分钟", "is_correct": false, "explanation": "语义：每分钟坐飞机回家与现实不符，周期过短。"}], "explanations": {"每月": "正确：“小李每月坐飞机回家”表示每个月回家一次，与句意相合，能正确填入这里。", "每秒": "语义：“每秒”的间隔太短，坐飞机回家不可能每秒发生。", "每小时": "搭配：坐飞机回家是长途出行，不按小时计算。", "每分钟": "语义：每分钟坐飞机回家与现实不符，周期过短。"}, "sentence_index": 6, "correct_answer": "每月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每月的生日是十二月五号。", "explanation": "〈生日〉一年只有一次，修饰它应该用〈每年的〉，这里的“每月的”不对。"}, {"text": "今天我每月坐了三次地铁。", "explanation": "〈每月〉指每个月重复，与指当天的“今天”相冲突，这里应该用〈每天〉。"}, {"text": "我们学校的毕业典礼每月举行一次。", "explanation": "〈毕业典礼〉一年只举行一次，这里应该用〈每年〉，不能用〈每月〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每月了的电费我都自己交。", "corrected_sentence": "每月的电费我都自己交。", "error_description": "错误形式：“了”被放在了“每月”之后。正确形式：去掉“了”，说“每月的电费我都自己交”。原因：“了”不能附着在时间词“每月”后面，这里也不表示动作完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每月的去看奶奶。", "corrected_sentence": "我每月去看奶奶。", "error_description": "错误形式：“我每月的去看奶奶”。正确形式：“我每月去看奶奶”。原因：这里“每月”作时间状语，修饰动词“去”，应直接放在动词前面；“的”用在修饰名词的成分后面，不能放在状语和动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d23ba3-1997-4f35-82ca-9cc82a876860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平淡", "is_correct": true, "explanation": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。"}, {"text": "高", "is_correct": false, "explanation": "无关：“高”指高度，与“浪漫”没有反义关系。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”指不软，与“浪漫”没有对立关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”指形状，与“浪漫”没有反义关系。"}], "correct_answer": "平淡", "explanations": {"平淡": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。", "高": "无关：“高”指高度，与“浪漫”没有反义关系。", "硬": "无关：“硬”指不软，与“浪漫”没有对立关系。", "圆": "无关：“圆”指形状，与“浪漫”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平淡", "is_correct": true, "explanation": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。"}, {"text": "大", "is_correct": false, "explanation": "无关：“大”指体积或范围，与“浪漫”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "无关：“深”指距离表面远或程度高，与“浪漫”没有对立关系。"}, {"text": "厚", "is_correct": false, "explanation": "无关：“厚”指两个表面之间距离大，与“浪漫”没有反义关系。"}], "correct_answer": "平淡", "explanations": {"平淡": "反义：“平淡”指缺少起伏和情趣，与“浪漫”让人觉得美好温暖的情调相对。", "大": "无关：“大”指体积或范围，与“浪漫”没有反义关系。", "深": "无关：“深”指距离表面远或程度高，与“浪漫”没有对立关系。", "厚": "无关：“厚”指两个表面之间距离大，与“浪漫”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "浪漫是让人觉得美好、温暖、像故事一样。", "primary_collocate": null, "pronunciation": "làng màn", "ipa": "laŋ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "他给妻子准备了一个很浪漫的晚餐。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的日落让这次旅行变得很浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雪中散步，觉得特别浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烛光、音乐和玫瑰，气氛真浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢浪漫的爱情故事。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在星空下向女朋友求婚，多浪漫啊！", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的灯光很柔和，环境非常浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老两口手拉着手走路，真浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪的夜晚，小城看起来很浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情人节那天，他送给她一束玫瑰，很浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪漫主义", "label": "复合"}, {"form": "浪漫史", "label": "复合"}], "register": "通用", "sense_fingerprint": "让人觉得美好温暖的、像故事一样的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：让人觉得美好、温暖，与给妻子准备晚餐的情境相符。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”表示庄重、不轻松，与为妻子准备温馨晚餐的情境不符。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等，不能说“锋利的晚餐”。"}, {"text": "凄凉", "is_correct": false, "explanation": "语义：“凄凉”表示悲伤冷清，与给妻子准备晚餐的温暖氛围相反。"}], "explanations": {"浪漫": "浪漫：让人觉得美好、温暖，与给妻子准备晚餐的情境相符。", "严肃": "语义：“严肃”表示庄重、不轻松，与为妻子准备温馨晚餐的情境不符。", "锋利": "搭配：“锋利”形容刀刃等，不能说“锋利的晚餐”。", "凄凉": "语义：“凄凉”表示悲伤冷清，与给妻子准备晚餐的温暖氛围相反。"}, "sentence_index": 0, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛只剩最后一分钟，场上的气氛真浪漫。", "explanation": "这里应该用〈紧张〉。浪漫指美好温暖的情调，比赛关头的气氛要说紧张。"}, {"text": "这份说明书写得很浪漫，每一步都很清楚。", "explanation": "这里应该用〈清晰〉。浪漫用于美好温暖的情调，文字的条理要说清晰。"}, {"text": "这间厨房很浪漫，地板亮得能照出人影。", "explanation": "这里应该用〈干净〉。浪漫指美好温暖的情调，卫生状况要说干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：营造美好温暖的氛围，与“灯光很柔和”相呼应。"}, {"text": "刺眼", "is_correct": false, "explanation": "语义：“刺眼”指光线强到晃眼，与“灯光很柔和”相矛盾。"}, {"text": "脏乱", "is_correct": false, "explanation": "语义：“脏乱”指不干净、杂乱，与“浪漫”的美好情调完全相反。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”多形容人的态度，不说“环境热情”。"}], "explanations": {"浪漫": "浪漫：营造美好温暖的氛围，与“灯光很柔和”相呼应。", "刺眼": "语义：“刺眼”指光线强到晃眼，与“灯光很柔和”相矛盾。", "脏乱": "语义：“脏乱”指不干净、杂乱，与“浪漫”的美好情调完全相反。", "热情": "搭配：“热情”多形容人的态度，不说“环境热情”。"}, "sentence_index": 6, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他讲的笑话很浪漫，逗得大家直笑。", "explanation": "这里应该用〈幽默〉。浪漫指美好温暖、带有恋爱情调，逗人发笑的笑话要说幽默。"}, {"text": "这份申请表填写起来很浪漫，要填十几页。", "explanation": "这里应该用〈繁琐〉。浪漫指美好温暖的情调，手续多要说繁琐。"}, {"text": "这次会议的气氛很浪漫，大家都在认真讨论。", "explanation": "这里应该用〈严肃〉。浪漫用于美好温暖的情调，会议场合的庄重气氛要说严肃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他浪漫的为妻子布置了房间。", "corrected_sentence": "他浪漫地为妻子布置了房间。", "error_description": "“浪漫”修饰动词“布置”，作状语要用“地”，不能用“的”；应说“浪漫地为妻子布置了房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把房间布置很浪漫。", "corrected_sentence": "他把房间布置得很浪漫。", "error_description": "“浪漫”作“布置”的结果补语，动词和补语之间要用“得”，不能省略；应说“布置得很浪漫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "反义：“现实”指不带想象色彩、贴近实际，与“浪漫”富有诗意、充满幻想相对。"}, {"text": "薄", "is_correct": false, "explanation": "无关：“薄”指厚度小，与“浪漫”没有反义关系。"}, {"text": "软", "is_correct": false, "explanation": "无关：“软”指容易变形，与“浪漫”没有对立关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”指形状，与“浪漫”没有反义关系。"}], "correct_answer": "现实", "explanations": {"现实": "反义：“现实”指不带想象色彩、贴近实际，与“浪漫”富有诗意、充满幻想相对。", "薄": "无关：“薄”指厚度小，与“浪漫”没有反义关系。", "软": "无关：“软”指容易变形，与“浪漫”没有对立关系。", "圆": "无关：“圆”指形状，与“浪漫”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
