INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "富有诗意，充满幻想和美好情趣。", "primary_collocate": null, "pronunciation": "làng màn", "ipa": "laŋ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "这位诗人的想法非常浪漫。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个浪漫的人，常常写诗给朋友。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画很浪漫，充满了幻想。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用浪漫的语言描写山水。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的歌词很浪漫，像一首诗。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻时他很浪漫，梦想环游世界。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说有浪漫的色彩，也有幻想。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他浪漫地说，想在月亮上盖一座房子。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天真又浪漫，常常对着云朵编故事。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个浪漫的画家，喜欢在月光下作画。", "target_word": "浪漫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪漫主义", "label": "复合"}, {"form": "浪漫史", "label": "复合"}], "register": "通用", "sense_fingerprint": "富有诗意、充满幻想的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：富有诗意、充满幻想，与“诗人的想法”相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气、地面，不能形容“想法”。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”形容人多的地方，不能形容“想法”。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃，不能形容“想法”。"}], "explanations": {"浪漫": "浪漫：富有诗意、充满幻想，与“诗人的想法”相符。", "潮湿": "搭配：“潮湿”形容空气、地面，不能形容“想法”。", "拥挤": "搭配：“拥挤”形容人多的地方，不能形容“想法”。", "锋利": "搭配：“锋利”形容刀刃，不能形容“想法”。"}, "sentence_index": 0, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车站里人来人往，场面很浪漫。", "explanation": "这里应该用〈繁忙〉。浪漫用于诗意或情调，车站的人流要说繁忙。"}, {"text": "这份实验数据很浪漫，每个数字都经过核对。", "explanation": "这里应该用〈精确〉。浪漫形容富有诗意或幻想，描述数据要说精确。"}, {"text": "这把工具很浪漫，平时常用来拧螺丝。", "explanation": "这里应该用〈实用〉。浪漫用于诗意或情调，描述工具的功能要说实用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪漫", "is_correct": true, "explanation": "浪漫：富有诗意和想象的色彩，与“也有幻想”相呼应。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”多形容味道或言辞，不用来修饰“色彩”。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”表示缺乏感情，与“也有幻想”的美好想象相冲突。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”多形容质地、表面，不说“粗糙的色彩”。"}], "explanations": {"浪漫": "浪漫：富有诗意和想象的色彩，与“也有幻想”相呼应。", "辛辣": "搭配：“辛辣”多形容味道或言辞，不用来修饰“色彩”。", "冷漠": "语义：“冷漠”表示缺乏感情，与“也有幻想”的美好想象相冲突。", "粗糙": "搭配：“粗糙”多形容质地、表面，不说“粗糙的色彩”。"}, "sentence_index": 6, "correct_answer": "浪漫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子很浪漫，冷得直打哆嗦。", "explanation": "这里应该用〈寒冷〉。浪漫用于诗意或情调，天气冷要说寒冷。"}, {"text": "这份调查报告很浪漫，每一项结论都有依据。", "explanation": "这里应该用〈客观〉。浪漫用于诗意或幻想，描述报告的结论要说客观。"}, {"text": "这台机器很浪漫，运行速度非常快。", "explanation": "这里应该用〈高效〉。浪漫形容富有诗意的情调，描述机器的运行速度要说高效。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的画比他的很浪漫，充满了幻想。", "corrected_sentence": "她的画比他的浪漫，充满了幻想。", "error_description": "比较句错误：“比”字句中形容词前不能再用“很”；应说“比他的浪漫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜色降临，小镇慢慢变得浪漫得起来。", "corrected_sentence": "夜色降临，小镇慢慢变得浪漫起来。", "error_description": "重复的“得”：“变得”已带“得”，后面不能再加“得”；应说“变得浪漫起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
