INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海边或江河边供船舶停靠、装卸货物的地方。", "primary_collocate": null, "pronunciation": "gǎng kǒu", "ipa": "kɑŋ˨˩˦ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "港口每天都有货船来卸货。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条江边有一个新港口。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在港口装卸货物。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口一年运很多货。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大米从港口运进了城里。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香港有一个世界有名的港口。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的港口晚上很安静。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车排队等着进港口。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为大雾，港口关了一天。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在江边的港口当工人。", "target_word": "港口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个港口", "label": "量词"}, {"form": "一座港口", "label": "量词"}, {"form": "港口城市", "label": "复合"}], "register": "中性", "sense_fingerprint": "海边江边供船舶停靠和装卸货物的设施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b63a56-8ab2-40e1-be94-f37f7483128e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学校", "is_correct": false, "explanation": "语义：学校不是货船卸货的地方，货船不会每天来学校卸货。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不接收货船，“每天都有货船来卸货”在意义上不合理。"}, {"text": "港口", "is_correct": true, "explanation": "正确。海边或江河边供船舶停靠、装卸货物的地方就是港口。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：货船来卸货不说“车站”，车站是火车、汽车停靠的地方。"}], "explanations": {"学校": "语义：学校不是货船卸货的地方，货船不会每天来学校卸货。", "医院": "语义：医院不接收货船，“每天都有货船来卸货”在意义上不合理。", "港口": "正确。海边或江河边供船舶停靠、装卸货物的地方就是港口。", "车站": "搭配：货船来卸货不说“车站”，车站是火车、汽车停靠的地方。"}, "sentence_index": 0, "correct_answer": "港口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在港口等飞机。", "explanation": "这里应该用〈机场〉。港口供船靠岸，等飞机应该去机场。"}, {"text": "我昨天在港口看了一场电影。", "explanation": "这里应该用〈电影院〉。港口是船靠岸、装卸货物的地方，看电影要去电影院。"}, {"text": "我每天在港口坐火车上学。", "explanation": "这里应该用〈车站〉。港口是船靠岸的地方，坐火车要去车站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜市", "is_correct": false, "explanation": "语义：夜市晚上通常很热闹，与“安静”的语境冲突。"}, {"text": "港口", "is_correct": true, "explanation": "正确。海边的港口晚上较为安静，符合句子语境。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会通常很热闹，与“安静”的语境冲突。"}, {"text": "足球赛", "is_correct": false, "explanation": "语义：比赛通常很热闹，“海边的足球赛晚上很安静”在意义上不合理。"}], "explanations": {"夜市": "语义：夜市晚上通常很热闹，与“安静”的语境冲突。", "港口": "正确。海边的港口晚上较为安静，符合句子语境。", "演唱会": "语义：演唱会通常很热闹，与“安静”的语境冲突。", "足球赛": "语义：比赛通常很热闹，“海边的足球赛晚上很安静”在意义上不合理。"}, "sentence_index": 6, "correct_answer": "港口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我感冒了，今天在港口看病。", "explanation": "这里应该用〈医院〉。港口是船靠岸、装卸货物的地方，看病要去医院。"}, {"text": "我下午在港口上了一节数学课。", "explanation": "这里应该用〈学校〉。港口是船停靠、装卸货物的地方，上课要去学校。"}, {"text": "我想在港口买一本词典。", "explanation": "这里应该用〈书店〉。港口是船停靠的地方，买词典要去书店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "江边新建了一条港口。", "corrected_sentence": "江边新建了一座港口。", "error_description": "量词错误：“港口”应用“座”或“个”，不用“条”（“条”多用于细长的东西）。应把“一条港口”改为“一座港口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海边有一张很大的港口。", "corrected_sentence": "海边有一个很大的港口。", "error_description": "量词错误：“港口”用“个”或“座”，不用“张”（“张”用于纸、桌子等平面的东西）。应把“一张港口”改为“一个港口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
