INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94293, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "片段是一件很长的事里的一小段。", "primary_collocate": null, "pronunciation": "piàn duàn", "ipa": "pʰjɛn˥˩ twan˥˩", "syllable_count": 2, "sentences": [{"text": "我常想起童年生活的片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天的事我只记得几个片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些生活片段让她很感动。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了旅行中的几个有趣片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回忆里的片段慢慢变得不清楚了。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争的片段还留在老人的记忆里。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一天的生活片段写进了日记。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年的片段，我都舍不得忘。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用照片记录下旅行的每个片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聊起了大学时代的一些片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片断", "label": "异形"}, {"form": "个", "label": "量词"}], "register": "通用", "sense_fingerprint": "生活、经历、回忆中的一小段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "片段", "is_correct": true, "explanation": "“片段”指童年生活中截取的一小段，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：童年生活不能标价，“价格”与句意不合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于人的体形，不能用来指童年生活。"}, {"text": "工资", "is_correct": false, "explanation": "语义：童年生活里没有工资，“工资”与句意不合。"}], "explanations": {"片段": "“片段”指童年生活中截取的一小段，符合句意。", "价格": "语义：童年生活不能标价，“价格”与句意不合。", "身材": "体貌：“身材”只用于人的体形，不能用来指童年生活。", "工资": "语义：童年生活里没有工资，“工资”与句意不合。"}, "sentence_index": 0, "correct_answer": "片段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她回忆起一匹童年的片段。", "explanation": "这里应该用〈段〉或〈个〉。〈匹〉用于马、布等，不用于片段。"}, {"text": "这个片段是整本书，从第一页写到最后一页。", "explanation": "“片段”指长事中的一小段，不能说它就是整本书，应改为〈这本书〉。"}, {"text": "他回忆起一颗童年的片段。", "explanation": "这里应该用〈段〉或〈个〉。〈颗〉用于粒状或球形的东西，不用于片段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "片段", "is_correct": true, "explanation": "“片段”指生活中截取的一小段，可以写进日记，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人的身体，不能说生活有身高。"}, {"text": "车票", "is_correct": false, "explanation": "语义：“车票”不是生活中可以写进日记的内容，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：生活不能称体重，“体重”与句意不合。"}], "explanations": {"片段": "“片段”指生活中截取的一小段，可以写进日记，符合句意。", "身高": "体貌：“身高”只用于人的身体，不能说生活有身高。", "车票": "语义：“车票”不是生活中可以写进日记的内容，句意不通。", "体重": "语义：生活不能称体重，“体重”与句意不合。"}, "sentence_index": 6, "correct_answer": "片段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段片段从出生写到死亡，是他的整段人生。", "explanation": "这里应该用〈传记〉。〈片段〉指一件长事中的一小段，不能指从出生到死亡的完整经历。"}, {"text": "他的片段从出生到死亡都没有遗漏。", "explanation": "这里应该用〈生平〉。〈片段〉只是长事中的一小部分，不能说从出生到死亡没有遗漏。"}, {"text": "他的片段从头到尾都写在这本书里。", "explanation": "这里应该用〈一生〉。〈片段〉只是长事中的一小段，不能指从头到尾的完整一生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把童年的一张片段讲给我听。", "corrected_sentence": "她把童年的一个片段讲给我听。", "error_description": "量词用错了。“片段”前应用“个”或“段”，“张”用于纸张、照片等平面的东西，不用于片段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们聊起了大学时代那些很开心片段。", "corrected_sentence": "我们聊起了大学时代那些很开心的片段。", "error_description": "“很开心”修饰“片段”时中间要加“的”，应说“很开心的片段”，不能说“很开心片段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
