INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整体中的一个小段落。", "primary_collocate": null, "pronunciation": "piàn duàn", "ipa": "pʰjɛn˥˩ twan˥˩", "syllable_count": 2, "sentences": [{"text": "老师给我们读了课文里的一个片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影片段很有意思。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这首歌的片段再放一次。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只听到了他讲话的片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段视频只是比赛的一个片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上背了那篇文章的片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我看了电视剧里最感人的片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我只读过几个片段。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把这个音乐片段唱给我听吗？", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说中有一个片段写的是春天。", "target_word": "片段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片断", "label": "异形"}, {"form": "个", "label": "量词"}], "register": "通用", "sense_fingerprint": "文章、影片、音乐等整体中截取的一小段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "片段", "is_correct": true, "explanation": "“片段”指课文中截取的一小段，符合句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“读”的对象是文字，“歌曲”是用来唱的，不能用“读”。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“读”不能接“照片”，照片是用来看的，不能被朗读。"}, {"text": "手机", "is_correct": false, "explanation": "语义：课文里的内容是文字，不会出现“手机”这样的实物被朗读。"}], "explanations": {"片段": "“片段”指课文中截取的一小段，符合句意。", "歌曲": "搭配：“读”的对象是文字，“歌曲”是用来唱的，不能用“读”。", "照片": "搭配：“读”不能接“照片”，照片是用来看的，不能被朗读。", "手机": "语义：课文里的内容是文字，不会出现“手机”这样的实物被朗读。"}, "sentence_index": 0, "correct_answer": "片段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗户被风吹碎了，地上全是片段。", "explanation": "这里应该用〈碎片〉。片段指整体中截取的一小段，不用来指摔碎的东西。"}, {"text": "他离开后，屋子里安静了一个片段。", "explanation": "这里应该用〈片刻〉。〈片段〉指整体中截取的一小段，不表示时间很短的一会儿，不能用来计量安静的时长。"}, {"text": "他讲的故事很长，我只听了一个片段就听完了整个故事。", "explanation": "〈片段〉指整体中的一小部分，“听了一个片段就听完了整个故事”自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "片段", "is_correct": true, "explanation": "“片段”指电视剧中截取的一小段，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“感人”修饰情节、场面，不能修饰“价格”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能使人感动，“感人的天气”句意不通。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：电视剧里能感人的是情节，不会是菜单。"}], "explanations": {"片段": "“片段”指电视剧中截取的一小段，符合句意。", "价格": "搭配：“感人”修饰情节、场面，不能修饰“价格”。", "天气": "语义：天气不能使人感动，“感人的天气”句意不通。", "菜单": "语义：电视剧里能感人的是情节，不会是菜单。"}, "sentence_index": 6, "correct_answer": "片段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屏幕上闪过一张很短的片段。", "explanation": "这里应该用〈段〉或〈个〉。〈张〉用于纸张、照片等平面的东西，不用于片段。"}, {"text": "老人给我讲了一颗很有意思的片段。", "explanation": "这里应该用〈段〉或〈个〉。〈颗〉用于粒状或球形的东西，不用于片段。"}, {"text": "书架上放着一根长长的片段。", "explanation": "这里应该用〈段〉或〈个〉。〈根〉用于细长的东西，不用于片段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把比赛的一张精彩片段剪下来给我看。", "corrected_sentence": "他把比赛的一个精彩片段剪下来给我看。", "error_description": "量词用错了。“片段”前应用“个”或“段”，“张”用于纸张、照片等平面的东西，不用来修饰片段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我看了一个很长片段。", "corrected_sentence": "他给我看了一个很长的片段。", "error_description": "“很长”修饰“片段”时中间要加“的”，应说“很长的片段”，不能说“很长片段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
