INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "狮子是一种很大的野兽，脖子上有长毛，叫声很响。", "primary_collocate": null, "pronunciation": "shī zi", "ipa": "ʂɻ̩⁵⁵ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "狮子的叫声很响，远处都能听到。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狮子的脖子上有很长的毛。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的狮子正躺着睡觉。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩听见狮子叫，吓得哭了。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狮子看见一只小鹿，慢慢走了过去。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在笼子外面看狮子吃肉。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头狮子又大又凶，大家都不敢靠近。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一头狮子，脖子上全是长毛。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，狮子的叫声让我睡不着。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次在动物园里看到真正的狮子。", "target_word": "狮子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}, {"form": "狮子狗", "label": "复合"}, {"form": "獅子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长毛、叫声很响的大野兽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '803b8d38-3b31-4866-a82b-2e7f4534b9dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94295, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "狮子", "is_correct": true, "explanation": "正确答案。狮子是一种大型猛兽。"}, {"text": "石子", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，石子指小石头，不是猛兽。"}, {"text": "柿子", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，柿子是一种水果。"}, {"text": "十字", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，第二个音节 zì 也变了声调，十字指交叉的形状。"}], "explanations": {"狮子": "正确答案。狮子是一种大型猛兽。", "石子": "shí（第二声）与 shī（第一声）声调不同，石子指小石头，不是猛兽。", "柿子": "shì（第四声）与 shī（第一声）声调不同，柿子是一种水果。", "十字": "shí（第二声）与 shī（第一声）声调不同，第二个音节 zì 也变了声调，十字指交叉的形状。"}, "sentence_index": null, "correct_answer": "狮子"}, "level_3": {"options": [{"text": "狮子", "is_correct": true, "explanation": "正确。“狮子”会发出很响的叫声，与句中的“叫声很响”相合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”不会发出叫声，与“叫声很响”矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“叫声”一般指动物的叫，汽车多说鸣笛声，不说“汽车的叫声”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会发出叫声，句意不通。"}], "explanations": {"狮子": "正确。“狮子”会发出很响的叫声，与句中的“叫声很响”相合。", "钢琴": "语义：“钢琴”不会发出叫声，与“叫声很响”矛盾。", "汽车": "搭配：“叫声”一般指动物的叫，汽车多说鸣笛声，不说“汽车的叫声”。", "窗户": "语义：窗户不会发出叫声，句意不通。"}, "sentence_index": 0, "correct_answer": "狮子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动物园里有一本狮子在睡觉。", "explanation": "这里应该用〈只〉。狮子是动物，量词要用“只”或“头”，“本”用于书籍。"}, {"text": "我们在草地上看见一条狮子。", "explanation": "这里应该用〈只〉。“条”多用于长条形的东西，不用于狮子。"}, {"text": "他画了一朵狮子。", "explanation": "这里应该用〈只〉或〈头〉。“朵”用于花、云等，不能用于狮子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狮子", "is_correct": true, "explanation": "正确。“这头狮子”体型大、性情凶，与“又大又凶”相合。"}, {"text": "小猪", "is_correct": false, "explanation": "体貌：“小猪”体型小，与“又大又凶”的描述相矛盾。"}, {"text": "小牛", "is_correct": false, "explanation": "体貌：“小牛”体型小，与句中的“又大”相矛盾。"}, {"text": "小羊", "is_correct": false, "explanation": "体貌：“小羊”体型小、性情温和，与“又大又凶”相矛盾。"}], "explanations": {"狮子": "正确。“这头狮子”体型大、性情凶，与“又大又凶”相合。", "小猪": "体貌：“小猪”体型小，与“又大又凶”的描述相矛盾。", "小牛": "体貌：“小牛”体型小，与句中的“又大”相矛盾。", "小羊": "体貌：“小羊”体型小、性情温和，与“又大又凶”相矛盾。"}, "sentence_index": 6, "correct_answer": "狮子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在路边看见一辆狮子。", "explanation": "这里应该用〈只〉。“辆”用于车，不能用于动物狮子。"}, {"text": "我在森林里看见一棵狮子。", "explanation": "这里应该用〈只〉。“棵”用于树木等植物，不能用于动物狮子。"}, {"text": "我们在山上看见一根狮子。", "explanation": "这里应该用〈只〉。“根”用于细长的东西，不用于狮子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处有一辆狮子在走。", "corrected_sentence": "远处有一只狮子在走。", "error_description": "错误形式：“一辆狮子”。正确形式：“一只狮子”。“辆”用于车辆，狮子是动物，量词应用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猎人狮子赶走了。", "corrected_sentence": "猎人把狮子赶走了。", "error_description": "错误形式：“猎人狮子赶走了”。正确形式：“猎人把狮子赶走了”。缺少“把”，“把”字短语要引出宾语“狮子”，并放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
