INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94298, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在一定时期内生产的产品的总价值。", "primary_collocate": null, "pronunciation": "chǎn zhí", "ipa": "ʈʂʰan˨˩˦ ʈʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "今年工厂的产值比去年高。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市去年的工业产值很高。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司一年的产值超过一亿元。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农业产值今年增加了百分之五。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂换了新机器，产值提高了不少。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受天气影响，这个月的产值下降了。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的产值每年都在增长。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个县的产值主要来自水果。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报告里写着，全年总产值是三亿元。", "target_word": "产值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小厂的产值不大，但是很稳。", "target_word": "产值", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "產值", "label": "繁体"}, {"form": "总产值", "label": "复合"}, {"form": "工业产值", "label": "复合"}], "register": "书面", "sense_fingerprint": "产值：一定时期内生产出的产品的总价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ce9a55-ce32-4de2-b1f7-ff56f8f8bde6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产值", "is_correct": true, "explanation": "正确。产值指一定时期内生产的产品总价值，与“工厂”和“比去年高”相合。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高用于人或动物，不能说工厂的身高。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，与工厂的生产情况无关。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学生缴纳的学习费用，与工厂无关。"}], "explanations": {"产值": "正确。产值指一定时期内生产的产品总价值，与“工厂”和“比去年高”相合。", "身高": "搭配：身高用于人或动物，不能说工厂的身高。", "体温": "语义：体温指身体的温度，与工厂的生产情况无关。", "学费": "语义：学费是学生缴纳的学习费用，与工厂无关。"}, "sentence_index": 0, "correct_answer": "产值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂今年的产值是十万台。", "explanation": "这里应该用〈产量〉。产值是按钱数计算的总价值，按台数计的要用产量。"}, {"text": "这个工人每个月的产值是五千元，他用来养家。", "explanation": "这里应该用〈工资〉。产值是生产的产品总价值，工人每月拿到的钱要说工资。"}, {"text": "这家商店去年的产值是五百万。", "explanation": "这里应该用〈营业额〉。产值指生产的总价值，商店卖货的总收入要说营业额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产值", "is_correct": true, "explanation": "正确。产值是生产的总价值，可以每年增长，与“他们的”和“每年都在增长”相合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：脾气是性格特点，不能说每年都在增长。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不用“增长”来描述。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音指声音的特质，不能用数量上的增长来说明。"}], "explanations": {"产值": "正确。产值是生产的总价值，可以每年增长，与“他们的”和“每年都在增长”相合。", "脾气": "搭配：脾气是性格特点，不能说每年都在增长。", "颜色": "搭配：颜色不用“增长”来描述。", "嗓音": "语义：嗓音指声音的特质，不能用数量上的增长来说明。"}, "sentence_index": 6, "correct_answer": "产值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的产值是两百元，我买不起。", "explanation": "这里应该用〈价格〉。产值是一定时期内生产的产品总价值，一件衣服卖多少钱要说价格。"}, {"text": "学校的产值今年增加了一倍。", "explanation": "这里应该用〈经费〉。产值只用于生产产品的地区或企业，学校的钱款要说经费。"}, {"text": "今年的产值是五万斤粮食。", "explanation": "这里应该用〈收成〉。产值是钱数，按斤计算的农作物产出要说收成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年全县的产值增长了十台。", "corrected_sentence": "今年全县的产值增长了百分之十。", "error_description": "错误：产值是钱数，不能用“台”计量，应说“增长了百分之十”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家厂的产值比去年多了三张。", "corrected_sentence": "这家厂的产值比去年多了三成。", "error_description": "错误：“张”用于纸张、桌子等，不能用来计量产值，应说“多了三成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
